-- Common editorial content and owner-only daily learning. Existing journals stay intact.
create schema if not exists learning_private;
revoke all on schema learning_private from public, anon;
grant usage on schema learning_private to authenticated;
create table public.learning_modules (
 id uuid primary key default gen_random_uuid(), position integer not null unique check(position>0),
 title text not null check(length(title) between 3 and 180), objective text not null default ''
);
create table public.learning_documents (
 id uuid primary key default gen_random_uuid(), module_id uuid not null references public.learning_modules(id),
 position integer not null unique check(position>0), revision integer not null default 1,
 status text not null default 'draft' check(status in ('draft','review','published','archived')),
 draft jsonb not null check(jsonb_typeof(draft)='object' and octet_length(draft::text)<60000),
 published jsonb, published_revision integer, updated_at timestamptz not null default now()
);
create table public.learning_versions (
 id bigint generated always as identity primary key, document_id uuid not null references public.learning_documents(id),
 revision integer not null, content jsonb not null, status text not null, editor uuid references auth.users(id),
 created_at timestamptz not null default now(), unique(document_id,revision)
);
create table public.learning_profiles (
 owner_id uuid primary key references auth.users(id) on delete cascade,
 time_zone text not null default 'America/Toronto', personalization boolean not null default false,
 consent_at timestamptz
);
create table public.learning_days (
 owner_id uuid not null references auth.users(id) on delete cascade, date date not null,
 document_id uuid not null references public.learning_documents(id), snapshot jsonb not null,
 revision integer not null default 1, notes jsonb not null default '{}', adaptation jsonb,
 questions jsonb not null default '[]', quiet boolean not null default false,
 reflection_skipped boolean not null default false, created_at timestamptz not null default now(),
 primary key(owner_id,date)
);
create table public.learning_completions (
 owner_id uuid not null references auth.users(id) on delete cascade,
 document_id uuid not null references public.learning_documents(id), completed_on date not null,
 snapshot jsonb not null, primary key(owner_id,document_id), unique(owner_id,completed_on)
);
create table public.learning_memories (
 id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users(id) on delete cascade,
 text text not null check(length(text) between 1 and 500), source_date date not null,
 category text not null, status text not null default 'suggested' check(status in ('suggested','confirmed')),
 created_at timestamptz not null default now()
);
create table learning_private.ai_requests (
 id uuid primary key default gen_random_uuid(), owner_id uuid not null references auth.users(id) on delete cascade,
 date date not null, kind text not null, created_at timestamptz not null default now(), finished boolean not null default false
);
create index learning_documents_module on public.learning_documents(module_id);
create index learning_versions_document on public.learning_versions(document_id,created_at desc);
create index learning_days_document on public.learning_days(document_id);
create index learning_completions_document on public.learning_completions(document_id);
create index learning_memories_owner on public.learning_memories(owner_id,source_date);
create index learning_requests_owner on learning_private.ai_requests(owner_id,created_at);
alter table learning_private.ai_requests enable row level security;
revoke all on learning_private.ai_requests from public,anon,authenticated;
DO $$declare t text; begin
 foreach t in array array['learning_modules','learning_documents','learning_versions'] loop
  execute format('alter table public.%I enable row level security',t);
  execute format('revoke all on public.%I from public,anon,authenticated',t);
  execute format('grant select on public.%I to authenticated',t);
  execute format('create policy editorial_admin on public.%I for select to authenticated using (public.current_user_admin())',t);
 end loop;
 foreach t in array array['learning_profiles','learning_days','learning_completions','learning_memories'] loop
  execute format('alter table public.%I enable row level security',t);
  execute format('revoke all on public.%I from public,anon,authenticated',t);
  execute format('grant select on public.%I to authenticated',t);
  execute format('create policy learning_owner on public.%I for select to authenticated using (public.current_user_allowed() and owner_id=(select auth.uid()))',t);
 end loop;
end $$;

create function learning_private.program_action(action text, payload jsonb default '{}') returns jsonb
language plpgsql security definer set search_path='' as $$
declare uid uuid:=auth.uid(); tz text; today date; target date; doc public.learning_documents;
 day public.learning_days; module public.learning_modules; result jsonb; current_note jsonb;
 request_id uuid; req learning_private.ai_requests; note_key text; v integer; p jsonb;
begin
 -- Every mutation and progress decision serializes on this owner's membership row.
 perform 1 from private.members where user_id=uid and active for update;
 if uid is null or not found or not public.current_user_allowed() then raise exception 'Forbidden' using errcode='42501'; end if;
 if octet_length(payload::text)>150000 then raise exception 'Invalid input'; end if;
 if action like 'admin_%' then
  if not public.current_user_admin() then raise exception 'Forbidden' using errcode='42501'; end if;
  if action='admin_module' then
   if length(trim(payload->>'title')) not between 3 and 180 then raise exception 'Invalid title'; end if;
   perform pg_advisory_xact_lock(730092);
   insert into public.learning_modules(position,title,objective) values((select coalesce(max(position),0)+1 from public.learning_modules),trim(payload->>'title'),coalesce(payload->>'objective',''));
  elsif action='admin_save' then
   if payload->>'id' is null then
    perform pg_advisory_xact_lock(730092);
    insert into public.learning_documents(module_id,position,draft,status) values((payload->>'moduleId')::uuid,(select coalesce(max(position),0)+1 from public.learning_documents),payload->'content','draft') returning * into doc;
   else
    select * into doc from public.learning_documents where id=(payload->>'id')::uuid for update;
    if doc.id is null or doc.revision<>(payload->>'expectedRevision')::integer then raise exception 'Conflict' using errcode='40001'; end if;
    update public.learning_documents set draft=payload->'content',revision=revision+1,status='draft',updated_at=now() where id=doc.id returning * into doc;
   end if;
   insert into public.learning_versions(document_id,revision,content,status,editor) values(doc.id,doc.revision,doc.draft,'draft',uid);
  elsif action in ('admin_review','admin_publish','admin_archive','admin_restore') then
   select * into doc from public.learning_documents where id=(payload->>'id')::uuid for update;
   if doc.id is null or doc.revision<>(payload->>'expectedRevision')::integer then raise exception 'Conflict' using errcode='40001'; end if;
   if action='admin_publish' and (length(doc.draft->>'body')<40 or jsonb_array_length(doc.draft->'sources')<1 or coalesce(payload->>'reviewed','false')<>'true') then raise exception 'Review required'; end if;
   p:=doc.draft;
   if action='admin_restore' then
    select content into p from public.learning_versions where document_id=doc.id and revision=(payload->>'version')::integer;
    if p is null then raise exception 'Version unavailable'; end if;
   end if;
   update public.learning_documents set revision=revision+1,draft=p,
    status=case action when 'admin_publish' then 'published' when 'admin_review' then 'review' when 'admin_archive' then 'archived' else 'draft' end,
    published=case when action='admin_publish' then draft when action='admin_archive' then null else published end,
    published_revision=case when action='admin_publish' then revision+1 else published_revision end,updated_at=now()
    where id=doc.id returning * into doc;
   insert into public.learning_versions(document_id,revision,content,status,editor) values(doc.id,doc.revision,doc.draft,doc.status,uid);
  elsif action='admin_versions' then
   return coalesce((select jsonb_agg(to_jsonb(x)-'editor' order by revision desc) from public.learning_versions x where document_id=(payload->>'id')::uuid),'[]');
  elsif action<>'admin_list' then raise exception 'Invalid action'; end if;
  return jsonb_build_object('modules',coalesce((select jsonb_agg(to_jsonb(m) order by position) from public.learning_modules m),'[]'),
   'documents',coalesce((select jsonb_agg(to_jsonb(d) order by position) from public.learning_documents d),'[]'));
 end if;
 tz:=coalesce(payload->>'timeZone','America/Toronto');
 if not exists(select 1 from pg_timezone_names where name=tz) then tz:='America/Toronto'; end if;
 insert into public.learning_profiles(owner_id,time_zone) values(uid,tz) on conflict do nothing;
 select time_zone into tz from public.learning_profiles where owner_id=uid;
 today:=(clock_timestamp() at time zone tz)::date;
 target:=coalesce((payload->>'date')::date,today);
 if action='preferences' then
  if exists(select 1 from public.personal_vaults where owner_id=uid) and (payload->>'enabled')::boolean then raise exception 'Vault migration required'; end if;
  update public.learning_profiles set personalization=(payload->>'enabled')::boolean,consent_at=case when (payload->>'enabled')::boolean then now() else null end where owner_id=uid;
 elsif action='memory' then
  if payload->>'operation'='forget' then delete from public.learning_memories where owner_id=uid and id=(payload->>'id')::uuid;
  elsif payload->>'operation'='forget_all' then delete from public.learning_memories where owner_id=uid;
  else update public.learning_memories set text=coalesce(payload->>'text',text),status='confirmed' where owner_id=uid and id=(payload->>'id')::uuid; end if;
 elsif action='ensure' and target=today then
  if not exists(select 1 from public.learning_days where owner_id=uid and date=target) then
   -- Resume the exact unfinished snapshot; new content cannot move an existing milestone.
   select * into day from public.learning_days d where owner_id=uid and not exists(select 1 from public.learning_completions c where c.owner_id=uid and c.document_id=d.document_id) order by date desc limit 1;
   if day.document_id is not null then
    insert into public.learning_days(owner_id,date,document_id,snapshot) values(uid,today,day.document_id,day.snapshot);
   elsif not exists(select 1 from public.learning_completions where owner_id=uid and completed_on>=today) then
    select * into doc from public.learning_documents d where published is not null and not exists(select 1 from public.learning_completions c where c.owner_id=uid and c.document_id=d.id) order by position limit 1;
    if doc.id is not null then
     select * into module from public.learning_modules where id=doc.module_id;
     insert into public.learning_days(owner_id,date,document_id,snapshot) values(uid,today,doc.id,doc.published||jsonb_build_object('moduleTitle',module.title,'version',doc.published_revision));
    end if;
   end if;
  end if;
 elsif action='complete' then
  select * into day from public.learning_days where owner_id=uid and date=target for update;
  if day.document_id is null or target<>today then raise exception 'Today only' using errcode='40001'; end if;
  if not exists(select 1 from public.learning_completions where owner_id=uid and document_id=day.document_id) then
   if exists(select 1 from public.learning_completions where owner_id=uid and completed_on>=today) then raise exception 'One step per day' using errcode='40001'; end if;
   insert into public.learning_completions values(uid,day.document_id,today,day.snapshot);
  end if;
 elsif action='note' then
  if exists(select 1 from public.personal_vaults where owner_id=uid) then raise exception 'Vault migration required'; end if;
  note_key:=payload->>'key';
  if length(coalesce(payload->>'text',''))>20000 or length(note_key)>80 then raise exception 'Invalid note'; end if;
  select * into day from public.learning_days where owner_id=uid and date=target for update;
  if day.document_id is null then raise exception 'Day unavailable'; end if;
  if note_key<>'reflection' and not exists(select 1 from jsonb_array_elements(day.questions) q where q->>'id'=note_key) then raise exception 'Question unavailable'; end if;
  current_note:=day.notes->note_key;
  v:=coalesce((current_note->>'revision')::integer,0);
  if v<>(payload->>'expectedRevision')::integer then
   if current_note->>'text'=payload->>'text' then return current_note; end if;
   raise exception 'Note conflict' using errcode='40001';
  end if;
  p:=jsonb_build_object('text',payload->>'text','revision',v+1);
  update public.learning_days set notes=jsonb_set(notes,array[note_key],p),revision=revision+1,reflection_skipped=false where owner_id=uid and date=target;
  -- Old interpretations become invalid when the source note changes.
  delete from public.learning_memories where owner_id=uid and source_date=target and status='suggested';
  return p;
 elsif action in ('quiet','skip') then
  update public.learning_days set quiet=case when action='quiet' then (payload->>'enabled')::boolean else quiet end,
   reflection_skipped=case when action='skip' then (payload->>'enabled')::boolean else reflection_skipped end where owner_id=uid and date=target;
 elsif action='reserve_ai' then
  if exists(select 1 from public.personal_vaults where owner_id=uid) or not exists(select 1 from public.learning_profiles where owner_id=uid and personalization) then raise exception 'Personalization disabled' using errcode='42501'; end if;
  select * into day from public.learning_days where owner_id=uid and date=target;
  if day.document_id is null or day.quiet or target<>today then raise exception 'Unavailable'; end if;
  if (select count(*) from learning_private.ai_requests where owner_id=uid and date=today)>=4 or exists(select 1 from learning_private.ai_requests where owner_id=uid and not finished and created_at>now()-interval '2 minutes') then raise exception 'Rate limit' using errcode='53300'; end if;
  insert into learning_private.ai_requests(owner_id,date,kind) values(uid,target,coalesce(payload->>'kind','followup')) returning id into request_id;
  return jsonb_build_object('requestId',request_id,'day',to_jsonb(day)-'owner_id');
 elsif action='finish_ai' then
  select * into req from learning_private.ai_requests where id=(payload->>'requestId')::uuid and owner_id=uid and not finished for update;
  if req.id is null then raise exception 'Request unavailable'; end if;
  update learning_private.ai_requests set finished=true where id=req.id;
  if not exists(select 1 from public.learning_profiles where owner_id=uid and personalization) or exists(select 1 from public.personal_vaults where owner_id=uid) then raise exception 'Personalization disabled' using errcode='42501'; end if;
  select * into day from public.learning_days where owner_id=uid and date=req.date for update;
  if day.quiet or day.revision<>(payload->>'expectedRevision')::integer then return jsonb_build_object('stale',true); end if;
  p:=payload->'result';
  if length(p->>'question') not between 10 and 500 or length(p->>'introduction')>700 or length(p->>'experiment')>700 then raise exception 'Invalid result'; end if;
  update public.learning_days set adaptation=case when adaptation is null then jsonb_build_object('introduction',p->>'introduction','experiment',p->>'experiment') else adaptation end,
   questions=questions||jsonb_build_array(jsonb_build_object('id',gen_random_uuid(),'text',p->>'question','source','assistant','createdAt',now())),revision=revision+1 where owner_id=uid and date=req.date;
  for current_note in select * from jsonb_array_elements(coalesce(p->'memories','[]')) loop
   if (current_note->>'sourceDate')::date<=today and (select count(*) from public.learning_memories where owner_id=uid)<60 then
    insert into public.learning_memories(owner_id,text,source_date,category) values(uid,current_note->>'text',(current_note->>'sourceDate')::date,current_note->>'category');
   end if;
  end loop;
 elsif action not in ('state','ensure') then raise exception 'Invalid action'; end if;
 select * into day from public.learning_days where owner_id=uid and date=target;
 if day.document_id is not null then
  select m.* into module from public.learning_modules m join public.learning_documents d on d.module_id=m.id where d.id=day.document_id;
 end if;
 result:=jsonb_build_object('today',today,'timeZone',tz,'personalization',(select personalization from public.learning_profiles where owner_id=uid),
  'day',case when day.document_id is null then null else to_jsonb(day)-'owner_id' end,
  'dates',coalesce((select jsonb_agg(date order by date desc) from public.learning_days where owner_id=uid),'[]'),
  'pages',coalesce((select jsonb_agg(jsonb_build_object('date',date,'title',snapshot->>'title','journalDone',exists(select 1 from jsonb_each(notes) n where length(trim(n.value->>'text'))>0)) order by date desc) from public.learning_days where owner_id=uid),'[]'),
  'completed',coalesce((select jsonb_agg(jsonb_build_object('document_id',document_id,'completed_on',completed_on,'title',snapshot->>'title','moduleTitle',snapshot->>'moduleTitle') order by completed_on) from public.learning_completions where owner_id=uid),'[]'),
  'memories',coalesce((select jsonb_agg(to_jsonb(m)-'owner_id' order by created_at desc) from public.learning_memories m where owner_id=uid),'[]'),
  'currentModule',case when module.id is null then null else jsonb_build_object('title',module.title,
   'completed',(select count(*) from public.learning_completions c join public.learning_documents d on d.id=c.document_id where c.owner_id=uid and d.module_id=module.id),
   'total',(select count(*) from public.learning_documents where module_id=module.id and published is not null)) end,
  'waiting',exists(select 1 from public.learning_completions where owner_id=uid and completed_on>=today),
  'encrypted',exists(select 1 from public.personal_vaults where owner_id=uid));
 return result;
end $$;
revoke all on function learning_private.program_action(text,jsonb) from public,anon;
grant execute on function learning_private.program_action(text,jsonb) to authenticated;
create function public.learning_action(action text,payload jsonb default '{}') returns jsonb language sql security invoker set search_path='' as $$ select learning_private.program_action(action,payload) $$;
revoke all on function public.learning_action(text,jsonb) from public,anon;
grant execute on function public.learning_action(text,jsonb) to authenticated;

-- Client-side decrypted migration. Old envelope retained privately until verified;
-- stale encrypted tabs can no longer overwrite the migrated standard workspace.
create table learning_private.vault_migrations (
 owner_id uuid primary key references auth.users(id) on delete cascade, envelope jsonb not null, migrated_at timestamptz not null default now()
);
alter table learning_private.vault_migrations enable row level security;
revoke all on learning_private.vault_migrations from public,anon,authenticated;
create function learning_private.migrate_vault(expected_revision integer,personal jsonb) returns integer language plpgsql security definer set search_path='' as $$
declare uid uuid:=auth.uid(); sealed jsonb; actual integer; rev integer;
begin
 perform 1 from private.members where user_id=uid and active for update;
 if uid is null or not found or not public.current_user_allowed() then raise exception 'Forbidden' using errcode='42501'; end if;
 select envelope,revision into sealed,actual from public.personal_vaults where owner_id=uid for update;
 if actual is null or actual<>expected_revision then raise exception 'Conflict' using errcode='40001'; end if;
 if not coalesce(personal ?& array['journal','weights','plans','slots','pantry','preferences','documents','groceryChecks','program'],false) or octet_length(personal::text)>3000000 then raise exception 'Invalid workspace'; end if;
 insert into learning_private.vault_migrations(owner_id,envelope) values(uid,sealed) on conflict(owner_id) do update set envelope=excluded.envelope,migrated_at=now();
 delete from public.personal_vaults where owner_id=uid;
 select coalesce(revision,0) into rev from public.standard_workspaces where owner_id=uid;
 rev:=public.save_standard_workspace(coalesce(rev,0),personal);
 return rev;
end $$;
revoke all on function learning_private.migrate_vault(integer,jsonb) from public,anon;
grant execute on function learning_private.migrate_vault(integer,jsonb) to authenticated;
create function public.migrate_learning_vault(expected_revision integer,personal jsonb) returns integer language sql security invoker set search_path='' as $$ select learning_private.migrate_vault(expected_revision,personal) $$;
revoke all on function public.migrate_learning_vault(integer,jsonb) from public,anon;
grant execute on function public.migrate_learning_vault(integer,jsonb) to authenticated;
create function learning_private.no_new_vaults() returns trigger language plpgsql set search_path='' as $$
begin
 if not exists(select 1 from public.personal_vaults where owner_id=new.owner_id) then raise exception 'New vault creation retired' using errcode='42501'; end if;
 return new;
end $$;
create trigger no_new_vaults before insert on public.personal_vaults for each row execute function learning_private.no_new_vaults();
insert into public.learning_modules(id,position,title,objective) values('ad1525ce-f011-5dbe-9421-16a54463f7a1','1','Trouver ses raisons de changer','choisir ce qui compte pour vous. Les approches professionnelles privilégient des objectifs négociés et une démarche adaptée à la personne. Les raisons personnelles ne remplacent pas les ressources matérielles ni les soins nécessaires.') on conflict do nothing;
insert into public.learning_modules(id,position,title,objective) values('9d515df3-65ac-5817-a92a-411e3b8320a8','2','Comprendre comment les habitudes fonctionnent','rendre un comportement praticable sans attendre une motivation constante. Les petites actions et les plans de rechange sont utiles ; il n’existe pas de délai universel de 21 jours pour former une habitude. La durée varie beaucoup.') on conflict do nothing;
insert into public.learning_modules(id,position,title,objective) values('233277de-4b59-5f1d-84f7-24e7cbaef3fe','3','Observer ses comportements sans se juger','obtenir assez d’informations pour ajuster votre démarche. Le suivi alimentaire et du poids est utilisé dans les programmes comportementaux, mais son format doit rester tolérable. Un suivi qui devient obsessionnel mérite d’être simplifié ou suspendu.') on conflict do nothing;
insert into public.learning_modules(id,position,title,objective) values('6c30a0b7-ff23-54ff-a201-209dd1ba62a0','4','Comprendre les bases de l’alimentation','manger de façon suffisamment nourrissante et compatible avec vos besoins. Il n’existe pas une répartition de macronutriments idéale pour tous. Une alimentation doit aussi être abordable, culturellement acceptable et durable.') on conflict do nothing;
insert into public.learning_modules(id,position,title,objective) values('34c4b4e1-445a-57ca-9d47-c24e3ef74825','5','Utiliser la densité calorique sans moraliser les aliments','disposer d’un outil supplémentaire, sans réduire l’alimentation à un code de couleur. Les preuves sur la densité énergétique ne valident pas automatiquement un système commercial précis.') on conflict do nothing;
insert into public.learning_modules(id,position,title,objective) values('9048f60d-6d6d-5033-b6ea-f28ca21b63fb','6','Reconnaître la faim et le rassasiement','utiliser vos sensations comme informations, avec souplesse. La faim peut être discrète, perturbée par un traitement ou difficile à identifier. Un horaire de repas reste parfois nécessaire. Vous n’avez pas besoin de prouver votre faim pour avoir le droit de manger.') on conflict do nothing;
insert into public.learning_modules(id,position,title,objective) values('93683a7d-6b0a-56c3-813a-461fba3bbc58','7','Manger avec plus d’attention','mieux remarquer votre expérience. L’alimentation attentive peut aider certains comportements, mais ses effets propres sur le poids sont variables. Elle complète les autres moyens ; elle ne garantit pas une perte de poids.') on conflict do nothing;
insert into public.learning_modules(id,position,title,objective) values('66e3a23d-5b8b-507d-a534-0869a903a1c8','8','Reconnaître les pensées qui compliquent la démarche','remarquer les interprétations qui vous enferment. Les outils inspirés de la thérapie cognitivo-comportementale aident à examiner une pensée, sans prétendre que les difficultés matérielles ou médicales sont imaginaires.') on conflict do nothing;
insert into public.learning_modules(id,position,title,objective) values('a2bd1a05-e1a3-59b9-8f32-a3ae1fef827c','9','Construire un dialogue intérieur plus utile','vous soutenir avec des paroles exactes et praticables. L’autocompassion est prometteuse pour le vécu émotionnel des difficultés ; ce n’est pas une méthode de perte de poids démontrée à elle seule.') on conflict do nothing;
insert into public.learning_modules(id,position,title,objective) values('bff21190-bb55-50e7-8bd1-377d679a3143','10','Comprendre l’alimentation émotionnelle','diversifier les réponses à vos besoins. Manger pour se réconforter arrive à beaucoup de personnes. Cela devient particulièrement préoccupant lorsque la perte de contrôle, la détresse ou les compensations se répètent. Ces situations méritent des soins spécifiques.') on conflict do nothing;
insert into public.learning_modules(id,position,title,objective) values('3bd39602-79f9-5809-8d45-0afd2ea46156','11','Traverser les envies et les situations déclenchantes','augmenter votre marge de choix, sans faire de la résistance à la faim un objectif. Les stratégies ci-dessous sont des expériences personnelles ; aucune n’est une technique infaillible pour faire disparaître les envies.') on conflict do nothing;
insert into public.learning_modules(id,position,title,objective) values('6b8b7f8c-0304-50ee-a154-311ef18dac67','12','Organiser son environnement alimentaire','rendre les repas possibles avec vos ressources réelles. Une alimentation saine peut utiliser des produits surgelés, des conserves et des aliments préparés. Le budget, l’accès à une cuisine et la fatigue sont des paramètres de conception, pas des défauts personnels.') on conflict do nothing;
insert into public.learning_modules(id,position,title,objective) values('9513b194-feb2-589a-97f8-49167a5ce868','13','Préserver sa vie sociale et le plaisir de manger','participer aux repas partagés sans abandonner vos besoins. Le soutien social fait partie des moyens de maintien ; il doit être choisi, respectueux et concret.') on conflict do nothing;
insert into public.learning_modules(id,position,title,objective) values('9a61d466-f75f-5fe2-8ce1-1285dd53ec95','14','Bouger, dormir et gérer son stress','renforcer votre capacité à vivre vos journées. Les repères de santé publique sont des directions à adapter, pas des exigences de départ. Toute progression doit tenir compte de votre mobilité, de votre douleur et de votre santé.') on conflict do nothing;
insert into public.learning_modules(id,position,title,objective) values('55fb1826-8b34-51ff-bb6e-8fa53d50c471','15','Mesurer ses progrès et maintenir les changements','continuer à ajuster votre démarche. Les programmes étudiés comprennent souvent un accompagnement prolongé et plusieurs composantes. Lire un manuel ne reproduit pas à lui seul cette intensité de soutien.') on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('9b872e92-8f5a-5b1d-8ea8-6e16792f4ff5','ad1525ce-f011-5dbe-9421-16a54463f7a1',1,'published','{"title": "Définir son « pourquoi » personnel", "objective": "choisir ce qui compte pour vous. Les approches professionnelles privilégient des objectifs négociés et une démarche adaptée à la personne. Les raisons personnelles ne remplacent pas les ressources matérielles ni les soins nécessaires.", "body": "« Perdre du poids » décrit un résultat. Votre pourquoi raconte ce que ce résultat pourrait rendre possible : voyager avec plus de confort, réduire une douleur, retrouver une activité. Vous pouvez aussi commencer ces activités avant d’avoir atteint un certain poids.", "action": "complétez « J’aimerais prendre soin de ma santé pour pouvoir… », puis ajoutez une scène concrète. Exemple : « visiter un musée avec mon conjoint et profiter de la journée ». Gardez cette phrase visible, sans en faire une obligation quotidienne de motivation.", "question": "Qu’est-ce que cette idée change pour moi, dans une journée ordinaire?", "sources": [{"id": "S02", "title": "Vallis, Macklin et Russell-Mayhew, Obésité Canada, 2020.", "url": "https://obesitycanada.ca/wp-content/uploads/2025/03/10-Canadian-Adult-Obesity-CPG-Psych-Interventions.pdf"}, {"id": "S03", "title": "NICE, NG246, publié en 2025, version en ligne consultée.", "url": "https://www.nice.org.uk/guidance/ng246"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,'{"title": "Définir son « pourquoi » personnel", "objective": "choisir ce qui compte pour vous. Les approches professionnelles privilégient des objectifs négociés et une démarche adaptée à la personne. Les raisons personnelles ne remplacent pas les ressources matérielles ni les soins nécessaires.", "body": "« Perdre du poids » décrit un résultat. Votre pourquoi raconte ce que ce résultat pourrait rendre possible : voyager avec plus de confort, réduire une douleur, retrouver une activité. Vous pouvez aussi commencer ces activités avant d’avoir atteint un certain poids.", "action": "complétez « J’aimerais prendre soin de ma santé pour pouvoir… », puis ajoutez une scène concrète. Exemple : « visiter un musée avec mon conjoint et profiter de la journée ». Gardez cette phrase visible, sans en faire une obligation quotidienne de motivation.", "question": "Qu’est-ce que cette idée change pour moi, dans une journée ordinaire?", "sources": [{"id": "S02", "title": "Vallis, Macklin et Russell-Mayhew, Obésité Canada, 2020.", "url": "https://obesitycanada.ca/wp-content/uploads/2025/03/10-Canadian-Adult-Obesity-CPG-Psych-Interventions.pdf"}, {"id": "S03", "title": "NICE, NG246, publié en 2025, version en ligne consultée.", "url": "https://www.nice.org.uk/guidance/ng246"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,1) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('9233bef4-79b6-59fa-a501-87be5b5bf8cd','ad1525ce-f011-5dbe-9421-16a54463f7a1',2,'published','{"title": "Distinguer ses motivations des attentes des autres", "objective": "choisir ce qui compte pour vous. Les approches professionnelles privilégient des objectifs négociés et une démarche adaptée à la personne. Les raisons personnelles ne remplacent pas les ressources matérielles ni les soins nécessaires.", "body": "Un commentaire familial ou une comparaison sur les réseaux peut déclencher une démarche. Cela ne signifie pas que le projet correspond à vos besoins. Vous avez le droit de vouloir changer et celui de refuser une pression sur votre apparence.", "action": "faites deux colonnes : « ce que je souhaite » et « ce qu’on attend de moi ». Entourez une intention que vous conserveriez même si personne ne remarquait votre changement. Utilisez-la pour choisir votre première action.", "question": "Qu’est-ce que cette idée change pour moi, dans une journée ordinaire?", "sources": [{"id": "S02", "title": "Vallis, Macklin et Russell-Mayhew, Obésité Canada, 2020.", "url": "https://obesitycanada.ca/wp-content/uploads/2025/03/10-Canadian-Adult-Obesity-CPG-Psych-Interventions.pdf"}, {"id": "S03", "title": "NICE, NG246, publié en 2025, version en ligne consultée.", "url": "https://www.nice.org.uk/guidance/ng246"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,'{"title": "Distinguer ses motivations des attentes des autres", "objective": "choisir ce qui compte pour vous. Les approches professionnelles privilégient des objectifs négociés et une démarche adaptée à la personne. Les raisons personnelles ne remplacent pas les ressources matérielles ni les soins nécessaires.", "body": "Un commentaire familial ou une comparaison sur les réseaux peut déclencher une démarche. Cela ne signifie pas que le projet correspond à vos besoins. Vous avez le droit de vouloir changer et celui de refuser une pression sur votre apparence.", "action": "faites deux colonnes : « ce que je souhaite » et « ce qu’on attend de moi ». Entourez une intention que vous conserveriez même si personne ne remarquait votre changement. Utilisez-la pour choisir votre première action.", "question": "Qu’est-ce que cette idée change pour moi, dans une journée ordinaire?", "sources": [{"id": "S02", "title": "Vallis, Macklin et Russell-Mayhew, Obésité Canada, 2020.", "url": "https://obesitycanada.ca/wp-content/uploads/2025/03/10-Canadian-Adult-Obesity-CPG-Psych-Interventions.pdf"}, {"id": "S03", "title": "NICE, NG246, publié en 2025, version en ligne consultée.", "url": "https://www.nice.org.uk/guidance/ng246"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,1) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('603bf823-ead6-5494-a02f-48bee06146b1','ad1525ce-f011-5dbe-9421-16a54463f7a1',3,'published','{"title": "Relier sa démarche à ses valeurs", "objective": "choisir ce qui compte pour vous. Les approches professionnelles privilégient des objectifs négociés et une démarche adaptée à la personne. Les raisons personnelles ne remplacent pas les ressources matérielles ni les soins nécessaires.", "body": "Une valeur est une direction : autonomie, plaisir, présence familiale, découverte. Elle peut guider des actions même lorsque la balance reste stable. « Prendre soin de moi » peut vouloir dire préparer un repas, mais aussi dormir ou consulter.", "action": "choisissez deux valeurs et une action pour chacune. Pour « partage », proposez de cuisiner avec un proche ; pour « autonomie », apprenez un repas facile. Si votre plan contredit constamment vos valeurs, modifiez le plan.", "question": "Qu’est-ce que cette idée change pour moi, dans une journée ordinaire?", "sources": [{"id": "S02", "title": "Vallis, Macklin et Russell-Mayhew, Obésité Canada, 2020.", "url": "https://obesitycanada.ca/wp-content/uploads/2025/03/10-Canadian-Adult-Obesity-CPG-Psych-Interventions.pdf"}, {"id": "S03", "title": "NICE, NG246, publié en 2025, version en ligne consultée.", "url": "https://www.nice.org.uk/guidance/ng246"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,'{"title": "Relier sa démarche à ses valeurs", "objective": "choisir ce qui compte pour vous. Les approches professionnelles privilégient des objectifs négociés et une démarche adaptée à la personne. Les raisons personnelles ne remplacent pas les ressources matérielles ni les soins nécessaires.", "body": "Une valeur est une direction : autonomie, plaisir, présence familiale, découverte. Elle peut guider des actions même lorsque la balance reste stable. « Prendre soin de moi » peut vouloir dire préparer un repas, mais aussi dormir ou consulter.", "action": "choisissez deux valeurs et une action pour chacune. Pour « partage », proposez de cuisiner avec un proche ; pour « autonomie », apprenez un repas facile. Si votre plan contredit constamment vos valeurs, modifiez le plan.", "question": "Qu’est-ce que cette idée change pour moi, dans une journée ordinaire?", "sources": [{"id": "S02", "title": "Vallis, Macklin et Russell-Mayhew, Obésité Canada, 2020.", "url": "https://obesitycanada.ca/wp-content/uploads/2025/03/10-Canadian-Adult-Obesity-CPG-Psych-Interventions.pdf"}, {"id": "S03", "title": "NICE, NG246, publié en 2025, version en ligne consultée.", "url": "https://www.nice.org.uk/guidance/ng246"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,1) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('765567c7-b2ed-58ac-b2aa-c5165e18dfcd','ad1525ce-f011-5dbe-9421-16a54463f7a1',4,'published','{"title": "Imaginer les changements souhaités dans la vie quotidienne", "objective": "choisir ce qui compte pour vous. Les approches professionnelles privilégient des objectifs négociés et une démarche adaptée à la personne. Les raisons personnelles ne remplacent pas les ressources matérielles ni les soins nécessaires.", "body": "Une image de votre quotidien peut être plus utile qu’une silhouette idéale. Pensez à une journée ordinaire avec moins de difficultés : un dîner disponible, une marche agréable, un coucher moins tardif. L’objectif est d’identifier des besoins observables.", "action": "racontez cinq lignes d’un mardi qui se passe mieux. Soulignez un détail que vous pouvez tester cette semaine. « Je ne saute pas mon dîner » devient, par exemple, « je réserve un moment et je prévois une option rapide ».", "question": "Qu’est-ce que cette idée change pour moi, dans une journée ordinaire?", "sources": [{"id": "S02", "title": "Vallis, Macklin et Russell-Mayhew, Obésité Canada, 2020.", "url": "https://obesitycanada.ca/wp-content/uploads/2025/03/10-Canadian-Adult-Obesity-CPG-Psych-Interventions.pdf"}, {"id": "S03", "title": "NICE, NG246, publié en 2025, version en ligne consultée.", "url": "https://www.nice.org.uk/guidance/ng246"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,'{"title": "Imaginer les changements souhaités dans la vie quotidienne", "objective": "choisir ce qui compte pour vous. Les approches professionnelles privilégient des objectifs négociés et une démarche adaptée à la personne. Les raisons personnelles ne remplacent pas les ressources matérielles ni les soins nécessaires.", "body": "Une image de votre quotidien peut être plus utile qu’une silhouette idéale. Pensez à une journée ordinaire avec moins de difficultés : un dîner disponible, une marche agréable, un coucher moins tardif. L’objectif est d’identifier des besoins observables.", "action": "racontez cinq lignes d’un mardi qui se passe mieux. Soulignez un détail que vous pouvez tester cette semaine. « Je ne saute pas mon dîner » devient, par exemple, « je réserve un moment et je prévois une option rapide ».", "question": "Qu’est-ce que cette idée change pour moi, dans une journée ordinaire?", "sources": [{"id": "S02", "title": "Vallis, Macklin et Russell-Mayhew, Obésité Canada, 2020.", "url": "https://obesitycanada.ca/wp-content/uploads/2025/03/10-Canadian-Adult-Obesity-CPG-Psych-Interventions.pdf"}, {"id": "S03", "title": "NICE, NG246, publié en 2025, version en ligne consultée.", "url": "https://www.nice.org.uk/guidance/ng246"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,1) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('68c7f9dd-8246-53df-90ec-b10bb189b5a3','ad1525ce-f011-5dbe-9421-16a54463f7a1',5,'published','{"title": "Choisir des objectifs au-delà de la balance", "objective": "choisir ce qui compte pour vous. Les approches professionnelles privilégient des objectifs négociés et une démarche adaptée à la personne. Les raisons personnelles ne remplacent pas les ressources matérielles ni les soins nécessaires.", "body": "Le poids est une donnée possible parmi d’autres. L’endurance, le sommeil, le confort digestif, la relation à la nourriture et les mesures médicales peuvent aussi compter. Une amélioration n’a pas besoin d’être visible pour être réelle.", "action": "retenez trois indicateurs : un comportement, une sensation et une capacité. Exemple : préparer deux dîners, remarquer son énergie et marcher jusqu’à un commerce avec davantage de confort. Faites le point après quelques semaines, sans transformer chaque journée en contrôle.", "question": "Qu’est-ce que cette idée change pour moi, dans une journée ordinaire?", "sources": [{"id": "S02", "title": "Vallis, Macklin et Russell-Mayhew, Obésité Canada, 2020.", "url": "https://obesitycanada.ca/wp-content/uploads/2025/03/10-Canadian-Adult-Obesity-CPG-Psych-Interventions.pdf"}, {"id": "S03", "title": "NICE, NG246, publié en 2025, version en ligne consultée.", "url": "https://www.nice.org.uk/guidance/ng246"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,'{"title": "Choisir des objectifs au-delà de la balance", "objective": "choisir ce qui compte pour vous. Les approches professionnelles privilégient des objectifs négociés et une démarche adaptée à la personne. Les raisons personnelles ne remplacent pas les ressources matérielles ni les soins nécessaires.", "body": "Le poids est une donnée possible parmi d’autres. L’endurance, le sommeil, le confort digestif, la relation à la nourriture et les mesures médicales peuvent aussi compter. Une amélioration n’a pas besoin d’être visible pour être réelle.", "action": "retenez trois indicateurs : un comportement, une sensation et une capacité. Exemple : préparer deux dîners, remarquer son énergie et marcher jusqu’à un commerce avec davantage de confort. Faites le point après quelques semaines, sans transformer chaque journée en contrôle.", "question": "Qu’est-ce que cette idée change pour moi, dans une journée ordinaire?", "sources": [{"id": "S02", "title": "Vallis, Macklin et Russell-Mayhew, Obésité Canada, 2020.", "url": "https://obesitycanada.ca/wp-content/uploads/2025/03/10-Canadian-Adult-Obesity-CPG-Psych-Interventions.pdf"}, {"id": "S03", "title": "NICE, NG246, publié en 2025, version en ligne consultée.", "url": "https://www.nice.org.uk/guidance/ng246"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,1) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('3b335250-7f32-5409-b654-1fe39f39a2dd','ad1525ce-f011-5dbe-9421-16a54463f7a1',6,'published','{"title": "Reconnaître les avantages de ses habitudes actuelles", "objective": "choisir ce qui compte pour vous. Les approches professionnelles privilégient des objectifs négociés et une démarche adaptée à la personne. Les raisons personnelles ne remplacent pas les ressources matérielles ni les soins nécessaires.", "body": "Une habitude persistante remplit souvent une fonction. Commander un repas peut économiser de l’énergie ; grignoter peut marquer une pause ; manger tard peut être la seule possibilité de la journée. Supprimer le comportement sans remplacer son utilité rend le changement difficile.", "action": "choisissez une habitude et demandez-vous : « Qu’est-ce qu’elle me donne ? » Si la réponse est « du temps », cherchez une solution aussi rapide. Un repas assemblé peut mieux convenir qu’une recette ambitieuse.", "question": "Qu’est-ce que cette idée change pour moi, dans une journée ordinaire?", "sources": [{"id": "S02", "title": "Vallis, Macklin et Russell-Mayhew, Obésité Canada, 2020.", "url": "https://obesitycanada.ca/wp-content/uploads/2025/03/10-Canadian-Adult-Obesity-CPG-Psych-Interventions.pdf"}, {"id": "S03", "title": "NICE, NG246, publié en 2025, version en ligne consultée.", "url": "https://www.nice.org.uk/guidance/ng246"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,'{"title": "Reconnaître les avantages de ses habitudes actuelles", "objective": "choisir ce qui compte pour vous. Les approches professionnelles privilégient des objectifs négociés et une démarche adaptée à la personne. Les raisons personnelles ne remplacent pas les ressources matérielles ni les soins nécessaires.", "body": "Une habitude persistante remplit souvent une fonction. Commander un repas peut économiser de l’énergie ; grignoter peut marquer une pause ; manger tard peut être la seule possibilité de la journée. Supprimer le comportement sans remplacer son utilité rend le changement difficile.", "action": "choisissez une habitude et demandez-vous : « Qu’est-ce qu’elle me donne ? » Si la réponse est « du temps », cherchez une solution aussi rapide. Un repas assemblé peut mieux convenir qu’une recette ambitieuse.", "question": "Qu’est-ce que cette idée change pour moi, dans une journée ordinaire?", "sources": [{"id": "S02", "title": "Vallis, Macklin et Russell-Mayhew, Obésité Canada, 2020.", "url": "https://obesitycanada.ca/wp-content/uploads/2025/03/10-Canadian-Adult-Obesity-CPG-Psych-Interventions.pdf"}, {"id": "S03", "title": "NICE, NG246, publié en 2025, version en ligne consultée.", "url": "https://www.nice.org.uk/guidance/ng246"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,1) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('5e20ce9a-8396-5fcc-a0b7-a47416309e57','ad1525ce-f011-5dbe-9421-16a54463f7a1',7,'published','{"title": "Comprendre son ambivalence", "objective": "choisir ce qui compte pour vous. Les approches professionnelles privilégient des objectifs négociés et une démarche adaptée à la personne. Les raisons personnelles ne remplacent pas les ressources matérielles ni les soins nécessaires.", "body": "On peut vouloir améliorer sa santé et ne pas vouloir compter ses repas, renoncer à des sorties ou consacrer davantage de temps à cuisiner. Cette hésitation mérite d’être entendue. Elle permet de construire une démarche plus acceptable.", "action": "écrivez « j’aimerais… mais je tiens aussi à… ». Par exemple : « j’aimerais manger plus régulièrement, mais je tiens à ma flexibilité ». Cherchez ensuite un compromis concret : deux repas de secours disponibles, sans horaire parfaitement fixe.", "question": "Qu’est-ce que cette idée change pour moi, dans une journée ordinaire?", "sources": [{"id": "S02", "title": "Vallis, Macklin et Russell-Mayhew, Obésité Canada, 2020.", "url": "https://obesitycanada.ca/wp-content/uploads/2025/03/10-Canadian-Adult-Obesity-CPG-Psych-Interventions.pdf"}, {"id": "S03", "title": "NICE, NG246, publié en 2025, version en ligne consultée.", "url": "https://www.nice.org.uk/guidance/ng246"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,'{"title": "Comprendre son ambivalence", "objective": "choisir ce qui compte pour vous. Les approches professionnelles privilégient des objectifs négociés et une démarche adaptée à la personne. Les raisons personnelles ne remplacent pas les ressources matérielles ni les soins nécessaires.", "body": "On peut vouloir améliorer sa santé et ne pas vouloir compter ses repas, renoncer à des sorties ou consacrer davantage de temps à cuisiner. Cette hésitation mérite d’être entendue. Elle permet de construire une démarche plus acceptable.", "action": "écrivez « j’aimerais… mais je tiens aussi à… ». Par exemple : « j’aimerais manger plus régulièrement, mais je tiens à ma flexibilité ». Cherchez ensuite un compromis concret : deux repas de secours disponibles, sans horaire parfaitement fixe.", "question": "Qu’est-ce que cette idée change pour moi, dans une journée ordinaire?", "sources": [{"id": "S02", "title": "Vallis, Macklin et Russell-Mayhew, Obésité Canada, 2020.", "url": "https://obesitycanada.ca/wp-content/uploads/2025/03/10-Canadian-Adult-Obesity-CPG-Psych-Interventions.pdf"}, {"id": "S03", "title": "NICE, NG246, publié en 2025, version en ligne consultée.", "url": "https://www.nice.org.uk/guidance/ng246"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,1) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('ef9ba890-5237-5f27-a3d6-edad2546faba','ad1525ce-f011-5dbe-9421-16a54463f7a1',8,'published','{"title": "Évaluer sa disponibilité à changer", "objective": "choisir ce qui compte pour vous. Les approches professionnelles privilégient des objectifs négociés et une démarche adaptée à la personne. Les raisons personnelles ne remplacent pas les ressources matérielles ni les soins nécessaires.", "body": "La période de vie compte. Un deuil, des soucis financiers ou un emploi épuisant peuvent limiter la place disponible. Stabiliser une routine peut alors être plus pertinent que multiplier les objectifs.", "action": "évaluez votre confiance de 0 à 10 pour une action précise. Ce chiffre n’est pas un test validé ici ; c’est un outil de discussion. Si la confiance est faible, demandez : « Quel obstacle puis-je enlever ? » Réduisez l’action jusqu’à ce qu’elle paraisse faisable.", "question": "Qu’est-ce que cette idée change pour moi, dans une journée ordinaire?", "sources": [{"id": "S02", "title": "Vallis, Macklin et Russell-Mayhew, Obésité Canada, 2020.", "url": "https://obesitycanada.ca/wp-content/uploads/2025/03/10-Canadian-Adult-Obesity-CPG-Psych-Interventions.pdf"}, {"id": "S03", "title": "NICE, NG246, publié en 2025, version en ligne consultée.", "url": "https://www.nice.org.uk/guidance/ng246"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,'{"title": "Évaluer sa disponibilité à changer", "objective": "choisir ce qui compte pour vous. Les approches professionnelles privilégient des objectifs négociés et une démarche adaptée à la personne. Les raisons personnelles ne remplacent pas les ressources matérielles ni les soins nécessaires.", "body": "La période de vie compte. Un deuil, des soucis financiers ou un emploi épuisant peuvent limiter la place disponible. Stabiliser une routine peut alors être plus pertinent que multiplier les objectifs.", "action": "évaluez votre confiance de 0 à 10 pour une action précise. Ce chiffre n’est pas un test validé ici ; c’est un outil de discussion. Si la confiance est faible, demandez : « Quel obstacle puis-je enlever ? » Réduisez l’action jusqu’à ce qu’elle paraisse faisable.", "question": "Qu’est-ce que cette idée change pour moi, dans une journée ordinaire?", "sources": [{"id": "S02", "title": "Vallis, Macklin et Russell-Mayhew, Obésité Canada, 2020.", "url": "https://obesitycanada.ca/wp-content/uploads/2025/03/10-Canadian-Adult-Obesity-CPG-Psych-Interventions.pdf"}, {"id": "S03", "title": "NICE, NG246, publié en 2025, version en ligne consultée.", "url": "https://www.nice.org.uk/guidance/ng246"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,1) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('26401108-b89d-50e7-8a71-9f774e9da16d','ad1525ce-f011-5dbe-9421-16a54463f7a1',9,'published','{"title": "Préserver ce qui donne du plaisir", "objective": "choisir ce qui compte pour vous. Les approches professionnelles privilégient des objectifs négociés et une démarche adaptée à la personne. Les raisons personnelles ne remplacent pas les ressources matérielles ni les soins nécessaires.", "body": "Un plan personnel doit laisser de la place à vos plats, votre culture et vos moments partagés. Préserver le plaisir ne signifie pas garder exactement toutes les quantités ou fréquences. Cela signifie éviter de construire une vie alimentaire que vous avez hâte de quitter.", "action": "listez trois choses à conserver, comme les tacos, le brunch ou le souper familial. Pour chacune, imaginez un ajustement acceptable : portion selon l’appétit, accompagnement différent, rythme plus attentif. Aucune modification n’est obligatoire d’emblée.", "question": "Qu’est-ce que cette idée change pour moi, dans une journée ordinaire?", "sources": [{"id": "S02", "title": "Vallis, Macklin et Russell-Mayhew, Obésité Canada, 2020.", "url": "https://obesitycanada.ca/wp-content/uploads/2025/03/10-Canadian-Adult-Obesity-CPG-Psych-Interventions.pdf"}, {"id": "S03", "title": "NICE, NG246, publié en 2025, version en ligne consultée.", "url": "https://www.nice.org.uk/guidance/ng246"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,'{"title": "Préserver ce qui donne du plaisir", "objective": "choisir ce qui compte pour vous. Les approches professionnelles privilégient des objectifs négociés et une démarche adaptée à la personne. Les raisons personnelles ne remplacent pas les ressources matérielles ni les soins nécessaires.", "body": "Un plan personnel doit laisser de la place à vos plats, votre culture et vos moments partagés. Préserver le plaisir ne signifie pas garder exactement toutes les quantités ou fréquences. Cela signifie éviter de construire une vie alimentaire que vous avez hâte de quitter.", "action": "listez trois choses à conserver, comme les tacos, le brunch ou le souper familial. Pour chacune, imaginez un ajustement acceptable : portion selon l’appétit, accompagnement différent, rythme plus attentif. Aucune modification n’est obligatoire d’emblée.", "question": "Qu’est-ce que cette idée change pour moi, dans une journée ordinaire?", "sources": [{"id": "S02", "title": "Vallis, Macklin et Russell-Mayhew, Obésité Canada, 2020.", "url": "https://obesitycanada.ca/wp-content/uploads/2025/03/10-Canadian-Adult-Obesity-CPG-Psych-Interventions.pdf"}, {"id": "S03", "title": "NICE, NG246, publié en 2025, version en ligne consultée.", "url": "https://www.nice.org.uk/guidance/ng246"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,1) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('091f5c1c-7873-58a8-b11c-db363b83900b','ad1525ce-f011-5dbe-9421-16a54463f7a1',10,'published','{"title": "Formuler un engagement réaliste", "objective": "choisir ce qui compte pour vous. Les approches professionnelles privilégient des objectifs négociés et une démarche adaptée à la personne. Les raisons personnelles ne remplacent pas les ressources matérielles ni les soins nécessaires.", "body": "Une promesse absolue expose à se sentir en échec au premier imprévu. Un engagement utile précise ce que vous allez essayer et comment vous réviserez le plan. Il prévoit le droit d’apprendre.", "action": "écrivez : « Pendant sept jours, je vais essayer __ dans la situation __. Si cela devient trop difficile, je simplifierai ainsi : __. Dimanche, je regarderai ce que j’ai appris. » Signez si cela vous plaît. Votre engagement porte sur l’expérience, pas sur un nombre de kilos.", "question": "Qu’est-ce que cette idée change pour moi, dans une journée ordinaire?", "sources": [{"id": "S02", "title": "Vallis, Macklin et Russell-Mayhew, Obésité Canada, 2020.", "url": "https://obesitycanada.ca/wp-content/uploads/2025/03/10-Canadian-Adult-Obesity-CPG-Psych-Interventions.pdf"}, {"id": "S03", "title": "NICE, NG246, publié en 2025, version en ligne consultée.", "url": "https://www.nice.org.uk/guidance/ng246"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,'{"title": "Formuler un engagement réaliste", "objective": "choisir ce qui compte pour vous. Les approches professionnelles privilégient des objectifs négociés et une démarche adaptée à la personne. Les raisons personnelles ne remplacent pas les ressources matérielles ni les soins nécessaires.", "body": "Une promesse absolue expose à se sentir en échec au premier imprévu. Un engagement utile précise ce que vous allez essayer et comment vous réviserez le plan. Il prévoit le droit d’apprendre.", "action": "écrivez : « Pendant sept jours, je vais essayer __ dans la situation __. Si cela devient trop difficile, je simplifierai ainsi : __. Dimanche, je regarderai ce que j’ai appris. » Signez si cela vous plaît. Votre engagement porte sur l’expérience, pas sur un nombre de kilos.", "question": "Qu’est-ce que cette idée change pour moi, dans une journée ordinaire?", "sources": [{"id": "S02", "title": "Vallis, Macklin et Russell-Mayhew, Obésité Canada, 2020.", "url": "https://obesitycanada.ca/wp-content/uploads/2025/03/10-Canadian-Adult-Obesity-CPG-Psych-Interventions.pdf"}, {"id": "S03", "title": "NICE, NG246, publié en 2025, version en ligne consultée.", "url": "https://www.nice.org.uk/guidance/ng246"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,1) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('8f5a2e23-f5d5-593f-9d71-ef09d720110c','9d515df3-65ac-5817-a92a-411e3b8320a8',11,'review','{"title": "Reconnaître les comportements automatiques", "objective": "rendre un comportement praticable sans attendre une motivation constante. Les petites actions et les plans de rechange sont utiles ; il n’existe pas de délai universel de 21 jours pour former une habitude. La durée varie beaucoup.", "body": "Un geste automatique commence parfois avant une décision consciente : ouvrir le garde-manger en entrant, manger devant l’ordinateur ou prendre une boisson en passant au café. L’automatisme n’est pas une faute.", "action": "observez un seul moment pendant trois jours. Notez le premier geste : « j’ouvre le tiroir », « je lance l’application ». Vous cherchez l’endroit où un choix pourrait devenir possible. Ne vous imposez pas de changer le comportement durant cette première observation.", "question": "Quel petit détail de ma journée m’aide à comprendre cette habitude?", "sources": [{"id": "S06", "title": "NIDDK, révision 2020.", "url": "https://www.niddk.nih.gov/health-information/diet-nutrition/changing-habits-better-health"}, {"id": "S07", "title": "CDC, 2024.", "url": "https://www.cdc.gov/diabetes/prevention-type-2/new-healthy-habits.html"}, {"id": "S08", "title": "Singh et coll., Healthcare, 2024.", "url": "https://www.mdpi.com/2227-9032/12/23/2488"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('2d123772-d277-560c-aa5d-bebd7a0a950d','9d515df3-65ac-5817-a92a-411e3b8320a8',12,'review','{"title": "Identifier les déclencheurs", "objective": "rendre un comportement praticable sans attendre une motivation constante. Les petites actions et les plans de rechange sont utiles ; il n’existe pas de délai universel de 21 jours pour former une habitude. La durée varie beaucoup.", "body": "Un déclencheur peut être un lieu, une heure, une personne, une émotion ou une sensation. Plusieurs peuvent se combiner. « Je manque de volonté le soir » devient une information plus précise si l’on remarque une fatigue et un long intervalle depuis le repas précédent.", "action": "complétez « cela arrive surtout quand… ». Retenez le déclencheur le plus fréquent. S’il s’agit d’une faim réelle, la solution peut être de manger plus régulièrement, plutôt que de rendre les aliments moins accessibles.", "question": "Quel petit détail de ma journée m’aide à comprendre cette habitude?", "sources": [{"id": "S06", "title": "NIDDK, révision 2020.", "url": "https://www.niddk.nih.gov/health-information/diet-nutrition/changing-habits-better-health"}, {"id": "S07", "title": "CDC, 2024.", "url": "https://www.cdc.gov/diabetes/prevention-type-2/new-healthy-habits.html"}, {"id": "S08", "title": "Singh et coll., Healthcare, 2024.", "url": "https://www.mdpi.com/2227-9032/12/23/2488"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('dd18aa88-3e36-58dd-bfcd-ce7c7a076578','9d515df3-65ac-5817-a92a-411e3b8320a8',13,'review','{"title": "Comprendre la boucle déclencheur, comportement, récompense", "objective": "rendre un comportement praticable sans attendre une motivation constante. Les petites actions et les plans de rechange sont utiles ; il n’existe pas de délai universel de 21 jours pour former une habitude. La durée varie beaucoup.", "body": "Cette boucle est un modèle simplifié : une situation précède un geste, puis une conséquence rend sa répétition attrayante. Elle aide à poser des questions, mais ne décrit pas toute la biologie de l’appétit.", "action": "dessinez votre propre exemple en trois cases. « Fin d’une réunion difficile → biscuits au bureau → courte détente. » Ajoutez une quatrième case : « autre manière possible d’obtenir une pause ». Gardez plusieurs réponses possibles, y compris une collation choisie.", "question": "Quel petit détail de ma journée m’aide à comprendre cette habitude?", "sources": [{"id": "S06", "title": "NIDDK, révision 2020.", "url": "https://www.niddk.nih.gov/health-information/diet-nutrition/changing-habits-better-health"}, {"id": "S07", "title": "CDC, 2024.", "url": "https://www.cdc.gov/diabetes/prevention-type-2/new-healthy-habits.html"}, {"id": "S08", "title": "Singh et coll., Healthcare, 2024.", "url": "https://www.mdpi.com/2227-9032/12/23/2488"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('50de799b-ccd9-5241-ba77-e8d04d0524a9','9d515df3-65ac-5817-a92a-411e3b8320a8',14,'review','{"title": "Repérer la récompense recherchée", "objective": "rendre un comportement praticable sans attendre une motivation constante. Les petites actions et les plans de rechange sont utiles ; il n’existe pas de délai universel de 21 jours pour former une habitude. La durée varie beaucoup.", "body": "La récompense n’est pas toujours le goût. Cela peut être du réconfort, de la stimulation, une transition ou un moment à soi. Une réponse adaptée dépend de ce besoin.", "action": "avant une habitude que vous voulez comprendre, choisissez un mot : faim, repos, plaisir, lien ou changement d’air. Après, demandez-vous si le besoin est satisfait. Si vous cherchiez un contact humain, un aliment délicieux peut rester agréable sans répondre à votre besoin de compagnie.", "question": "Quel petit détail de ma journée m’aide à comprendre cette habitude?", "sources": [{"id": "S06", "title": "NIDDK, révision 2020.", "url": "https://www.niddk.nih.gov/health-information/diet-nutrition/changing-habits-better-health"}, {"id": "S07", "title": "CDC, 2024.", "url": "https://www.cdc.gov/diabetes/prevention-type-2/new-healthy-habits.html"}, {"id": "S08", "title": "Singh et coll., Healthcare, 2024.", "url": "https://www.mdpi.com/2227-9032/12/23/2488"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('ff0c0134-c93d-5715-86de-62671d69801e','9d515df3-65ac-5817-a92a-411e3b8320a8',15,'review','{"title": "Reconnaître les automatismes et préparer ses choix", "objective": "rendre un comportement praticable sans attendre une motivation constante. Les petites actions et les plans de rechange sont utiles ; il n’existe pas de délai universel de 21 jours pour former une habitude. La durée varie beaucoup.", "body": "Certaines décisions se répètent presque automatiquement dans un contexte familier. Une intention réfléchie peut avoir besoin d’un repère concret pour prendre sa place dans une journée chargée.\n\nObserver le contexte, préparer une option simple et essayer à nouveau permet de chercher ce qui vous convient. Une difficulté n’est pas un défaut de volonté.", "action": "Repérez un moment où une habitude prend le dessus sur votre intention. Quelle petite modification du contexte pourrait vous aider à essayer autre chose?", "question": "Quel petit détail de ma journée m’aide à comprendre cette habitude?", "sources": [{"id": "S06", "title": "NIDDK, révision 2020.", "url": "https://www.niddk.nih.gov/health-information/diet-nutrition/changing-habits-better-health"}, {"id": "S07", "title": "CDC, 2024.", "url": "https://www.cdc.gov/diabetes/prevention-type-2/new-healthy-habits.html"}, {"id": "S08", "title": "Singh et coll., Healthcare, 2024.", "url": "https://www.mdpi.com/2227-9032/12/23/2488"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('a73c556b-c362-5952-8232-46c369d44656','9d515df3-65ac-5817-a92a-411e3b8320a8',16,'review','{"title": "Distinguer motivation et organisation", "objective": "rendre un comportement praticable sans attendre une motivation constante. Les petites actions et les plans de rechange sont utiles ; il n’existe pas de délai universel de 21 jours pour former une habitude. La durée varie beaucoup.", "body": "La motivation fluctue. Une action qui dépend de trente minutes libres, d’un ingrédient manquant et d’une forte énergie sera fragile. L’organisation sert à réduire les conditions nécessaires pour agir.", "action": "prenez une intention vague, comme « mieux dîner ». Énumérez ce qui manque : un repas, un contenant, une pause. Réglez un seul obstacle concret aujourd’hui. Demain, vous aurez moins de décisions à prendre, même si votre enthousiasme n’a pas augmenté.", "question": "Quel petit détail de ma journée m’aide à comprendre cette habitude?", "sources": [{"id": "S06", "title": "NIDDK, révision 2020.", "url": "https://www.niddk.nih.gov/health-information/diet-nutrition/changing-habits-better-health"}, {"id": "S07", "title": "CDC, 2024.", "url": "https://www.cdc.gov/diabetes/prevention-type-2/new-healthy-habits.html"}, {"id": "S08", "title": "Singh et coll., Healthcare, 2024.", "url": "https://www.mdpi.com/2227-9032/12/23/2488"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('bd29b528-d670-5e06-bd91-f7c9de5b8f6e','9d515df3-65ac-5817-a92a-411e3b8320a8',17,'review','{"title": "Remplacer une habitude en conservant sa fonction", "objective": "rendre un comportement praticable sans attendre une motivation constante. Les petites actions et les plans de rechange sont utiles ; il n’existe pas de délai universel de 21 jours pour former une habitude. La durée varie beaucoup.", "body": "Un remplacement doit être suffisamment satisfaisant. Si la pause-café apporte une vraie coupure, boire de l’eau devant le même écran ne remplace pas forcément cette pause. Cherchez la fonction plutôt que le geste le plus « vertueux ».", "action": "inventez deux versions d’une pause de travail : l’une avec une collation assise, l’autre avec une courte sortie. Testez-les à des moments comparables. Comparez leur effet sur votre besoin, sans décider à l’avance laquelle devrait gagner.", "question": "Quel petit détail de ma journée m’aide à comprendre cette habitude?", "sources": [{"id": "S06", "title": "NIDDK, révision 2020.", "url": "https://www.niddk.nih.gov/health-information/diet-nutrition/changing-habits-better-health"}, {"id": "S07", "title": "CDC, 2024.", "url": "https://www.cdc.gov/diabetes/prevention-type-2/new-healthy-habits.html"}, {"id": "S08", "title": "Singh et coll., Healthcare, 2024.", "url": "https://www.mdpi.com/2227-9032/12/23/2488"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('37e32421-2c0a-58a1-b8ea-fe1783aefcd2','9d515df3-65ac-5817-a92a-411e3b8320a8',18,'review','{"title": "Commencer par une action petite et répétable", "objective": "rendre un comportement praticable sans attendre une motivation constante. Les petites actions et les plans de rechange sont utiles ; il n’existe pas de délai universel de 21 jours pour former une habitude. La durée varie beaucoup.", "body": "Une petite action réduit la difficulté de départ. Elle peut ensuite grandir, mais n’a pas besoin de devenir ambitieuse immédiatement. Les répétitions régulières comptent davantage que la taille héroïque du premier effort.", "action": "transformez « préparer tous mes repas » en « choisir le dîner de demain ». Répétez cette version pendant quelques jours. Agrandissez-la seulement si elle ne vous coûte pas trop. Si elle échoue, cherchez un meilleur moment ou une version encore plus simple.", "question": "Quel petit détail de ma journée m’aide à comprendre cette habitude?", "sources": [{"id": "S06", "title": "NIDDK, révision 2020.", "url": "https://www.niddk.nih.gov/health-information/diet-nutrition/changing-habits-better-health"}, {"id": "S07", "title": "CDC, 2024.", "url": "https://www.cdc.gov/diabetes/prevention-type-2/new-healthy-habits.html"}, {"id": "S08", "title": "Singh et coll., Healthcare, 2024.", "url": "https://www.mdpi.com/2227-9032/12/23/2488"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('0119d51c-27f7-5195-804e-3508cec96c88','9d515df3-65ac-5817-a92a-411e3b8320a8',19,'review','{"title": "Réduire les obstacles pratiques", "objective": "rendre un comportement praticable sans attendre une motivation constante. Les petites actions et les plans de rechange sont utiles ; il n’existe pas de délai universel de 21 jours pour former une habitude. La durée varie beaucoup.", "body": "Une habitude devient plus accessible lorsque le matériel et les conditions sont disponibles. Cela peut être un banc pour cuisiner assis, des légumes surgelés ou des chaussures confortables. La solution n’est pas toujours d’en faire davantage.", "action": "choisissez une action et préparez son premier pas. Pour une marche, placez vos chaussures près de la porte ; pour un repas, regroupez les ingrédients. Vérifiez ensuite si cette préparation simplifie réellement la situation, au lieu de seulement embellir votre organisation.", "question": "Quel petit détail de ma journée m’aide à comprendre cette habitude?", "sources": [{"id": "S06", "title": "NIDDK, révision 2020.", "url": "https://www.niddk.nih.gov/health-information/diet-nutrition/changing-habits-better-health"}, {"id": "S07", "title": "CDC, 2024.", "url": "https://www.cdc.gov/diabetes/prevention-type-2/new-healthy-habits.html"}, {"id": "S08", "title": "Singh et coll., Healthcare, 2024.", "url": "https://www.mdpi.com/2227-9032/12/23/2488"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('b3bed9fe-d997-5afb-84e4-e526a85f0aae','9d515df3-65ac-5817-a92a-411e3b8320a8',20,'review','{"title": "Renforcer les efforts avec une récompense adaptée", "objective": "rendre un comportement praticable sans attendre une motivation constante. Les petites actions et les plans de rechange sont utiles ; il n’existe pas de délai universel de 21 jours pour former une habitude. La durée varie beaucoup.", "body": "Une récompense peut reconnaître un effort : cocher une case, écouter une musique appréciée, prendre un moment agréable. Évitez de conditionner votre droit de manger à une réussite sportive ou à une pesée.", "action": "après votre expérience, notez une phrase factuelle : « j’ai préparé une option pour demain ». Choisissez ensuite une petite reconnaissance accessible. Le but est de remarquer vos actions utiles, sans rendre votre plaisir dépendant d’une performance parfaite.", "question": "Quel petit détail de ma journée m’aide à comprendre cette habitude?", "sources": [{"id": "S06", "title": "NIDDK, révision 2020.", "url": "https://www.niddk.nih.gov/health-information/diet-nutrition/changing-habits-better-health"}, {"id": "S07", "title": "CDC, 2024.", "url": "https://www.cdc.gov/diabetes/prevention-type-2/new-healthy-habits.html"}, {"id": "S08", "title": "Singh et coll., Healthcare, 2024.", "url": "https://www.mdpi.com/2227-9032/12/23/2488"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('00c0ebe0-c85f-5336-83f8-23c5a9b01e08','233277de-4b59-5f1d-84f7-24e7cbaef3fe',21,'review','{"title": "Développer une attitude de curiosité", "objective": "obtenir assez d’informations pour ajuster votre démarche. Le suivi alimentaire et du poids est utilisé dans les programmes comportementaux, mais son format doit rester tolérable. Un suivi qui devient obsessionnel mérite d’être simplifié ou suspendu.", "body": "« Pourquoi suis-je incapable ? » ferme la discussion. « Que s’est-il passé ? » permet d’examiner le contexte. Vous pouvez reconnaître qu’une situation ne vous convient pas sans vous condamner.", "action": "après un repas difficile, écrivez une observation commençant par « j’ai remarqué ». Exemple : « j’ai remarqué que je mange rapidement lorsque je reprends mes courriels ». Ajoutez une question concrète : « est-ce différent quand je ferme l’ordinateur pendant les premières minutes ? »", "question": "Qu’ai-je remarqué, en laissant les jugements de côté?", "sources": [{"id": "S04", "title": "USPSTF, 2018.", "url": "https://www.uspreventiveservicestaskforce.org/uspstf/recommendation/obesity-in-adults-interventions"}, {"id": "S09", "title": "USDA, Nutrition Evidence Systematic Review.", "url": "https://nesr.usda.gov/what-relationship-between-use-diet-and-body-weight-self-monitoring-strategies-and-body-weight"}, {"id": "S26", "title": "NHS.", "url": "https://www.nhs.uk/mental-health/feelings-symptoms-behaviours/behaviours/eating-disorders/overview/"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('4bb81aec-d591-5f58-898e-87bf56dac68f','233277de-4b59-5f1d-84f7-24e7cbaef3fe',22,'review','{"title": "Tenir un journal alimentaire adapté", "objective": "obtenir assez d’informations pour ajuster votre démarche. Le suivi alimentaire et du poids est utilisé dans les programmes comportementaux, mais son format doit rester tolérable. Un suivi qui devient obsessionnel mérite d’être simplifié ou suspendu.", "body": "Un journal peut être une photo, quelques mots ou une liste d’aliments. Le comptage calorique est une possibilité, pas une obligation. Le meilleur format fournit une information utile sans accaparer votre vie.", "action": "pendant quelques jours, inscrivez uniquement l’heure et une description du repas. Si vous savez déjà que votre difficulté concerne le souper, observez seulement ce moment. Arrêtez l’essai si les notes augmentent fortement la honte ou l’envie de vous restreindre.", "question": "Qu’ai-je remarqué, en laissant les jugements de côté?", "sources": [{"id": "S04", "title": "USPSTF, 2018.", "url": "https://www.uspreventiveservicestaskforce.org/uspstf/recommendation/obesity-in-adults-interventions"}, {"id": "S09", "title": "USDA, Nutrition Evidence Systematic Review.", "url": "https://nesr.usda.gov/what-relationship-between-use-diet-and-body-weight-self-monitoring-strategies-and-body-weight"}, {"id": "S26", "title": "NHS.", "url": "https://www.nhs.uk/mental-health/feelings-symptoms-behaviours/behaviours/eating-disorders/overview/"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('107d6dab-b592-5cf1-a15c-48fd25cf324f','233277de-4b59-5f1d-84f7-24e7cbaef3fe',23,'review','{"title": "Noter le contexte d’un repas", "objective": "obtenir assez d’informations pour ajuster votre démarche. Le suivi alimentaire et du poids est utilisé dans les programmes comportementaux, mais son format doit rester tolérable. Un suivi qui devient obsessionnel mérite d’être simplifié ou suspendu.", "body": "Deux repas identiques peuvent être vécus différemment selon le lieu, la vitesse et les distractions. Le contexte aide à expliquer ce que les calories ne racontent pas.", "action": "ajoutez trois mots à un repas : « bureau, pressé, seul » ou « table, calme, famille ». Après plusieurs observations, cherchez un contexte qui facilite votre confort. Choisissez un petit élément transférable, comme vous asseoir, plutôt que de vouloir reproduire un repas idéal.", "question": "Qu’ai-je remarqué, en laissant les jugements de côté?", "sources": [{"id": "S04", "title": "USPSTF, 2018.", "url": "https://www.uspreventiveservicestaskforce.org/uspstf/recommendation/obesity-in-adults-interventions"}, {"id": "S09", "title": "USDA, Nutrition Evidence Systematic Review.", "url": "https://nesr.usda.gov/what-relationship-between-use-diet-and-body-weight-self-monitoring-strategies-and-body-weight"}, {"id": "S26", "title": "NHS.", "url": "https://www.nhs.uk/mental-health/feelings-symptoms-behaviours/behaviours/eating-disorders/overview/"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('a3b04a37-b5dd-5b32-a45d-4098a9a76478','233277de-4b59-5f1d-84f7-24e7cbaef3fe',24,'review','{"title": "Observer ses émotions avant et après", "objective": "obtenir assez d’informations pour ajuster votre démarche. Le suivi alimentaire et du poids est utilisé dans les programmes comportementaux, mais son format doit rester tolérable. Un suivi qui devient obsessionnel mérite d’être simplifié ou suspendu.", "body": "Une émotion peut précéder un repas sans l’expliquer entièrement. Vous pouvez être stressé et avoir faim. Évitez de conclure automatiquement qu’une prise alimentaire est « émotionnelle » parce que la journée a été difficile.", "action": "notez un mot avant et après : tendu, soulagé, neutre, content. Ajoutez si vous aviez faim. Cherchez une tendance sur plusieurs situations ; une observation unique ne permet pas de diagnostiquer un problème ni de déterminer ce qu’il faudrait manger.", "question": "Qu’ai-je remarqué, en laissant les jugements de côté?", "sources": [{"id": "S04", "title": "USPSTF, 2018.", "url": "https://www.uspreventiveservicestaskforce.org/uspstf/recommendation/obesity-in-adults-interventions"}, {"id": "S09", "title": "USDA, Nutrition Evidence Systematic Review.", "url": "https://nesr.usda.gov/what-relationship-between-use-diet-and-body-weight-self-monitoring-strategies-and-body-weight"}, {"id": "S26", "title": "NHS.", "url": "https://www.nhs.uk/mental-health/feelings-symptoms-behaviours/behaviours/eating-disorders/overview/"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('074d2f1b-c2be-5182-b1ca-9f34a318f4bc','233277de-4b59-5f1d-84f7-24e7cbaef3fe',25,'review','{"title": "Repérer ses moments de vulnérabilité", "objective": "obtenir assez d’informations pour ajuster votre démarche. Le suivi alimentaire et du poids est utilisé dans les programmes comportementaux, mais son format doit rester tolérable. Un suivi qui devient obsessionnel mérite d’être simplifié ou suspendu.", "body": "Certains moments accumulent les obstacles : fin de quart de travail, retour des enfants, long trajet. Les connaître permet de placer du soutien avant la difficulté.", "action": "repérez une période où votre plan se défait souvent. Préparez une solution pour ce moment précis : repas prêt, collation transportable, aide d’un proche ou temps de pause. Évaluez ensuite si la situation devient plus facile, même si le repas n’est pas celui que vous aviez imaginé.", "question": "Qu’ai-je remarqué, en laissant les jugements de côté?", "sources": [{"id": "S04", "title": "USPSTF, 2018.", "url": "https://www.uspreventiveservicestaskforce.org/uspstf/recommendation/obesity-in-adults-interventions"}, {"id": "S09", "title": "USDA, Nutrition Evidence Systematic Review.", "url": "https://nesr.usda.gov/what-relationship-between-use-diet-and-body-weight-self-monitoring-strategies-and-body-weight"}, {"id": "S26", "title": "NHS.", "url": "https://www.nhs.uk/mental-health/feelings-symptoms-behaviours/behaviours/eating-disorders/overview/"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('dfcb6892-6a6c-5d85-a490-a0f143e40526','233277de-4b59-5f1d-84f7-24e7cbaef3fe',26,'review','{"title": "Reconnaître les portions qu’on estime mal", "objective": "obtenir assez d’informations pour ajuster votre démarche. Le suivi alimentaire et du poids est utilisé dans les programmes comportementaux, mais son format doit rester tolérable. Un suivi qui devient obsessionnel mérite d’être simplifié ou suspendu.", "body": "La portion choisie peut différer de celle indiquée sur l’emballage. Les bols, les poignées et les cuillères varient. Une mesure occasionnelle peut servir d’étalonnage, sans devenir une surveillance permanente.", "action": "mesurez une fois un aliment que vous mangez souvent, puis regardez à quoi il ressemble dans votre vaisselle. Ce n’est pas automatiquement la quantité que vous devez manger : c’est un repère pour mieux comprendre une recette ou une étiquette.", "question": "Qu’ai-je remarqué, en laissant les jugements de côté?", "sources": [{"id": "S10", "title": "NIDDK, révision 2021.", "url": "https://www.niddk.nih.gov/health-information/weight-management/just-enough-food-portions"}, {"id": "S04", "title": "USPSTF, 2018.", "url": "https://www.uspreventiveservicestaskforce.org/uspstf/recommendation/obesity-in-adults-interventions"}, {"id": "S09", "title": "USDA, Nutrition Evidence Systematic Review.", "url": "https://nesr.usda.gov/what-relationship-between-use-diet-and-body-weight-self-monitoring-strategies-and-body-weight"}, {"id": "S26", "title": "NHS.", "url": "https://www.nhs.uk/mental-health/feelings-symptoms-behaviours/behaviours/eating-disorders/overview/"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('5d68b8f0-4326-516b-955c-f579fb22ba88','233277de-4b59-5f1d-84f7-24e7cbaef3fe',27,'review','{"title": "Repérer boissons et petites bouchées oubliées", "objective": "obtenir assez d’informations pour ajuster votre démarche. Le suivi alimentaire et du poids est utilisé dans les programmes comportementaux, mais son format doit rester tolérable. Un suivi qui devient obsessionnel mérite d’être simplifié ou suspendu.", "body": "Les dégustations en cuisinant, le café sucré ou les restes picorés peuvent échapper à la mémoire. L’objectif est de décrire le réel, pas de surveiller chaque bouchée avec anxiété.", "action": "observez seulement les boissons pendant une journée. Demandez-vous lesquelles vous appréciez vraiment et lesquelles sont automatiques. Si vous choisissez un changement, faites-le sur une consommation fréquente et peu satisfaisante. Garder un café apprécié peut être compatible avec une démarche équilibrée.", "question": "Qu’ai-je remarqué, en laissant les jugements de côté?", "sources": [{"id": "S04", "title": "USPSTF, 2018.", "url": "https://www.uspreventiveservicestaskforce.org/uspstf/recommendation/obesity-in-adults-interventions"}, {"id": "S09", "title": "USDA, Nutrition Evidence Systematic Review.", "url": "https://nesr.usda.gov/what-relationship-between-use-diet-and-body-weight-self-monitoring-strategies-and-body-weight"}, {"id": "S26", "title": "NHS.", "url": "https://www.nhs.uk/mental-health/feelings-symptoms-behaviours/behaviours/eating-disorders/overview/"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('895148c1-c119-5280-b5bb-cc573d44f414','233277de-4b59-5f1d-84f7-24e7cbaef3fe',28,'review','{"title": "Séparer observation et jugement", "objective": "obtenir assez d’informations pour ajuster votre démarche. Le suivi alimentaire et du poids est utilisé dans les programmes comportementaux, mais son format doit rester tolérable. Un suivi qui devient obsessionnel mérite d’être simplifié ou suspendu.", "body": "« J’ai mangé deux portions » est descriptif. « Je suis incontrôlable » est une interprétation globale. La première phrase laisse la possibilité d’examiner la faim, la portion initiale ou la distraction.", "action": "réécrivez une note autocritique comme si vous décriviez une scène filmée. Ajoutez ensuite votre ressenti dans une phrase séparée : « je me sens déçu ». Vous pouvez reconnaître une émotion sans la transformer en preuve que vous êtes incapable.", "question": "Qu’ai-je remarqué, en laissant les jugements de côté?", "sources": [{"id": "S04", "title": "USPSTF, 2018.", "url": "https://www.uspreventiveservicestaskforce.org/uspstf/recommendation/obesity-in-adults-interventions"}, {"id": "S09", "title": "USDA, Nutrition Evidence Systematic Review.", "url": "https://nesr.usda.gov/what-relationship-between-use-diet-and-body-weight-self-monitoring-strategies-and-body-weight"}, {"id": "S26", "title": "NHS.", "url": "https://www.nhs.uk/mental-health/feelings-symptoms-behaviours/behaviours/eating-disorders/overview/"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('a47338b4-164d-511f-b9f9-e8bde3fdda13','233277de-4b59-5f1d-84f7-24e7cbaef3fe',29,'review','{"title": "Chercher les tendances", "objective": "obtenir assez d’informations pour ajuster votre démarche. Le suivi alimentaire et du poids est utilisé dans les programmes comportementaux, mais son format doit rester tolérable. Un suivi qui devient obsessionnel mérite d’être simplifié ou suspendu.", "body": "Une fête, une maladie ou une mauvaise nuit peuvent créer une journée inhabituelle. Modifier tout son plan après un épisode isolé risque de répondre au bruit plutôt qu’au problème.", "action": "relisez plusieurs observations et cherchez une répétition. Par exemple : « les jours où mon dîner est tardif, je grignote en préparant le souper ». Formulez une hypothèse, puis testez un changement. Ne traitez pas une association personnelle comme une certitude scientifique.", "question": "Qu’ai-je remarqué, en laissant les jugements de côté?", "sources": [{"id": "S04", "title": "USPSTF, 2018.", "url": "https://www.uspreventiveservicestaskforce.org/uspstf/recommendation/obesity-in-adults-interventions"}, {"id": "S09", "title": "USDA, Nutrition Evidence Systematic Review.", "url": "https://nesr.usda.gov/what-relationship-between-use-diet-and-body-weight-self-monitoring-strategies-and-body-weight"}, {"id": "S26", "title": "NHS.", "url": "https://www.nhs.uk/mental-health/feelings-symptoms-behaviours/behaviours/eating-disorders/overview/"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('a5eed470-9d95-5bd7-bb77-4e4e1f937e70','233277de-4b59-5f1d-84f7-24e7cbaef3fe',30,'review','{"title": "Transformer l’observation en expérience", "objective": "obtenir assez d’informations pour ajuster votre démarche. Le suivi alimentaire et du poids est utilisé dans les programmes comportementaux, mais son format doit rester tolérable. Un suivi qui devient obsessionnel mérite d’être simplifié ou suspendu.", "body": "Un journal devient utile lorsqu’il mène à une décision. Accumuler des données sans question peut alourdir la démarche. Une expérience simple change un élément suffisamment précis pour que vous puissiez en observer l’effet.", "action": "« Cette semaine, je prévois une collation les jours où le souper sera tardif. Je regarderai si ma faim à l’arrivée et mon confort au repas changent. » Conservez, ajustez ou abandonnez cette stratégie selon vos observations ; aucun résultat n’est un verdict moral.", "question": "Qu’ai-je remarqué, en laissant les jugements de côté?", "sources": [{"id": "S04", "title": "USPSTF, 2018.", "url": "https://www.uspreventiveservicestaskforce.org/uspstf/recommendation/obesity-in-adults-interventions"}, {"id": "S09", "title": "USDA, Nutrition Evidence Systematic Review.", "url": "https://nesr.usda.gov/what-relationship-between-use-diet-and-body-weight-self-monitoring-strategies-and-body-weight"}, {"id": "S26", "title": "NHS.", "url": "https://www.nhs.uk/mental-health/feelings-symptoms-behaviours/behaviours/eating-disorders/overview/"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('aa5ff39a-a87e-5f60-bf61-496c4177c008','6c30a0b7-ff23-54ff-a201-209dd1ba62a0',31,'review','{"title": "Comprendre ce qu’est une calorie", "objective": "manger de façon suffisamment nourrissante et compatible avec vos besoins. Il n’existe pas une répartition de macronutriments idéale pour tous. Une alimentation doit aussi être abordable, culturellement acceptable et durable.", "body": "La calorie alimentaire mesure de l’énergie. Elle ne mesure ni votre mérite ni, à elle seule, la qualité d’un aliment. Deux repas apportant la même énergie peuvent différer par leurs protéines, leurs fibres, leur volume et le plaisir ressenti.", "action": "regardez une étiquette et identifiez d’abord la quantité de référence. Demandez-vous ensuite ce que l’aliment apporte à votre repas. Les chiffres deviennent ainsi une information parmi d’autres, plutôt qu’un classement automatique entre aliments permis et interdits.", "question": "Comment pourrais-je rendre un repas plus simple et satisfaisant?", "sources": [{"id": "S12", "title": "NIDDK.", "url": "https://www.niddk.nih.gov/health-information/weight-management/myths-nutrition-physical-activity/"}, {"id": "S15", "title": "Santé Canada.", "url": "https://www.canada.ca/en/health-canada/services/food-guide/explore/healthy-eating-recommendations/use-food-labels.html"}, {"id": "S05", "title": "Brown et coll., Obésité Canada, mise à jour 2022.", "url": "https://obesitycanada.ca/wp-content/uploads/2025/03/8-Canadian-Adult-Obesity-CPG-Medical-Nutrition-Therapy_22.pdf"}, {"id": "S11", "title": "Gardner et coll., JAMA, 2018.", "url": "https://pubmed.ncbi.nlm.nih.gov/29466592/"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('4918cf0e-ace9-5292-a95a-729638b98dba','6c30a0b7-ff23-54ff-a201-209dd1ba62a0',32,'review','{"title": "Comprendre l’équilibre énergétique", "objective": "manger de façon suffisamment nourrissante et compatible avec vos besoins. Il n’existe pas une répartition de macronutriments idéale pour tous. Une alimentation doit aussi être abordable, culturellement acceptable et durable.", "body": "Sur la durée, une perte de masse grasse implique un apport énergétique inférieur aux dépenses. Mais l’appétit et les dépenses s’adaptent ; le corps n’est pas un calculateur fixe. Cette explication ne dit pas quelle stratégie sera la plus facile pour vous.", "action": "choisissez une modification soutenable, comme remplacer une boisson sucrée habituelle par une option appréciée moins sucrée. Observez faim, plaisir et faisabilité avant de multiplier les réductions.", "question": "Comment pourrais-je rendre un repas plus simple et satisfaisant?", "sources": [{"id": "S01", "title": "Wharton et coll., CMAJ, 2020.", "url": "https://www.cmaj.ca/content/192/31/e875"}, {"id": "S12", "title": "NIDDK.", "url": "https://www.niddk.nih.gov/health-information/weight-management/myths-nutrition-physical-activity/"}, {"id": "S05", "title": "Brown et coll., Obésité Canada, mise à jour 2022.", "url": "https://obesitycanada.ca/wp-content/uploads/2025/03/8-Canadian-Adult-Obesity-CPG-Medical-Nutrition-Therapy_22.pdf"}, {"id": "S11", "title": "Gardner et coll., JAMA, 2018.", "url": "https://pubmed.ncbi.nlm.nih.gov/29466592/"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('27c31be7-ee10-5d31-867c-65b713e1e977','6c30a0b7-ff23-54ff-a201-209dd1ba62a0',33,'review','{"title": "Distinguer déficit et privation excessive", "objective": "manger de façon suffisamment nourrissante et compatible avec vos besoins. Il n’existe pas une répartition de macronutriments idéale pour tous. Une alimentation doit aussi être abordable, culturellement acceptable et durable.", "body": "Une démarche de perte de poids doit permettre de rester nourri et fonctionnel. Vertiges, fatigue marquée, préoccupations alimentaires envahissantes ou crises répétées ne sont pas des preuves que le programme « fonctionne ». Les approches très restrictives relèvent d’un encadrement clinique.", "action": "vérifiez chaque semaine : ai-je assez d’énergie pour mes activités ? Mon alimentation reste-t-elle variée ? Si la réponse se dégrade, demandez une réévaluation plutôt que de réduire davantage vos repas.", "question": "Comment pourrais-je rendre un repas plus simple et satisfaisant?", "sources": [{"id": "S03", "title": "NICE, NG246, publié en 2025, version en ligne consultée.", "url": "https://www.nice.org.uk/guidance/ng246"}, {"id": "S26", "title": "NHS.", "url": "https://www.nhs.uk/mental-health/feelings-symptoms-behaviours/behaviours/eating-disorders/overview/"}, {"id": "S05", "title": "Brown et coll., Obésité Canada, mise à jour 2022.", "url": "https://obesitycanada.ca/wp-content/uploads/2025/03/8-Canadian-Adult-Obesity-CPG-Medical-Nutrition-Therapy_22.pdf"}, {"id": "S11", "title": "Gardner et coll., JAMA, 2018.", "url": "https://pubmed.ncbi.nlm.nih.gov/29466592/"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('0733ad82-ebe6-5500-8e34-70aeed7af210','6c30a0b7-ff23-54ff-a201-209dd1ba62a0',34,'review','{"title": "Comprendre la densité calorique", "objective": "manger de façon suffisamment nourrissante et compatible avec vos besoins. Il n’existe pas une répartition de macronutriments idéale pour tous. Une alimentation doit aussi être abordable, culturellement acceptable et durable.", "body": "La densité calorique correspond à l’énergie par quantité de nourriture, souvent exprimée par gramme. Les aliments riches en eau ont généralement une densité plus faible ; les matières grasses augmentent la densité. C’est un outil possible de composition des repas.", "action": "comparez un raisin frais et un raisin sec. Le séchage retire de l’eau et concentre l’énergie dans un petit volume. Les deux peuvent avoir leur place ; leurs portions usuelles et leurs usages diffèrent.", "question": "Comment pourrais-je rendre un repas plus simple et satisfaisant?", "sources": [{"id": "S13", "title": "Ello-Martin et coll., American Journal of Clinical Nutrition, 2007.", "url": "https://pubmed.ncbi.nlm.nih.gov/17556681/"}, {"id": "S05", "title": "Brown et coll., Obésité Canada, mise à jour 2022.", "url": "https://obesitycanada.ca/wp-content/uploads/2025/03/8-Canadian-Adult-Obesity-CPG-Medical-Nutrition-Therapy_22.pdf"}, {"id": "S11", "title": "Gardner et coll., JAMA, 2018.", "url": "https://pubmed.ncbi.nlm.nih.gov/29466592/"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('8b559467-85d6-5803-976e-f17055e15003','6c30a0b7-ff23-54ff-a201-209dd1ba62a0',35,'review','{"title": "Distinguer densité calorique et richesse nutritionnelle", "objective": "manger de façon suffisamment nourrissante et compatible avec vos besoins. Il n’existe pas une répartition de macronutriments idéale pour tous. Une alimentation doit aussi être abordable, culturellement acceptable et durable.", "body": "Les noix sont denses en énergie et apportent des nutriments utiles. Un produit très peu calorique peut apporter peu de nutriments. Choisir uniquement le plus faible nombre de calories serait donc incomplet.", "action": "pour un aliment, posez deux questions : « quelle quantité me convient ? » et « qu’apporte-t-il ? ». Une petite portion de noix peut compléter un fruit. Il n’est pas nécessaire de l’éliminer pour obtenir une assiette plus volumineuse.", "question": "Comment pourrais-je rendre un repas plus simple et satisfaisant?", "sources": [{"id": "S12", "title": "NIDDK.", "url": "https://www.niddk.nih.gov/health-information/weight-management/myths-nutrition-physical-activity/"}, {"id": "S14", "title": "Santé Canada.", "url": "https://www.canada.ca/fr/sante-canada/services/guide-alimentaire/explorez/recommandations-matiere-alimentation-saine.html"}, {"id": "S05", "title": "Brown et coll., Obésité Canada, mise à jour 2022.", "url": "https://obesitycanada.ca/wp-content/uploads/2025/03/8-Canadian-Adult-Obesity-CPG-Medical-Nutrition-Therapy_22.pdf"}, {"id": "S11", "title": "Gardner et coll., JAMA, 2018.", "url": "https://pubmed.ncbi.nlm.nih.gov/29466592/"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('a6062d26-8618-50f6-a539-d9241fe809de','6c30a0b7-ff23-54ff-a201-209dd1ba62a0',36,'review','{"title": "Comprendre le rôle de l’eau dans les aliments", "objective": "manger de façon suffisamment nourrissante et compatible avec vos besoins. Il n’existe pas une répartition de macronutriments idéale pour tous. Une alimentation doit aussi être abordable, culturellement acceptable et durable.", "body": "L’eau contenue dans les légumes, les fruits et certains plats augmente leur volume. Cela peut aider à composer un repas plus généreux pour son apport énergétique. Boire de l’eau ne remplace toutefois pas un repas lorsque vous avez faim.", "action": "ajoutez des légumes à une préparation que vous aimez, comme des champignons à une sauce ou des légumes surgelés à une soupe. Vérifiez le goût et le confort digestif. Le volume utile est celui que vous tolérez et appréciez.", "question": "Comment pourrais-je rendre un repas plus simple et satisfaisant?", "sources": [{"id": "S13", "title": "Ello-Martin et coll., American Journal of Clinical Nutrition, 2007.", "url": "https://pubmed.ncbi.nlm.nih.gov/17556681/"}, {"id": "S05", "title": "Brown et coll., Obésité Canada, mise à jour 2022.", "url": "https://obesitycanada.ca/wp-content/uploads/2025/03/8-Canadian-Adult-Obesity-CPG-Medical-Nutrition-Therapy_22.pdf"}, {"id": "S11", "title": "Gardner et coll., JAMA, 2018.", "url": "https://pubmed.ncbi.nlm.nih.gov/29466592/"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('92b8f70f-7702-5547-bb07-dc567b162854','6c30a0b7-ff23-54ff-a201-209dd1ba62a0',37,'review','{"title": "Comprendre le rôle des fibres", "objective": "manger de façon suffisamment nourrissante et compatible avec vos besoins. Il n’existe pas une répartition de macronutriments idéale pour tous. Une alimentation doit aussi être abordable, culturellement acceptable et durable.", "body": "Les fibres se trouvent notamment dans les légumineuses, les grains entiers, les fruits, les légumes, les noix et les graines. Elles participent au fonctionnement intestinal. Une augmentation graduelle et une hydratation adaptée facilitent généralement la tolérance.", "action": "ajoutez une petite quantité de lentilles à un plat familier ou choisissez parfois du pain de grains entiers. Observez votre digestion. En cas de maladie digestive ou de consigne médicale particulière, faites adapter ce changement plutôt que de chercher le maximum de fibres.", "question": "Comment pourrais-je rendre un repas plus simple et satisfaisant?", "sources": [{"id": "S16", "title": "Toronto Public Health.", "url": "https://www.toronto.ca/community-people/health-wellness-care/health-programs-advice/eating-well-with-canadas-food-guide/fibre/"}, {"id": "S05", "title": "Brown et coll., Obésité Canada, mise à jour 2022.", "url": "https://obesitycanada.ca/wp-content/uploads/2025/03/8-Canadian-Adult-Obesity-CPG-Medical-Nutrition-Therapy_22.pdf"}, {"id": "S11", "title": "Gardner et coll., JAMA, 2018.", "url": "https://pubmed.ncbi.nlm.nih.gov/29466592/"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('aae845a3-e6d0-571c-af1d-a11af972166b','6c30a0b7-ff23-54ff-a201-209dd1ba62a0',38,'review','{"title": "Comprendre le rôle des protéines", "objective": "manger de façon suffisamment nourrissante et compatible avec vos besoins. Il n’existe pas une répartition de macronutriments idéale pour tous. Une alimentation doit aussi être abordable, culturellement acceptable et durable.", "body": "Les protéines participent notamment à l’entretien des tissus et des muscles. Les besoins varient avec l’âge, la santé et le contexte. Il n’est pas nécessaire d’acheter des poudres pour inclure des aliments protéinés.", "action": "repérez une source dans vos repas : œufs, tofu, yogourt, légumineuses, poisson ou viande. Si vos repas en contiennent rarement, testez un ajout simple. Faites individualiser les quantités si vous avez une maladie rénale, une faible prise alimentaire ou un traitement qui réduit fortement l’appétit.", "question": "Comment pourrais-je rendre un repas plus simple et satisfaisant?", "sources": [{"id": "S14", "title": "Santé Canada.", "url": "https://www.canada.ca/fr/sante-canada/services/guide-alimentaire/explorez/recommandations-matiere-alimentation-saine.html"}, {"id": "S29", "title": "American College of Lifestyle Medicine, American Society for Nutrition, Obesity Medicine Association et The Obesity Society, 2025.", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC12125019/"}, {"id": "S05", "title": "Brown et coll., Obésité Canada, mise à jour 2022.", "url": "https://obesitycanada.ca/wp-content/uploads/2025/03/8-Canadian-Adult-Obesity-CPG-Medical-Nutrition-Therapy_22.pdf"}, {"id": "S11", "title": "Gardner et coll., JAMA, 2018.", "url": "https://pubmed.ncbi.nlm.nih.gov/29466592/"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('82f2c87e-a41c-5fe3-a035-9d6180468f7a','6c30a0b7-ff23-54ff-a201-209dd1ba62a0',39,'review','{"title": "Comprendre glucides et matières grasses", "objective": "manger de façon suffisamment nourrissante et compatible avec vos besoins. Il n’existe pas une répartition de macronutriments idéale pour tous. Une alimentation doit aussi être abordable, culturellement acceptable et durable.", "body": "Les glucides et les lipides ont leur place. Les aliments qui les apportent ne sont pas interchangeables : haricots, pain, huile et pâtisseries ont des compositions différentes. L’essai DIETFITS n’a pas trouvé de différence significative de perte de poids à douze mois entre les deux approches saines comparées, pauvre en gras et pauvre en glucides.", "action": "améliorez un repas habituel sans supprimer une famille complète : ajoutez une légumineuse, choisissez parfois un grain entier ou dosez une huile selon la recette.", "question": "Comment pourrais-je rendre un repas plus simple et satisfaisant?", "sources": [{"id": "S11", "title": "Gardner et coll., JAMA, 2018.", "url": "https://pubmed.ncbi.nlm.nih.gov/29466592/"}, {"id": "S05", "title": "Brown et coll., Obésité Canada, mise à jour 2022.", "url": "https://obesitycanada.ca/wp-content/uploads/2025/03/8-Canadian-Adult-Obesity-CPG-Medical-Nutrition-Therapy_22.pdf"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('db7c7401-b6c6-5514-927d-b7a7493e8004','6c30a0b7-ff23-54ff-a201-209dd1ba62a0',40,'review','{"title": "Composer un repas rassasiant et varié", "objective": "manger de façon suffisamment nourrissante et compatible avec vos besoins. Il n’existe pas une répartition de macronutriments idéale pour tous. Une alimentation doit aussi être abordable, culturellement acceptable et durable.", "body": "L’assiette canadienne propose environ une moitié de légumes et fruits, un quart d’aliments protéinés et un quart de grains entiers. Ce sont des proportions visuelles, pas des pourcentages de calories ni une prescription de quantité.", "action": "appliquez cette logique à un repas mélangé : riz, légumes et tofu ; pâtes, légumes et poulet ; chili et accompagnement. Ajustez la quantité à vos besoins. Une recette n’a pas besoin d’avoir trois compartiments pour être équilibrée.", "question": "Comment pourrais-je rendre un repas plus simple et satisfaisant?", "sources": [{"id": "S17", "title": "Santé Canada.", "url": "https://www.canada.ca/fr/sante-canada/services/guide-alimentaire/manger-favoriser/cuisiner/assiette-preparer-repas-sains.html"}, {"id": "S05", "title": "Brown et coll., Obésité Canada, mise à jour 2022.", "url": "https://obesitycanada.ca/wp-content/uploads/2025/03/8-Canadian-Adult-Obesity-CPG-Medical-Nutrition-Therapy_22.pdf"}, {"id": "S11", "title": "Gardner et coll., JAMA, 2018.", "url": "https://pubmed.ncbi.nlm.nih.gov/29466592/"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('4238165c-5a14-592b-b3dc-84f513d6a80b','34c4b4e1-445a-57ca-9d47-c24e3ef74825',41,'review','{"title": "Découvrir la densité énergétique avec souplesse", "objective": "disposer d’un outil supplémentaire, sans réduire l’alimentation à un code de couleur. Les preuves sur la densité énergétique ne valident pas automatiquement un système commercial précis.", "body": "La densité énergétique décrit la quantité d’énergie contenue dans un poids donné d’aliment. L’eau, les fibres et les matières grasses influencent ce repère. Il peut aider à réfléchir à la composition d’un repas, sans classer les aliments en bons et mauvais.\n\nLes goûts, la faim, les besoins et le plaisir comptent aussi. Ce repère n’impose pas de supprimer un aliment apprécié.", "action": "Observez un repas habituel. Y a-t-il un accompagnement que vous aimez et que vous aimeriez y ajouter pour le rendre plus satisfaisant?", "question": "Quel ajustement préserverait le plaisir de manger?", "sources": [{"id": "S13", "title": "Ello-Martin et coll., American Journal of Clinical Nutrition, 2007.", "url": "https://pubmed.ncbi.nlm.nih.gov/17556681/"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('6fa5121b-ce2c-564b-b1a4-9dbcf8ac3a34','34c4b4e1-445a-57ca-9d47-c24e3ef74825',42,'review','{"title": "Retirer le jugement moral", "objective": "disposer d’un outil supplémentaire, sans réduire l’alimentation à un code de couleur. Les preuves sur la densité énergétique ne valident pas automatiquement un système commercial précis.", "body": "Un aliment n’est pas une preuve de discipline ou d’échec. Certaines consommations sont à privilégier ou à limiter pour la santé, mais cela ne détermine pas la valeur de la personne qui mange.", "action": "remplacez « j’ai triché » par une description précise : « j’ai choisi un dessert ». Demandez-vous si vous l’avez apprécié et comment vous vous sentez. Cette formulation permet une décision future sans dette à rembourser par le jeûne ou l’exercice.", "question": "Quel ajustement préserverait le plaisir de manger?", "sources": [{"id": "S13", "title": "Ello-Martin et coll., American Journal of Clinical Nutrition, 2007.", "url": "https://pubmed.ncbi.nlm.nih.gov/17556681/"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('ac23f12b-8d67-5332-9d5e-ff977e8a4ecb','34c4b4e1-445a-57ca-9d47-c24e3ef74825',43,'review','{"title": "Augmenter la place des aliments moins denses", "objective": "disposer d’un outil supplémentaire, sans réduire l’alimentation à un code de couleur. Les preuves sur la densité énergétique ne valident pas automatiquement un système commercial précis.", "body": "Ajouter un aliment peu dense peut être pratique si cela améliore le repas. Ce n’est pas une consigne de remplir l’estomac au maximum. Une énorme salade sans accompagnement nourrissant ne répondra pas forcément à vos besoins.", "action": "gardez votre sandwich et ajoutez un légume ou un fruit apprécié. Observez votre satisfaction jusqu’au prochain repas. Si vous avez encore faim, revoyez l’ensemble du repas plutôt que d’ajouter toujours plus de volume.", "question": "Quel ajustement préserverait le plaisir de manger?", "sources": [{"id": "S13", "title": "Ello-Martin et coll., American Journal of Clinical Nutrition, 2007.", "url": "https://pubmed.ncbi.nlm.nih.gov/17556681/"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('4c422dce-2285-5ea2-82cd-29cf0fd5ad7d','34c4b4e1-445a-57ca-9d47-c24e3ef74825',44,'review','{"title": "Intégrer les aliments plus denses", "objective": "disposer d’un outil supplémentaire, sans réduire l’alimentation à un code de couleur. Les preuves sur la densité énergétique ne valident pas automatiquement un système commercial précis.", "body": "Fromage, huile, noix et chocolat peuvent s’intégrer à une alimentation équilibrée. Leur petite taille visuelle peut simplement rendre les quantités moins évidentes. Les exclure systématiquement peut nuire au goût ou à la variété.", "action": "servez la quantité que vous souhaitez dans une assiette ou un bol. Prenez le temps de l’apprécier et autorisez-vous à réévaluer. Ce geste vise à rendre la consommation visible, pas à imposer une portion universelle.", "question": "Quel ajustement préserverait le plaisir de manger?", "sources": [{"id": "S13", "title": "Ello-Martin et coll., American Journal of Clinical Nutrition, 2007.", "url": "https://pubmed.ncbi.nlm.nih.gov/17556681/"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('65109bf7-3533-5a53-836d-c40298c4dde1','34c4b4e1-445a-57ca-9d47-c24e3ef74825',45,'review','{"title": "Comparer à volume égal", "objective": "disposer d’un outil supplémentaire, sans réduire l’alimentation à un code de couleur. Les preuves sur la densité énergétique ne valident pas automatiquement un système commercial précis.", "body": "Deux bols de même taille n’apportent pas nécessairement la même énergie. Comparer le volume aide à comprendre une impression, mais les recettes et la préparation font varier le résultat.", "action": "comparez les données d’une portion mesurée de deux collations que vous consommez réellement. Notez aussi goût, facilité et faim après consommation. Ne choisissez pas automatiquement la plus volumineuse : une collation compacte peut être pratique lors d’un déplacement ou lorsque l’appétit est faible.", "question": "Quel ajustement préserverait le plaisir de manger?", "sources": [{"id": "S13", "title": "Ello-Martin et coll., American Journal of Clinical Nutrition, 2007.", "url": "https://pubmed.ncbi.nlm.nih.gov/17556681/"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('63359b5b-1d87-5847-a719-77fe2d5f57e3','34c4b4e1-445a-57ca-9d47-c24e3ef74825',46,'review','{"title": "Comparer à énergie égale", "objective": "disposer d’un outil supplémentaire, sans réduire l’alimentation à un code de couleur. Les preuves sur la densité énergétique ne valident pas automatiquement un système commercial précis.", "body": "À énergie égale, les quantités et la composition diffèrent. Cela permet d’explorer le confort et la satisfaction. Il ne faut pas en déduire que le volume prédit exactement la satiété de chaque personne.", "action": "si les chiffres vous conviennent, comparez deux collations à partir de leurs étiquettes. Sinon, comparez simplement deux collations habituelles à des moments semblables. Notez laquelle convient mieux à la situation. Une seule expérience ne permet pas de désigner un aliment « gagnant ».", "question": "Quel ajustement préserverait le plaisir de manger?", "sources": [{"id": "S13", "title": "Ello-Martin et coll., American Journal of Clinical Nutrition, 2007.", "url": "https://pubmed.ncbi.nlm.nih.gov/17556681/"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('732d9008-a1de-5adf-9f1a-df7123f45a0c','34c4b4e1-445a-57ca-9d47-c24e3ef74825',47,'review','{"title": "Tenir compte des boissons", "objective": "disposer d’un outil supplémentaire, sans réduire l’alimentation à un code de couleur. Les preuves sur la densité énergétique ne valident pas automatiquement un système commercial précis.", "body": "Les boissons sucrées peuvent apporter une énergie peu remarquée. L’eau est la boisson de référence du Guide alimentaire canadien, mais une boisson nutritive peut également contribuer à un repas. Un smoothie doit être considéré selon sa composition et son usage.", "action": "choisissez une boisson habituelle et testez une modification acceptable : moins de sirop, eau pétillante ou format différent. Gardez celle qui vous convient. Le but n’est pas de boire de l’eau pour repousser une faim réelle.", "question": "Quel ajustement préserverait le plaisir de manger?", "sources": [{"id": "S14", "title": "Santé Canada.", "url": "https://www.canada.ca/fr/sante-canada/services/guide-alimentaire/explorez/recommandations-matiere-alimentation-saine.html"}, {"id": "S13", "title": "Ello-Martin et coll., American Journal of Clinical Nutrition, 2007.", "url": "https://pubmed.ncbi.nlm.nih.gov/17556681/"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('de1e7ca7-8e61-5729-900f-d7f6e48e0c98','34c4b4e1-445a-57ca-9d47-c24e3ef74825',48,'review','{"title": "Repérer huiles, sauces et garnitures", "objective": "disposer d’un outil supplémentaire, sans réduire l’alimentation à un code de couleur. Les preuves sur la densité énergétique ne valident pas automatiquement un système commercial précis.", "body": "Les ajouts peuvent modifier sensiblement l’énergie d’une recette. Ils contribuent aussi au plaisir. Une réduction modérée est parfois suffisante ; enlever toute matière grasse n’est pas nécessaire.", "action": "mesurez l’huile d’une recette une fois au lieu de la verser directement. Essayez un peu moins si la cuisson et le goût restent satisfaisants. Notez la quantité réellement utilisée pour pouvoir refaire la recette, sans chercher automatiquement la version la plus légère.", "question": "Quel ajustement préserverait le plaisir de manger?", "sources": [{"id": "S12", "title": "NIDDK.", "url": "https://www.niddk.nih.gov/health-information/weight-management/myths-nutrition-physical-activity/"}, {"id": "S13", "title": "Ello-Martin et coll., American Journal of Clinical Nutrition, 2007.", "url": "https://pubmed.ncbi.nlm.nih.gov/17556681/"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('aa7b1cde-5d70-5876-a843-db138c7860e9','34c4b4e1-445a-57ca-9d47-c24e3ef74825',49,'review','{"title": "Adapter une recette sans perdre son identité", "objective": "disposer d’un outil supplémentaire, sans réduire l’alimentation à un code de couleur. Les preuves sur la densité énergétique ne valident pas automatiquement un système commercial précis.", "body": "Une bonne adaptation garde ce qui rend le plat désirable. Modifier trop d’éléments peut produire un repas peu satisfaisant que vous ne voudrez pas répéter.", "action": "choisissez une seule modification : ajouter des haricots au chili, augmenter les légumes d’une sauce ou réduire légèrement l’huile. Faites goûter avant de changer autre chose. Évaluez sur trois critères : plaisir, facilité et confort. Une adaptation qui réussit à ces trois tests mérite une place dans votre répertoire.", "question": "Quel ajustement préserverait le plaisir de manger?", "sources": [{"id": "S13", "title": "Ello-Martin et coll., American Journal of Clinical Nutrition, 2007.", "url": "https://pubmed.ncbi.nlm.nih.gov/17556681/"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('6dc04f8d-4632-543c-af25-0057e9aa0fdf','34c4b4e1-445a-57ca-9d47-c24e3ef74825',50,'review','{"title": "Conserver ses aliments préférés", "objective": "disposer d’un outil supplémentaire, sans réduire l’alimentation à un code de couleur. Les preuves sur la densité énergétique ne valident pas automatiquement un système commercial précis.", "body": "Un aliment plaisir peut être prévu, spontané ou partagé. Il n’a pas besoin d’être « mérité ». L’objectif est de trouver une place compatible avec votre santé et votre satisfaction, sans fabriquer une dernière occasion d’en profiter.", "action": "choisissez un aliment que vous aimez et mangez-le dans des conditions agréables. Demandez-vous ensuite ce qui a compté : saveur, quantité, compagnie ou moment. Servez-vous de cette information pour préserver le plaisir avec davantage de choix.", "question": "Quel ajustement préserverait le plaisir de manger?", "sources": [{"id": "S13", "title": "Ello-Martin et coll., American Journal of Clinical Nutrition, 2007.", "url": "https://pubmed.ncbi.nlm.nih.gov/17556681/"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('9ebb8eb7-26ee-5015-a30b-f6e1059c44c0','9048f60d-6d6d-5033-b6ea-f28ca21b63fb',51,'review','{"title": "Distinguer faim physique et envie de manger", "objective": "utiliser vos sensations comme informations, avec souplesse. La faim peut être discrète, perturbée par un traitement ou difficile à identifier. Un horaire de repas reste parfois nécessaire. Vous n’avez pas besoin de prouver votre faim pour avoir le droit de manger.", "body": "La faim renvoie au besoin de manger ; une envie peut être liée au plaisir, au contexte ou à une émotion. Elles se chevauchent souvent. Une envie précise n’exclut pas la faim, et manger pour le plaisir n’est pas automatiquement problématique.", "action": "devant une envie, demandez-vous : « Quelles sensations physiques sont présentes ? Depuis quand ai-je mangé ? Qu’est-ce qui m’attire ? » Choisissez ensuite ce qui vous convient. Évitez le faux test « si je ne veux pas une pomme, je n’ai pas faim ».", "question": "Qu’ai-je ressenti, sans chercher à forcer une réponse?", "sources": [{"id": "S18", "title": "Santé Canada.", "url": "https://www.canada.ca/fr/sante-canada/services/guide-alimentaire/explorez/recommandations-matiere-alimentation-saine/prenez-conscience-habitudes-alimentaires.html"}, {"id": "S25", "title": "NICE, NG69, 2017, version en ligne consultée.", "url": "https://www.nice.org.uk/guidance/ng69/chapter/recommendations"}, {"id": "S29", "title": "American College of Lifestyle Medicine, American Society for Nutrition, Obesity Medicine Association et The Obesity Society, 2025.", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC12125019/"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('451ef3e9-90f7-5078-b41a-965eb1e2983d','9048f60d-6d6d-5033-b6ea-f28ca21b63fb',52,'review','{"title": "Reconnaître ses premiers signes de faim", "objective": "utiliser vos sensations comme informations, avec souplesse. La faim peut être discrète, perturbée par un traitement ou difficile à identifier. Un horaire de repas reste parfois nécessaire. Vous n’avez pas besoin de prouver votre faim pour avoir le droit de manger.", "body": "La faim ne se manifeste pas uniquement par un ventre qui gargouille. Certains remarquent surtout une baisse de concentration ou une irritabilité. Ces sensations peuvent aussi avoir d’autres causes : leur interprétation demande du contexte.", "action": "avant un repas habituel, notez un signe que vous remarquez, puis ce qui change après. Avec le temps, construisez votre vocabulaire personnel. Des malaises répétés, tremblements ou étourdissements méritent une évaluation ; ils ne doivent pas devenir un exercice de tolérance à la faim.", "question": "Qu’ai-je ressenti, sans chercher à forcer une réponse?", "sources": [{"id": "S18", "title": "Santé Canada.", "url": "https://www.canada.ca/fr/sante-canada/services/guide-alimentaire/explorez/recommandations-matiere-alimentation-saine/prenez-conscience-habitudes-alimentaires.html"}, {"id": "S25", "title": "NICE, NG69, 2017, version en ligne consultée.", "url": "https://www.nice.org.uk/guidance/ng69/chapter/recommendations"}, {"id": "S29", "title": "American College of Lifestyle Medicine, American Society for Nutrition, Obesity Medicine Association et The Obesity Society, 2025.", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC12125019/"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('bdc0e5c8-e8d3-5f9a-a812-449e5b79695a','9048f60d-6d6d-5033-b6ea-f28ca21b63fb',53,'review','{"title": "Observer l’intensité de sa faim", "objective": "utiliser vos sensations comme informations, avec souplesse. La faim peut être discrète, perturbée par un traitement ou difficile à identifier. Un horaire de repas reste parfois nécessaire. Vous n’avez pas besoin de prouver votre faim pour avoir le droit de manger.", "body": "L’intensité varie d’un repas à l’autre selon l’activité, le repas précédent et la journée. L’objectif n’est pas de maintenir une faim basse en permanence, mais de mieux préparer vos réponses.", "action": "utilisez trois mots : faible, présente, forte. Cela suffit souvent. Si vous arrivez fréquemment au souper avec une faim très forte, examinez le dîner et les horaires. Une collation ou un dîner plus nourrissant peut être plus utile qu’une consigne de contrôle au souper.", "question": "Qu’ai-je ressenti, sans chercher à forcer une réponse?", "sources": [{"id": "S18", "title": "Santé Canada.", "url": "https://www.canada.ca/fr/sante-canada/services/guide-alimentaire/explorez/recommandations-matiere-alimentation-saine/prenez-conscience-habitudes-alimentaires.html"}, {"id": "S25", "title": "NICE, NG69, 2017, version en ligne consultée.", "url": "https://www.nice.org.uk/guidance/ng69/chapter/recommendations"}, {"id": "S29", "title": "American College of Lifestyle Medicine, American Society for Nutrition, Obesity Medicine Association et The Obesity Society, 2025.", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC12125019/"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('bfe97a5f-4931-5979-8c01-cdc6e98d2236','9048f60d-6d6d-5033-b6ea-f28ca21b63fb',54,'review','{"title": "Utiliser une échelle souple", "objective": "utiliser vos sensations comme informations, avec souplesse. La faim peut être discrète, perturbée par un traitement ou difficile à identifier. Un horaire de repas reste parfois nécessaire. Vous n’avez pas besoin de prouver votre faim pour avoir le droit de manger.", "body": "Une échelle donne un langage aux sensations, pas une autorisation de manger. Pour ce manuel, vous pouvez utiliser : 0 = faim très forte ; 5 = état neutre ; 10 = inconfort d’avoir trop mangé. Ce repère pédagogique n’est pas une mesure médicale.", "action": "notez approximativement votre sensation avant et après un repas, sans viser un chiffre obligatoire. Si les nombres vous rigidifient, utilisez simplement « faim », « confortable » et « trop plein ». Les besoins médicaux passent avant cette échelle.", "question": "Qu’ai-je ressenti, sans chercher à forcer une réponse?", "sources": [{"id": "S18", "title": "Santé Canada.", "url": "https://www.canada.ca/fr/sante-canada/services/guide-alimentaire/explorez/recommandations-matiere-alimentation-saine/prenez-conscience-habitudes-alimentaires.html"}, {"id": "S25", "title": "NICE, NG69, 2017, version en ligne consultée.", "url": "https://www.nice.org.uk/guidance/ng69/chapter/recommendations"}, {"id": "S29", "title": "American College of Lifestyle Medicine, American Society for Nutrition, Obesity Medicine Association et The Obesity Society, 2025.", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC12125019/"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('74ec4e76-2055-5064-b537-3cc596246739','9048f60d-6d6d-5033-b6ea-f28ca21b63fb',55,'review','{"title": "Distinguer appétit, plaisir et besoin énergétique", "objective": "utiliser vos sensations comme informations, avec souplesse. La faim peut être discrète, perturbée par un traitement ou difficile à identifier. Un horaire de repas reste parfois nécessaire. Vous n’avez pas besoin de prouver votre faim pour avoir le droit de manger.", "body": "Un plat attirant peut ouvrir l’appétit même après un repas. À l’inverse, stress ou médicament peuvent réduire l’envie malgré des besoins nutritionnels. Les sensations sont utiles, mais ne suffisent pas toujours à assurer des apports adéquats.", "action": "imaginez deux situations : un dessert partagé après un souper et un dîner oublié faute d’appétit. Dans la première, choisissez votre plaisir ; dans la seconde, cherchez une façon de vous nourrir. La même règle ne convient pas nécessairement aux deux.", "question": "Qu’ai-je ressenti, sans chercher à forcer une réponse?", "sources": [{"id": "S18", "title": "Santé Canada.", "url": "https://www.canada.ca/fr/sante-canada/services/guide-alimentaire/explorez/recommandations-matiere-alimentation-saine/prenez-conscience-habitudes-alimentaires.html"}, {"id": "S25", "title": "NICE, NG69, 2017, version en ligne consultée.", "url": "https://www.nice.org.uk/guidance/ng69/chapter/recommendations"}, {"id": "S29", "title": "American College of Lifestyle Medicine, American Society for Nutrition, Obesity Medicine Association et The Obesity Society, 2025.", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC12125019/"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('6b456526-f21e-5b2e-854f-08c7abbd7b87','9048f60d-6d6d-5033-b6ea-f28ca21b63fb',56,'review','{"title": "Reconnaître le rassasiement pendant le repas", "objective": "utiliser vos sensations comme informations, avec souplesse. La faim peut être discrète, perturbée par un traitement ou difficile à identifier. Un horaire de repas reste parfois nécessaire. Vous n’avez pas besoin de prouver votre faim pour avoir le droit de manger.", "body": "Le rassasiement est le processus qui contribue à terminer le repas. Il peut s’exprimer par une diminution de la faim, un confort physique ou une moindre envie de poursuivre. Vous n’avez pas besoin d’attendre l’inconfort.", "action": "à un moment naturel, posez brièvement vos ustensiles. Demandez-vous si vous souhaitez continuer, vous resservir ou garder le reste. Toutes ces réponses sont possibles. Si vos signaux sont peu fiables, utilisez aussi la structure de repas convenue avec un professionnel.", "question": "Qu’ai-je ressenti, sans chercher à forcer une réponse?", "sources": [{"id": "S18", "title": "Santé Canada.", "url": "https://www.canada.ca/fr/sante-canada/services/guide-alimentaire/explorez/recommandations-matiere-alimentation-saine/prenez-conscience-habitudes-alimentaires.html"}, {"id": "S25", "title": "NICE, NG69, 2017, version en ligne consultée.", "url": "https://www.nice.org.uk/guidance/ng69/chapter/recommendations"}, {"id": "S29", "title": "American College of Lifestyle Medicine, American Society for Nutrition, Obesity Medicine Association et The Obesity Society, 2025.", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC12125019/"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('02aa8077-0667-54ef-a93b-716ef3a9906e','9048f60d-6d6d-5033-b6ea-f28ca21b63fb',57,'review','{"title": "Observer combien de temps un repas vous soutient", "objective": "utiliser vos sensations comme informations, avec souplesse. La faim peut être discrète, perturbée par un traitement ou difficile à identifier. Un horaire de repas reste parfois nécessaire. Vous n’avez pas besoin de prouver votre faim pour avoir le droit de manger.", "body": "La satiété correspond à la période pendant laquelle la faim reste atténuée après le repas. Sa durée varie ; il n’existe pas un nombre d’heures que chaque repas doit obligatoirement couvrir.", "action": "comparez deux déjeuners habituels sur des journées semblables. Notez approximativement le retour de la faim, l’énergie et le plaisir. Si l’un vous soutient moins, testez un ajout nourrissant. N’utilisez pas la durée sans manger comme un score de réussite.", "question": "Qu’ai-je ressenti, sans chercher à forcer une réponse?", "sources": [{"id": "S18", "title": "Santé Canada.", "url": "https://www.canada.ca/fr/sante-canada/services/guide-alimentaire/explorez/recommandations-matiere-alimentation-saine/prenez-conscience-habitudes-alimentaires.html"}, {"id": "S25", "title": "NICE, NG69, 2017, version en ligne consultée.", "url": "https://www.nice.org.uk/guidance/ng69/chapter/recommendations"}, {"id": "S29", "title": "American College of Lifestyle Medicine, American Society for Nutrition, Obesity Medicine Association et The Obesity Society, 2025.", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC12125019/"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('6304fe46-e420-5908-942f-4be8c1a4395f','9048f60d-6d6d-5033-b6ea-f28ca21b63fb',58,'review','{"title": "Reconnaître l’inconfort d’avoir trop mangé", "objective": "utiliser vos sensations comme informations, avec souplesse. La faim peut être discrète, perturbée par un traitement ou difficile à identifier. Un horaire de repas reste parfois nécessaire. Vous n’avez pas besoin de prouver votre faim pour avoir le droit de manger.", "body": "Un repas plus copieux peut laisser une lourdeur. Cela arrive et ne réclame pas de punition. L’information utile concerne ce qui a contribué à cet inconfort : vitesse, portion, faim préalable ou difficulté à s’arrêter.", "action": "revenez à vos repas habituels en tenant compte de votre confort. Notez un ajustement possible pour une prochaine occasion. Si les douleurs, vomissements ou inconforts importants se répètent, consultez : toute gêne digestive ne s’explique pas par une portion trop grande.", "question": "Qu’ai-je ressenti, sans chercher à forcer une réponse?", "sources": [{"id": "S18", "title": "Santé Canada.", "url": "https://www.canada.ca/fr/sante-canada/services/guide-alimentaire/explorez/recommandations-matiere-alimentation-saine/prenez-conscience-habitudes-alimentaires.html"}, {"id": "S25", "title": "NICE, NG69, 2017, version en ligne consultée.", "url": "https://www.nice.org.uk/guidance/ng69/chapter/recommendations"}, {"id": "S29", "title": "American College of Lifestyle Medicine, American Society for Nutrition, Obesity Medicine Association et The Obesity Society, 2025.", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC12125019/"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('a41f8c1d-b956-568b-b522-dacc745796ee','9048f60d-6d6d-5033-b6ea-f28ca21b63fb',59,'review','{"title": "Comprendre l’effet d’une faim très forte", "objective": "utiliser vos sensations comme informations, avec souplesse. La faim peut être discrète, perturbée par un traitement ou difficile à identifier. Un horaire de repas reste parfois nécessaire. Vous n’avez pas besoin de prouver votre faim pour avoir le droit de manger.", "body": "Lorsque manger devient urgent, décider calmement peut être difficile. Vous n’avez pas à apprendre à ignorer cette urgence pour progresser. La prévention peut se situer plusieurs heures avant le moment problématique.", "action": "pour une journée où le souper sera tardif, prévoyez une collation accessible : yogourt et fruit, pain et fromage, ou autre combinaison tolérée. Comparez votre arrivée à la maison avec les jours sans cette préparation. Ajustez selon votre appétit, vos horaires et vos soins.", "question": "Qu’ai-je ressenti, sans chercher à forcer une réponse?", "sources": [{"id": "S18", "title": "Santé Canada.", "url": "https://www.canada.ca/fr/sante-canada/services/guide-alimentaire/explorez/recommandations-matiere-alimentation-saine/prenez-conscience-habitudes-alimentaires.html"}, {"id": "S25", "title": "NICE, NG69, 2017, version en ligne consultée.", "url": "https://www.nice.org.uk/guidance/ng69/chapter/recommendations"}, {"id": "S29", "title": "American College of Lifestyle Medicine, American Society for Nutrition, Obesity Medicine Association et The Obesity Society, 2025.", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC12125019/"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('d2bac6fc-9d7f-5930-b662-3d0e24d8453f','9048f60d-6d6d-5033-b6ea-f28ca21b63fb',60,'review','{"title": "Ajuster les portions à ses besoins du moment", "objective": "utiliser vos sensations comme informations, avec souplesse. La faim peut être discrète, perturbée par un traitement ou difficile à identifier. Un horaire de repas reste parfois nécessaire. Vous n’avez pas besoin de prouver votre faim pour avoir le droit de manger.", "body": "Les portions ne doivent pas être identiques tous les jours. Vous pouvez avoir davantage faim après une journée active ou moins d’appétit un autre jour. L’ajustement reste compatible avec des repères structurés.", "action": "commencez par une portion habituelle, puis gardez la possibilité de compléter. Demandez-vous si votre repas est suffisant en variété autant qu’en quantité. Une réduction importante et persistante de l’appétit, notamment sous traitement, mérite d’être discutée plutôt que célébrée automatiquement.", "question": "Qu’ai-je ressenti, sans chercher à forcer une réponse?", "sources": [{"id": "S18", "title": "Santé Canada.", "url": "https://www.canada.ca/fr/sante-canada/services/guide-alimentaire/explorez/recommandations-matiere-alimentation-saine/prenez-conscience-habitudes-alimentaires.html"}, {"id": "S25", "title": "NICE, NG69, 2017, version en ligne consultée.", "url": "https://www.nice.org.uk/guidance/ng69/chapter/recommendations"}, {"id": "S29", "title": "American College of Lifestyle Medicine, American Society for Nutrition, Obesity Medicine Association et The Obesity Society, 2025.", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC12125019/"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('b1513de6-2ddf-5f13-8a89-41b9d086c419','93683a7d-6b0a-56c3-813a-461fba3bbc58',61,'review','{"title": "Sortir du pilote automatique", "objective": "mieux remarquer votre expérience. L’alimentation attentive peut aider certains comportements, mais ses effets propres sur le poids sont variables. Elle complète les autres moyens ; elle ne garantit pas une perte de poids.", "body": "Il est possible de finir un repas en se rappelant surtout les messages lus en même temps. Retrouver quelques moments de présence peut suffire pour commencer. Aucun repas ne doit devenir une séance d’observation intensive.", "action": "avant la première bouchée, regardez votre repas et nommez ce que vous allez manger. Une phrase suffit. Puis mangez normalement. Si cela vous paraît artificiel, utilisez un repère plus naturel : vous asseoir ou prendre votre repas dans une assiette.", "question": "Quel moment du repas aimerais-je savourer davantage?", "sources": [{"id": "S19", "title": "Santé Canada.", "url": "https://www.canada.ca/fr/sante-canada/services/guide-alimentaire/explorez/recommandations-matiere-alimentation-saine/prenez-conscience-habitudes-alimentaires/prenez-temps-manger.html"}, {"id": "S20", "title": "NCCIH, National Institutes of Health.", "url": "https://www.nccih.nih.gov/health/meditation-and-mindfulness-effectiveness-and-safety"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('1088967f-f1bf-5284-b04e-083a143f7e5a','93683a7d-6b0a-56c3-813a-461fba3bbc58',62,'review','{"title": "Réduire les distractions", "objective": "mieux remarquer votre expérience. L’alimentation attentive peut aider certains comportements, mais ses effets propres sur le poids sont variables. Elle complète les autres moyens ; elle ne garantit pas une perte de poids.", "body": "Un écran, une réunion ou une tâche parallèle peuvent limiter l’attention disponible. Tout le monde ne peut pas manger dans le calme, notamment au travail ou avec de jeunes enfants. Cherchez une amélioration partielle.", "action": "choisissez les premières minutes d’un repas sans téléphone. Comparez votre expérience, sans obligation de manger moins. Si un silence complet vous rend inconfortable, gardez une musique ou une présence agréable. L’objectif est de mieux vivre le repas, pas de supprimer tout environnement.", "question": "Quel moment du repas aimerais-je savourer davantage?", "sources": [{"id": "S19", "title": "Santé Canada.", "url": "https://www.canada.ca/fr/sante-canada/services/guide-alimentaire/explorez/recommandations-matiere-alimentation-saine/prenez-conscience-habitudes-alimentaires/prenez-temps-manger.html"}, {"id": "S20", "title": "NCCIH, National Institutes of Health.", "url": "https://www.nccih.nih.gov/health/meditation-and-mindfulness-effectiveness-and-safety"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('81326d93-b23a-5062-b976-4f7b6996bde6','93683a7d-6b0a-56c3-813a-461fba3bbc58',63,'review','{"title": "Observer saveurs, textures et odeurs", "objective": "mieux remarquer votre expérience. L’alimentation attentive peut aider certains comportements, mais ses effets propres sur le poids sont variables. Elle complète les autres moyens ; elle ne garantit pas une perte de poids.", "body": "Les qualités sensorielles permettent de reconnaître ce qui vous plaît réellement. Vous découvrirez peut-être qu’un aliment habituel ne vous satisfait pas autant que prévu, ou qu’une petite garniture change beaucoup le repas.", "action": "prenez une bouchée et trouvez trois mots simples : croquant, acidulé, chaud. Demandez-vous ce qui rendrait le repas plus agréable. Vous pouvez ajouter une épice, une texture ou un accompagnement. Un repas satisfaisant n’est pas nécessairement le plus compliqué.", "question": "Quel moment du repas aimerais-je savourer davantage?", "sources": [{"id": "S19", "title": "Santé Canada.", "url": "https://www.canada.ca/fr/sante-canada/services/guide-alimentaire/explorez/recommandations-matiere-alimentation-saine/prenez-conscience-habitudes-alimentaires/prenez-temps-manger.html"}, {"id": "S20", "title": "NCCIH, National Institutes of Health.", "url": "https://www.nccih.nih.gov/health/meditation-and-mindfulness-effectiveness-and-safety"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('0a0043a8-954e-5c4e-abb7-5523caa1f57f','93683a7d-6b0a-56c3-813a-461fba3bbc58',64,'review','{"title": "Ralentir suffisamment pour remarquer", "objective": "mieux remarquer votre expérience. L’alimentation attentive peut aider certains comportements, mais ses effets propres sur le poids sont variables. Elle complète les autres moyens ; elle ne garantit pas une perte de poids.", "body": "Ralentir signifie créer une occasion de percevoir le repas. Il n’est pas nécessaire de compter les mastications ou de respecter une durée universelle. Ces règles peuvent devenir pénibles sans apporter davantage d’utilité.", "action": "posez votre ustensile une fois ou prenez une courte pause entre deux portions. Si votre horaire oblige à manger vite, préparez un repas facile à consommer et cherchez à protéger un peu de temps. Le problème peut être organisationnel plutôt qu’un manque d’attention.", "question": "Quel moment du repas aimerais-je savourer davantage?", "sources": [{"id": "S19", "title": "Santé Canada.", "url": "https://www.canada.ca/fr/sante-canada/services/guide-alimentaire/explorez/recommandations-matiere-alimentation-saine/prenez-conscience-habitudes-alimentaires/prenez-temps-manger.html"}, {"id": "S20", "title": "NCCIH, National Institutes of Health.", "url": "https://www.nccih.nih.gov/health/meditation-and-mindfulness-effectiveness-and-safety"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('4a7cadd2-157c-5807-97c3-1e8c5bada1cf','93683a7d-6b0a-56c3-813a-461fba3bbc58',65,'review','{"title": "Faire une pause au milieu du repas", "objective": "mieux remarquer votre expérience. L’alimentation attentive peut aider certains comportements, mais ses effets propres sur le poids sont variables. Elle complète les autres moyens ; elle ne garantit pas une perte de poids.", "body": "Une pause sert à vérifier où vous en êtes. Elle ne doit pas devenir un moyen de vous convaincre d’arrêter malgré la faim.", "action": "à mi-repas approximativement, demandez-vous : « ai-je encore faim ? Est-ce agréable ? Suis-je confortable ? » Reprenez ensuite selon votre réponse. Si vous avez besoin de finir rapidement, une seconde de vérification peut suffire. Vous n’avez pas à transformer chaque repas en exercice formel.", "question": "Quel moment du repas aimerais-je savourer davantage?", "sources": [{"id": "S19", "title": "Santé Canada.", "url": "https://www.canada.ca/fr/sante-canada/services/guide-alimentaire/explorez/recommandations-matiere-alimentation-saine/prenez-conscience-habitudes-alimentaires/prenez-temps-manger.html"}, {"id": "S20", "title": "NCCIH, National Institutes of Health.", "url": "https://www.nccih.nih.gov/health/meditation-and-mindfulness-effectiveness-and-safety"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('75e11d82-276e-5888-8d67-e0568d07d792','93683a7d-6b0a-56c3-813a-461fba3bbc58',66,'review','{"title": "Vérifier si le plaisir est encore présent", "objective": "mieux remarquer votre expérience. L’alimentation attentive peut aider certains comportements, mais ses effets propres sur le poids sont variables. Elle complète les autres moyens ; elle ne garantit pas une perte de poids.", "body": "Le goût et l’intérêt peuvent évoluer au fil du repas. Parfois, on poursuit parce que l’aliment est devant soi ; parfois, le plaisir reste bien présent. Observer permet de choisir sans appliquer une règle extérieure.", "action": "avec un aliment apprécié, remarquez une bouchée au début et une autre plus tard. Si le plaisir diminue, vous pouvez conserver le reste. S’il demeure et que vous êtes confortable, vous pouvez continuer. Évitez de faire de la moindre baisse de plaisir une obligation d’arrêt.", "question": "Quel moment du repas aimerais-je savourer davantage?", "sources": [{"id": "S19", "title": "Santé Canada.", "url": "https://www.canada.ca/fr/sante-canada/services/guide-alimentaire/explorez/recommandations-matiere-alimentation-saine/prenez-conscience-habitudes-alimentaires/prenez-temps-manger.html"}, {"id": "S20", "title": "NCCIH, National Institutes of Health.", "url": "https://www.nccih.nih.gov/health/meditation-and-mindfulness-effectiveness-and-safety"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('fffe4ecd-afd7-5ba0-9045-00665ca67735','93683a7d-6b0a-56c3-813a-461fba3bbc58',67,'review','{"title": "Distinguer satisfaction et estomac plein", "objective": "mieux remarquer votre expérience. L’alimentation attentive peut aider certains comportements, mais ses effets propres sur le poids sont variables. Elle complète les autres moyens ; elle ne garantit pas une perte de poids.", "body": "On peut avoir mangé un grand volume sans se sentir satisfait du repas. Il peut manquer du goût, de la variété ou un aliment dont on avait envie. Augmenter le volume n’est pas toujours la solution.", "action": "après un repas peu satisfaisant, nommez ce qui manquait : chaleur, croquant, féculent, dessert, temps. Testez un ajustement la prochaine fois. L’objectif est de construire un repas qui nourrit et plaît, sans conclure que toute envie après le repas est un problème.", "question": "Quel moment du repas aimerais-je savourer davantage?", "sources": [{"id": "S19", "title": "Santé Canada.", "url": "https://www.canada.ca/fr/sante-canada/services/guide-alimentaire/explorez/recommandations-matiere-alimentation-saine/prenez-conscience-habitudes-alimentaires/prenez-temps-manger.html"}, {"id": "S20", "title": "NCCIH, National Institutes of Health.", "url": "https://www.nccih.nih.gov/health/meditation-and-mindfulness-effectiveness-and-safety"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('7fa5d703-1513-5901-98ce-a73e18e81201','93683a7d-6b0a-56c3-813a-461fba3bbc58',68,'review','{"title": "Choisir consciemment de se resservir", "objective": "mieux remarquer votre expérience. L’alimentation attentive peut aider certains comportements, mais ses effets propres sur le poids sont variables. Elle complète les autres moyens ; elle ne garantit pas une perte de poids.", "body": "Se resservir peut répondre à une faim réelle, à une portion initiale trop petite ou à l’envie de prolonger le plaisir. L’important est de pouvoir choisir, pas d’interdire la deuxième portion.", "action": "avant de vous resservir, demandez-vous ce que vous souhaitez encore manger. Peut-être davantage de tout, ou seulement une composante. Servez-vous et observez votre confort. Si la première portion était insuffisante, utilisez cette information pour mieux prévoir le prochain repas.", "question": "Quel moment du repas aimerais-je savourer davantage?", "sources": [{"id": "S19", "title": "Santé Canada.", "url": "https://www.canada.ca/fr/sante-canada/services/guide-alimentaire/explorez/recommandations-matiere-alimentation-saine/prenez-conscience-habitudes-alimentaires/prenez-temps-manger.html"}, {"id": "S20", "title": "NCCIH, National Institutes of Health.", "url": "https://www.nccih.nih.gov/health/meditation-and-mindfulness-effectiveness-and-safety"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('90dc4fd8-867e-51c8-b1f8-880c71392a30','93683a7d-6b0a-56c3-813a-461fba3bbc58',69,'review','{"title": "S’autoriser à laisser de la nourriture", "objective": "mieux remarquer votre expérience. L’alimentation attentive peut aider certains comportements, mais ses effets propres sur le poids sont variables. Elle complète les autres moyens ; elle ne garantit pas une perte de poids.", "body": "Finir son assiette n’est pas une obligation. Le souci du gaspillage est légitime, surtout quand le budget est serré, mais manger au-delà du confort ne récupère pas l’argent dépensé.", "action": "servez une première portion avec la possibilité d’en reprendre et prévoyez un contenant pour les restes. Si vous ne pouvez pas conserver un aliment en sécurité, ajustez les quantités la prochaine fois. Prévenir le gaspillage commence surtout à l’achat, à la préparation et au service.", "question": "Quel moment du repas aimerais-je savourer davantage?", "sources": [{"id": "S19", "title": "Santé Canada.", "url": "https://www.canada.ca/fr/sante-canada/services/guide-alimentaire/explorez/recommandations-matiere-alimentation-saine/prenez-conscience-habitudes-alimentaires/prenez-temps-manger.html"}, {"id": "S20", "title": "NCCIH, National Institutes of Health.", "url": "https://www.nccih.nih.gov/health/meditation-and-mindfulness-effectiveness-and-safety"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('d2f68422-d8cc-5d00-8caa-ffa43c41bd31','93683a7d-6b0a-56c3-813a-461fba3bbc58',70,'review','{"title": "Savourer sans culpabiliser", "objective": "mieux remarquer votre expérience. L’alimentation attentive peut aider certains comportements, mais ses effets propres sur le poids sont variables. Elle complète les autres moyens ; elle ne garantit pas une perte de poids.", "body": "La culpabilité peut occuper toute l’attention pendant un aliment pourtant choisi pour le plaisir. Vous avez le droit de profiter d’un repas. Une occasion agréable n’annule pas les autres habitudes.", "action": "choisissez une phrase simple : « ce dessert fait partie de mon repas ». Mangez-le sans prévoir une compensation. Après, revenez à votre journée. Si la culpabilité reste forte et fréquente, prenez-la comme un motif de soutien, pas comme une preuve que l’aliment aurait dû être interdit.", "question": "Quel moment du repas aimerais-je savourer davantage?", "sources": [{"id": "S19", "title": "Santé Canada.", "url": "https://www.canada.ca/fr/sante-canada/services/guide-alimentaire/explorez/recommandations-matiere-alimentation-saine/prenez-conscience-habitudes-alimentaires/prenez-temps-manger.html"}, {"id": "S20", "title": "NCCIH, National Institutes of Health.", "url": "https://www.nccih.nih.gov/health/meditation-and-mindfulness-effectiveness-and-safety"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('e3b963a1-3308-5cc2-a38d-a55e75c00d8d','66e3a23d-5b8b-507d-a534-0869a903a1c8',71,'review','{"title": "Relier pensées, émotions et comportements", "objective": "remarquer les interprétations qui vous enferment. Les outils inspirés de la thérapie cognitivo-comportementale aident à examiner une pensée, sans prétendre que les difficultés matérielles ou médicales sont imaginaires.", "body": "Un même événement peut provoquer différentes réactions selon l’interprétation. Un repas imprévu peut être vécu comme une adaptation ou comme un échec total. Ce lien ne signifie pas que vous choisissez volontairement vos émotions.", "action": "décrivez une situation en quatre lignes : événement, pensée, émotion, action. Exemple : « dîner commandé ; j’ai raté ma semaine ; découragement ; j’abandonne ma planification ». Cherchez ensuite un endroit où vous pourriez agir : prévoir une option de commande acceptable.", "question": "Quelle autre lecture de la situation me semblerait plus juste?", "sources": [{"id": "S21", "title": "NHS, Every Mind Matters.", "url": "https://www.nhs.uk/every-mind-matters/mental-wellbeing-tips/self-help-cbt-techniques/reframing-unhelpful-thoughts/"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('d1c60947-e9b5-517f-8cee-9ca7c073f547','66e3a23d-5b8b-507d-a534-0869a903a1c8',72,'review','{"title": "Repérer le tout ou rien", "objective": "remarquer les interprétations qui vous enferment. Les outils inspirés de la thérapie cognitivo-comportementale aident à examiner une pensée, sans prétendre que les difficultés matérielles ou médicales sont imaginaires.", "body": "La pensée tout ou rien ne laisse que deux résultats : parfait ou inutile. Elle efface les progrès partiels. Une promenade plus courte ou un repas simplement assemblé deviennent alors invisibles.", "action": "imaginez trois niveaux pour une habitude : version minimale, habituelle et plus ambitieuse. Pour cuisiner : assembler une assiette, faire une recette simple, préparer plusieurs composantes. Une journée chargée peut appeler la version minimale sans annuler votre démarche.", "question": "Quelle autre lecture de la situation me semblerait plus juste?", "sources": [{"id": "S21", "title": "NHS, Every Mind Matters.", "url": "https://www.nhs.uk/every-mind-matters/mental-wellbeing-tips/self-help-cbt-techniques/reframing-unhelpful-thoughts/"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('b56dc0a8-621d-5f49-9990-f3c7ba020ad3','66e3a23d-5b8b-507d-a534-0869a903a1c8',73,'review','{"title": "Reconnaître les règles trop rigides", "objective": "remarquer les interprétations qui vous enferment. Les outils inspirés de la thérapie cognitivo-comportementale aident à examiner une pensée, sans prétendre que les difficultés matérielles ou médicales sont imaginaires.", "body": "« Jamais de pain », « toujours cuisiner », « ne rien manger après telle heure » peuvent devenir difficiles à concilier avec la vie réelle. Une règle médicale spécifique est différente et doit être discutée avec le soignant.", "action": "prenez une règle personnelle et transformez-la en préférence souple. « Je dois toujours cuisiner » devient « j’aime avoir des repas maison et deux options de dépannage ». Vérifiez si cette version protège votre objectif tout en laissant de la place aux imprévus.", "question": "Quelle autre lecture de la situation me semblerait plus juste?", "sources": [{"id": "S21", "title": "NHS, Every Mind Matters.", "url": "https://www.nhs.uk/every-mind-matters/mental-wellbeing-tips/self-help-cbt-techniques/reframing-unhelpful-thoughts/"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('233e9432-53e1-5290-b149-03f1b17ba23e','66e3a23d-5b8b-507d-a534-0869a903a1c8',74,'review','{"title": "Ne pas transformer un repas en verdict", "objective": "remarquer les interprétations qui vous enferment. Les outils inspirés de la thérapie cognitivo-comportementale aident à examiner une pensée, sans prétendre que les difficultés matérielles ou médicales sont imaginaires.", "body": "Un épisode ne décrit pas toute une semaine. Le jugement global peut créer davantage de difficultés que le repas lui-même, en poussant à abandonner ou à compenser.", "action": "après un souper plus copieux, écrivez une phrase limitée dans le temps : « ce souper était plus copieux que prévu ». Décidez ensuite d’une action ordinaire : reprendre votre déjeuner habituel ou préparer votre dîner. Vous n’avez pas à sauver une journée déjà terminée.", "question": "Quelle autre lecture de la situation me semblerait plus juste?", "sources": [{"id": "S21", "title": "NHS, Every Mind Matters.", "url": "https://www.nhs.uk/every-mind-matters/mental-wellbeing-tips/self-help-cbt-techniques/reframing-unhelpful-thoughts/"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('5f816a67-ea6d-570a-8449-ca0506514723','66e3a23d-5b8b-507d-a534-0869a903a1c8',75,'review','{"title": "Repérer les généralisations", "objective": "remarquer les interprétations qui vous enferment. Les outils inspirés de la thérapie cognitivo-comportementale aident à examiner une pensée, sans prétendre que les difficultés matérielles ou médicales sont imaginaires.", "body": "Les mots « toujours » et « jamais » transforment une difficulté répétée en identité fixe. Ils peuvent masquer des exceptions utiles : un contexte où vous avez déjà trouvé une solution.", "action": "remplacez « je ne planifie jamais » par « je planifie rarement les jours de réunion tardive ». Cherchez une exception : « mercredi, un repas simple était prêt ». Identifiez ce qui l’a rendue possible. Cette précision donne une piste de travail bien plus concrète qu’une critique générale.", "question": "Quelle autre lecture de la situation me semblerait plus juste?", "sources": [{"id": "S21", "title": "NHS, Every Mind Matters.", "url": "https://www.nhs.uk/every-mind-matters/mental-wellbeing-tips/self-help-cbt-techniques/reframing-unhelpful-thoughts/"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('93049d5a-a2f6-5d0f-8846-43e2e81584b6','66e3a23d-5b8b-507d-a534-0869a903a1c8',76,'review','{"title": "Reconnaître les prédictions décourageantes", "objective": "remarquer les interprétations qui vous enferment. Les outils inspirés de la thérapie cognitivo-comportementale aident à examiner une pensée, sans prétendre que les difficultés matérielles ou médicales sont imaginaires.", "body": "« Je vais abandonner » est une prédiction. Votre histoire peut expliquer cette crainte, mais elle ne décrit pas exactement ce qui arrivera avec un plan différent.", "action": "demandez-vous ce qui rendrait l’expérience actuelle différente des précédentes. Un objectif plus petit ? Une douleur prise en charge ? Un suivi régulier ? Écrivez une seule différence et testez-la. Vous n’avez pas besoin d’être certain de réussir pour recueillir de nouvelles informations.", "question": "Quelle autre lecture de la situation me semblerait plus juste?", "sources": [{"id": "S21", "title": "NHS, Every Mind Matters.", "url": "https://www.nhs.uk/every-mind-matters/mental-wellbeing-tips/self-help-cbt-techniques/reframing-unhelpful-thoughts/"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('e9918868-e107-5b0d-b5c1-cc223f796662','66e3a23d-5b8b-507d-a534-0869a903a1c8',77,'review','{"title": "Examiner les suppositions sur les autres", "objective": "remarquer les interprétations qui vous enferment. Les outils inspirés de la thérapie cognitivo-comportementale aident à examiner une pensée, sans prétendre que les difficultés matérielles ou médicales sont imaginaires.", "body": "On ne peut pas toujours savoir ce qu’une personne pense de notre corps ou de notre assiette. Cependant, les remarques stigmatisantes existent réellement. Le but n’est pas de nier une expérience de discrimination.", "action": "séparez « ce qui a été dit ou fait » de « ce que j’imagine ». Si un commentaire a réellement été blessant, préparez une limite : « je préfère qu’on ne commente pas mon assiette ». Si vous êtes incertain, cherchez une interprétation moins définitive.", "question": "Quelle autre lecture de la situation me semblerait plus juste?", "sources": [{"id": "S21", "title": "NHS, Every Mind Matters.", "url": "https://www.nhs.uk/every-mind-matters/mental-wellbeing-tips/self-help-cbt-techniques/reframing-unhelpful-thoughts/"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('eed1233b-e5fa-57b1-a737-60b991167b26','66e3a23d-5b8b-507d-a534-0869a903a1c8',78,'review','{"title": "Distinguer sentiment et fait", "objective": "remarquer les interprétations qui vous enferment. Les outils inspirés de la thérapie cognitivo-comportementale aident à examiner une pensée, sans prétendre que les difficultés matérielles ou médicales sont imaginaires.", "body": "Se sentir incapable est douloureux, mais ne prouve pas que vous n’avez aucune capacité. L’émotion mérite de l’attention ; la conclusion mérite d’être examinée.", "action": "formulez deux phrases : « je me sens découragé » et « j’ai néanmoins accompli __ ». Choisissez un fait modeste et exact, comme avoir acheté un repas pour demain. Le but n’est pas de forcer l’optimisme, mais de laisser plusieurs informations coexister.", "question": "Quelle autre lecture de la situation me semblerait plus juste?", "sources": [{"id": "S21", "title": "NHS, Every Mind Matters.", "url": "https://www.nhs.uk/every-mind-matters/mental-wellbeing-tips/self-help-cbt-techniques/reframing-unhelpful-thoughts/"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('525bf55f-97d0-5baf-a2ca-5984b683b59d','66e3a23d-5b8b-507d-a534-0869a903a1c8',79,'review','{"title": "Reconnaître les étiquettes personnelles", "objective": "remarquer les interprétations qui vous enferment. Les outils inspirés de la thérapie cognitivo-comportementale aident à examiner une pensée, sans prétendre que les difficultés matérielles ou médicales sont imaginaires.", "body": "« Paresseux », « gourmand » ou « sans discipline » résument injustement une personne à une interprétation. Une description de comportement est plus précise et plus modifiable.", "action": "remplacez l’étiquette par une scène : « après neuf heures de travail, je n’ai pas envie de cuisiner ». Demandez-vous ensuite quel soutien convient à cette scène. Vous pouvez agir sur une tâche, une fatigue ou une organisation ; vous n’avez pas à réparer votre valeur personnelle.", "question": "Quelle autre lecture de la situation me semblerait plus juste?", "sources": [{"id": "S21", "title": "NHS, Every Mind Matters.", "url": "https://www.nhs.uk/every-mind-matters/mental-wellbeing-tips/self-help-cbt-techniques/reframing-unhelpful-thoughts/"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('ad79a425-edf0-5d24-97e3-64256f8ab82c','66e3a23d-5b8b-507d-a534-0869a903a1c8',80,'review','{"title": "Repérer les raisonnements qui poussent à abandonner", "objective": "remarquer les interprétations qui vous enferment. Les outils inspirés de la thérapie cognitivo-comportementale aident à examiner une pensée, sans prétendre que les difficultés matérielles ou médicales sont imaginaires.", "body": "Certains raisonnements créent une fausse urgence : « puisque j’ai commencé, autant finir » ou « je reprendrai quand tout sera calme ». Ils repoussent le prochain choix utile.", "action": "préparez une réponse courte : « je peux choisir la suite indépendamment de ce qui vient d’arriver ». Appliquez-la à une petite décision, comme conserver un reste ou préparer le prochain repas. Aucun discours motivant n’est nécessaire : une action ordinaire suffit.", "question": "Quelle autre lecture de la situation me semblerait plus juste?", "sources": [{"id": "S21", "title": "NHS, Every Mind Matters.", "url": "https://www.nhs.uk/every-mind-matters/mental-wellbeing-tips/self-help-cbt-techniques/reframing-unhelpful-thoughts/"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('eed53dce-d686-57e6-93b4-936908af4284','a2bd1a05-e1a3-59b9-8f32-a3ae1fef827c',81,'review','{"title": "Prendre du recul devant une pensée", "objective": "vous soutenir avec des paroles exactes et praticables. L’autocompassion est prometteuse pour le vécu émotionnel des difficultés ; ce n’est pas une méthode de perte de poids démontrée à elle seule.", "body": "Une pensée peut être entendue sans être immédiatement suivie. Ajouter « je remarque que je pense… » peut créer une petite distance, surtout devant une phrase familière.", "action": "remplacez « je n’y arriverai pas » par « je remarque que je prédis un échec ». Puis regardez votre prochaine action possible. Si cette formulation vous paraît trop abstraite, écrivez simplement la pensée sur une feuille et revenez à la tâche concrète.", "question": "Que dirais-je à un proche qui vit la même chose?", "sources": [{"id": "S22", "title": "Hagerman et coll., Appetite, 2023.", "url": "https://pubmed.ncbi.nlm.nih.gov/37619622/"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('c0fd6542-76c3-596c-bd7f-38f2a1a5d16e','a2bd1a05-e1a3-59b9-8f32-a3ae1fef827c',82,'review','{"title": "Examiner les faits", "objective": "vous soutenir avec des paroles exactes et praticables. L’autocompassion est prometteuse pour le vécu émotionnel des difficultés ; ce n’est pas une méthode de perte de poids démontrée à elle seule.", "body": "Chercher les faits consiste à considérer les informations favorables et défavorables à une conclusion. Ce n’est pas chercher à vous convaincre que tout va bien.", "action": "devant « mon plan ne marche pas », notez ce qui s’est amélioré, ce qui reste difficile et ce qui manque pour conclure. Peut-être que vos repas sont réguliers mais que votre sommeil se dégrade. La réponse utile peut être de modifier un élément, plutôt que d’abandonner l’ensemble.", "question": "Que dirais-je à un proche qui vit la même chose?", "sources": [{"id": "S22", "title": "Hagerman et coll., Appetite, 2023.", "url": "https://pubmed.ncbi.nlm.nih.gov/37619622/"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('23e64663-59e3-5253-8f78-64467194305a','a2bd1a05-e1a3-59b9-8f32-a3ae1fef827c',83,'review','{"title": "Chercher une interprétation plus nuancée", "objective": "vous soutenir avec des paroles exactes et praticables. L’autocompassion est prometteuse pour le vécu émotionnel des difficultés ; ce n’est pas une méthode de perte de poids démontrée à elle seule.", "body": "Une pensée alternative doit être crédible. « Tout sera parfait » aide rarement quand on est épuisé. « Cette semaine est difficile et je peux simplifier » reconnaît la réalité et ouvre une possibilité.", "action": "écrivez une phrase comportant « et » : « je suis déçu et j’ai le droit de reprendre doucement ». Associez-la à une action précise. La nuance devient plus utile lorsqu’elle soutient un geste, plutôt qu’un simple exercice de formulation.", "question": "Que dirais-je à un proche qui vit la même chose?", "sources": [{"id": "S22", "title": "Hagerman et coll., Appetite, 2023.", "url": "https://pubmed.ncbi.nlm.nih.gov/37619622/"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('e3518163-ac68-5f3d-9f82-fd521cbfcbe0','a2bd1a05-e1a3-59b9-8f32-a3ae1fef827c',84,'review','{"title": "Remplacer l’autocritique par une réponse constructive", "objective": "vous soutenir avec des paroles exactes et praticables. L’autocompassion est prometteuse pour le vécu émotionnel des difficultés ; ce n’est pas une méthode de perte de poids démontrée à elle seule.", "body": "Une critique utile indique ce qu’on peut modifier. Une attaque personnelle ne le fait pas. « Ce plan demande trop de cuisine » donne une information exploitable ; « je suis nul » n’en donne aucune.", "action": "transformez une critique en problème pratique : trop long, trop coûteux, peu rassasiant, mal placé dans l’horaire. Choisissez ensuite un ajustement. Par exemple, remplacez une recette de quarante minutes par un repas composé d’éléments déjà prêts.", "question": "Que dirais-je à un proche qui vit la même chose?", "sources": [{"id": "S22", "title": "Hagerman et coll., Appetite, 2023.", "url": "https://pubmed.ncbi.nlm.nih.gov/37619622/"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('e9711f88-c49d-5437-96b8-c765da55f0a1','a2bd1a05-e1a3-59b9-8f32-a3ae1fef827c',85,'review','{"title": "Se parler comme à un ami", "objective": "vous soutenir avec des paroles exactes et praticables. L’autocompassion est prometteuse pour le vécu émotionnel des difficultés ; ce n’est pas une méthode de perte de poids démontrée à elle seule.", "body": "Vous ne conseilleriez probablement pas à un ami de se punir pour un repas. Vous chercheriez à comprendre ce qui l’a rendu difficile. Cette attitude peut aussi vous être utile.", "action": "écrivez deux phrases à une personne fictive qui vit votre situation : une pour reconnaître la difficulté, une pour proposer une prochaine étape. Relisez-les en remplaçant son nom par le vôtre. Gardez les mots qui sonnent naturels ; la douceur n’a pas besoin d’être solennelle.", "question": "Que dirais-je à un proche qui vit la même chose?", "sources": [{"id": "S22", "title": "Hagerman et coll., Appetite, 2023.", "url": "https://pubmed.ncbi.nlm.nih.gov/37619622/"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('e94d1118-a4aa-5c66-8d55-5f3885106921','a2bd1a05-e1a3-59b9-8f32-a3ae1fef827c',86,'review','{"title": "Développer une mentalité d’apprentissage", "objective": "vous soutenir avec des paroles exactes et praticables. L’autocompassion est prometteuse pour le vécu émotionnel des difficultés ; ce n’est pas une méthode de perte de poids démontrée à elle seule.", "body": "Une expérience qui ne vous aide pas apporte une information. Cela ne signifie pas que toutes les stratégies sont efficaces, ni qu’il faut persister indéfiniment. Apprendre inclut le droit d’abandonner un outil inadapté.", "action": "après une semaine, complétez trois phrases : « j’ai essayé… ; j’ai observé… ; je vais maintenant… ». Exemple : « la préparation du dimanche m’épuise ; je vais essayer deux petites préparations ». Évaluez l’outil, pas votre capacité à obéir à l’outil.", "question": "Que dirais-je à un proche qui vit la même chose?", "sources": [{"id": "S22", "title": "Hagerman et coll., Appetite, 2023.", "url": "https://pubmed.ncbi.nlm.nih.gov/37619622/"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('9182eb29-dbd7-5379-bc51-82e970f3e64f','a2bd1a05-e1a3-59b9-8f32-a3ae1fef827c',87,'review','{"title": "Construire sa confiance par des réussites accessibles", "objective": "vous soutenir avec des paroles exactes et praticables. L’autocompassion est prometteuse pour le vécu émotionnel des difficultés ; ce n’est pas une méthode de perte de poids démontrée à elle seule.", "body": "La confiance peut se nourrir de preuves concrètes. Une petite action choisie et répétée donne un point d’appui plus précis qu’un objectif lointain.", "action": "gardez une courte liste des situations que vous savez mieux gérer : repas de secours, marche adaptée, demande d’aide. Lorsqu’un nouveau défi apparaît, demandez-vous quelle compétence déjà acquise pourrait servir. Votre répertoire peut grandir même lorsque les résultats physiques sont lents.", "question": "Que dirais-je à un proche qui vit la même chose?", "sources": [{"id": "S22", "title": "Hagerman et coll., Appetite, 2023.", "url": "https://pubmed.ncbi.nlm.nih.gov/37619622/"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('0894b18d-f62f-515b-a575-701e352f74c9','a2bd1a05-e1a3-59b9-8f32-a3ae1fef827c',88,'review','{"title": "Accepter l’imperfection", "objective": "vous soutenir avec des paroles exactes et praticables. L’autocompassion est prometteuse pour le vécu émotionnel des difficultés ; ce n’est pas une méthode de perte de poids démontrée à elle seule.", "body": "Une habitude durable doit supporter des jours moyens. Prévoir une marge évite de traiter chaque imprévu comme une rupture. Cette marge est à définir selon votre réalité, sans imposer une règle universelle de type 80/20.", "action": "écrivez la version « assez bonne » de votre semaine. Elle pourrait inclure quelques repas assemblés, une sortie et une marche raccourcie. Demandez-vous si cette semaine protège l’essentiel sans vous demander une disponibilité que vous n’avez pas.", "question": "Que dirais-je à un proche qui vit la même chose?", "sources": [{"id": "S22", "title": "Hagerman et coll., Appetite, 2023.", "url": "https://pubmed.ncbi.nlm.nih.gov/37619622/"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('9013341c-8008-575c-8dca-778525e0ab6b','a2bd1a05-e1a3-59b9-8f32-a3ae1fef827c',89,'review','{"title": "Distinguer responsabilité et culpabilité", "objective": "vous soutenir avec des paroles exactes et praticables. L’autocompassion est prometteuse pour le vécu émotionnel des difficultés ; ce n’est pas une méthode de perte de poids démontrée à elle seule.", "body": "La responsabilité concerne les actions sur lesquelles vous avez une prise. La culpabilité peut devenir une condamnation globale. Vos choix comptent, mais ils s’inscrivent dans des contraintes qui ne dépendent pas toutes de vous.", "action": "séparez une difficulté en trois catégories : ce que je peux faire, l’aide que je peux demander et ce que je ne contrôle pas aujourd’hui. Choisissez une action dans les deux premières. Vous n’avez pas à vous attribuer le poids de la troisième.", "question": "Que dirais-je à un proche qui vit la même chose?", "sources": [{"id": "S22", "title": "Hagerman et coll., Appetite, 2023.", "url": "https://pubmed.ncbi.nlm.nih.gov/37619622/"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('cf28e8ef-d117-50a1-93a4-66e3eeaf57aa','a2bd1a05-e1a3-59b9-8f32-a3ae1fef827c',90,'review','{"title": "Reprendre au prochain choix", "objective": "vous soutenir avec des paroles exactes et praticables. L’autocompassion est prometteuse pour le vécu émotionnel des difficultés ; ce n’est pas une méthode de perte de poids démontrée à elle seule.", "body": "Attendre lundi peut transformer une interruption en longue pause. Reprendre ne demande pas un redémarrage spectaculaire. Il s’agit souvent d’une action familière et suffisamment simple.", "action": "après une journée difficile, choisissez votre prochain geste ordinaire : prendre un repas, sortir quelques minutes ou préparer le coucher. Évitez la séance punitive et le repas supprimé. Votre plan de reprise devrait être plus doux et plus clair que votre plan initial, pas plus exigeant.", "question": "Que dirais-je à un proche qui vit la même chose?", "sources": [{"id": "S22", "title": "Hagerman et coll., Appetite, 2023.", "url": "https://pubmed.ncbi.nlm.nih.gov/37619622/"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('84cf6744-fe81-52ef-a992-e940336c7896','bff21190-bb55-50e7-8bd1-377d679a3143',91,'review','{"title": "Reconnaître l’envie de modifier une émotion", "objective": "diversifier les réponses à vos besoins. Manger pour se réconforter arrive à beaucoup de personnes. Cela devient particulièrement préoccupant lorsque la perte de contrôle, la détresse ou les compensations se répètent. Ces situations méritent des soins spécifiques.", "body": "Vous pouvez chercher à prolonger une joie, diminuer une tension ou remplir un moment vide. Identifier cette fonction n’interdit pas de manger. Cela vous donne une occasion de voir si une autre aide serait également utile.", "action": "complétez « j’espère que manger va m’aider à… ». Si vous répondez « me calmer », vous pouvez choisir une collation et une pause. Les besoins physiques et émotionnels n’ont pas à entrer en compétition.", "question": "De quoi avais-je besoin à ce moment-là?", "sources": [{"id": "S25", "title": "NICE, NG69, 2017, version en ligne consultée.", "url": "https://www.nice.org.uk/guidance/ng69/chapter/recommendations"}, {"id": "S26", "title": "NHS.", "url": "https://www.nhs.uk/mental-health/feelings-symptoms-behaviours/behaviours/eating-disorders/overview/"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('16d8eea4-1ec0-55d9-9ba0-584d60d43829','bff21190-bb55-50e7-8bd1-377d679a3143',92,'review','{"title": "Nommer les émotions déclenchantes", "objective": "diversifier les réponses à vos besoins. Manger pour se réconforter arrive à beaucoup de personnes. Cela devient particulièrement préoccupant lorsque la perte de contrôle, la détresse ou les compensations se répètent. Ces situations méritent des soins spécifiques.", "body": "« Je me sens mal » peut recouvrir déception, colère, inquiétude ou solitude. Un mot plus précis peut orienter une réponse plus pertinente. Il n’est pas nécessaire de trouver une explication profonde à chaque envie.", "action": "utilisez une liste courte : triste, tendu, frustré, seul, content, fatigué. Choisissez le mot le plus proche et demandez-vous ce qui aiderait un peu. Si rien ne vient, décrivez simplement le moment. Ne transformez pas l’exercice en enquête contre vous-même.", "question": "De quoi avais-je besoin à ce moment-là?", "sources": [{"id": "S25", "title": "NICE, NG69, 2017, version en ligne consultée.", "url": "https://www.nice.org.uk/guidance/ng69/chapter/recommendations"}, {"id": "S26", "title": "NHS.", "url": "https://www.nhs.uk/mental-health/feelings-symptoms-behaviours/behaviours/eating-disorders/overview/"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('f5451ce9-9eec-5813-8f83-4bb1aadfd0f0','bff21190-bb55-50e7-8bd1-377d679a3143',93,'review','{"title": "Distinguer stress, ennui, solitude et fatigue", "objective": "diversifier les réponses à vos besoins. Manger pour se réconforter arrive à beaucoup de personnes. Cela devient particulièrement préoccupant lorsque la perte de contrôle, la détresse ou les compensations se répètent. Ces situations méritent des soins spécifiques.", "body": "Ces états peuvent produire des gestes semblables mais réclamer des réponses différentes. Une conversation peut aider la solitude ; une diminution des tâches peut aider la surcharge. Aucun aliment ne peut à lui seul régler toute une organisation de vie.", "action": "créez quatre options : appeler quelqu’un, changer d’activité, vous reposer, demander du soutien. Lors d’un moment difficile, choisissez celle qui correspond le mieux au besoin. Mangez aussi si vous avez faim ; l’expérience ne consiste pas à détourner toute prise alimentaire.", "question": "De quoi avais-je besoin à ce moment-là?", "sources": [{"id": "S25", "title": "NICE, NG69, 2017, version en ligne consultée.", "url": "https://www.nice.org.uk/guidance/ng69/chapter/recommendations"}, {"id": "S26", "title": "NHS.", "url": "https://www.nhs.uk/mental-health/feelings-symptoms-behaviours/behaviours/eating-disorders/overview/"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('dcf024ce-e8c5-5ca1-8186-f9de5fed8dcb','bff21190-bb55-50e7-8bd1-377d679a3143',94,'review','{"title": "Reconnaître la nourriture comme récompense", "objective": "diversifier les réponses à vos besoins. Manger pour se réconforter arrive à beaucoup de personnes. Cela devient particulièrement préoccupant lorsque la perte de contrôle, la détresse ou les compensations se répètent. Ces situations méritent des soins spécifiques.", "body": "Se dire « je l’ai bien mérité » peut être une façon de s’accorder une pause. Le problème apparaît si le plaisir alimentaire exige toujours une performance, ou s’il reste votre seul espace de détente.", "action": "gardez un plaisir alimentaire apprécié et ajoutez deux récompenses non alimentaires accessibles : un épisode, une douche agréable, un moment au soleil. Vous élargissez vos options sans retirer la nourriture de la liste des plaisirs légitimes.", "question": "De quoi avais-je besoin à ce moment-là?", "sources": [{"id": "S25", "title": "NICE, NG69, 2017, version en ligne consultée.", "url": "https://www.nice.org.uk/guidance/ng69/chapter/recommendations"}, {"id": "S26", "title": "NHS.", "url": "https://www.nhs.uk/mental-health/feelings-symptoms-behaviours/behaviours/eating-disorders/overview/"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('1218bdc4-b245-5d0e-a816-9e1f1d315c1a','bff21190-bb55-50e7-8bd1-377d679a3143',95,'review','{"title": "Comprendre le soulagement temporaire", "objective": "diversifier les réponses à vos besoins. Manger pour se réconforter arrive à beaucoup de personnes. Cela devient particulièrement préoccupant lorsque la perte de contrôle, la détresse ou les compensations se répètent. Ces situations méritent des soins spécifiques.", "body": "Manger peut réellement procurer un soulagement. Si le problème initial reste entier, l’envie peut revenir. Reconnaître cette limite évite de conclure que vous avez seulement besoin de mieux vous contrôler.", "action": "après un moment de réconfort, demandez-vous : « qu’est-ce qui s’est amélioré, et qu’est-ce qui demande encore une réponse ? » Une tension de travail peut nécessiter une discussion sur la charge ou une limite horaire. Le repas n’avait pas pour mission de résoudre tout le problème.", "question": "De quoi avais-je besoin à ce moment-là?", "sources": [{"id": "S25", "title": "NICE, NG69, 2017, version en ligne consultée.", "url": "https://www.nice.org.uk/guidance/ng69/chapter/recommendations"}, {"id": "S26", "title": "NHS.", "url": "https://www.nhs.uk/mental-health/feelings-symptoms-behaviours/behaviours/eating-disorders/overview/"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('bb3347ed-86c5-5f03-946f-7f1f31e0fe65','bff21190-bb55-50e7-8bd1-377d679a3143',96,'review','{"title": "Identifier le besoin derrière l’envie", "objective": "diversifier les réponses à vos besoins. Manger pour se réconforter arrive à beaucoup de personnes. Cela devient particulièrement préoccupant lorsque la perte de contrôle, la détresse ou les compensations se répètent. Ces situations méritent des soins spécifiques.", "body": "Un besoin peut être concret : manger, dormir, être écouté, se sentir en sécurité, interrompre une tâche. Certaines situations sont complexes et ne se règlent pas avec un exercice d’une minute.", "action": "demandez « de quoi aurais-je besoin si la nourriture n’était pas le sujet ? ». Écrivez une réponse modeste et une aide possible. Si le besoin concerne une situation persistante de détresse, prenez rendez-vous avec un professionnel plutôt que d’ajouter des règles alimentaires.", "question": "De quoi avais-je besoin à ce moment-là?", "sources": [{"id": "S25", "title": "NICE, NG69, 2017, version en ligne consultée.", "url": "https://www.nice.org.uk/guidance/ng69/chapter/recommendations"}, {"id": "S26", "title": "NHS.", "url": "https://www.nhs.uk/mental-health/feelings-symptoms-behaviours/behaviours/eating-disorders/overview/"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('74e35c02-5d9b-518a-8fe4-e330a5928764','bff21190-bb55-50e7-8bd1-377d679a3143',97,'review','{"title": "Construire plusieurs moyens de se réconforter", "objective": "diversifier les réponses à vos besoins. Manger pour se réconforter arrive à beaucoup de personnes. Cela devient particulièrement préoccupant lorsque la perte de contrôle, la détresse ou les compensations se répètent. Ces situations méritent des soins spécifiques.", "body": "Un répertoire de réconfort doit correspondre à votre énergie et à vos moyens. Une longue méditation n’est pas forcément réaliste après une journée épuisante. Certaines options doivent demander très peu d’effort.", "action": "préparez trois catégories : une minute, dix minutes, avec une autre personne. Exemple : vous asseoir confortablement ; écouter une chanson ou sortir ; envoyer un message. Testez les options avant une grande difficulté et gardez seulement celles qui vous aident réellement.", "question": "De quoi avais-je besoin à ce moment-là?", "sources": [{"id": "S25", "title": "NICE, NG69, 2017, version en ligne consultée.", "url": "https://www.nice.org.uk/guidance/ng69/chapter/recommendations"}, {"id": "S26", "title": "NHS.", "url": "https://www.nhs.uk/mental-health/feelings-symptoms-behaviours/behaviours/eating-disorders/overview/"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('0002302d-51d7-5174-a19b-489cfe04e8b6','bff21190-bb55-50e7-8bd1-377d679a3143',98,'review','{"title": "Introduire une pause avant d’agir", "objective": "diversifier les réponses à vos besoins. Manger pour se réconforter arrive à beaucoup de personnes. Cela devient particulièrement préoccupant lorsque la perte de contrôle, la détresse ou les compensations se répètent. Ces situations méritent des soins spécifiques.", "body": "Une pause peut créer un espace de décision. Elle ne doit pas servir à repousser une faim réelle, une hypoglycémie ou un repas nécessaire. Elle peut être très courte.", "action": "demandez-vous « de quoi ai-je besoin maintenant ? », puis choisissez. Vous pouvez décider de manger tout de suite. Si vous faites une autre action d’abord, gardez explicitement le droit de manger ensuite. La réussite de l’exercice est d’avoir choisi avec davantage de clarté.", "question": "De quoi avais-je besoin à ce moment-là?", "sources": [{"id": "S25", "title": "NICE, NG69, 2017, version en ligne consultée.", "url": "https://www.nice.org.uk/guidance/ng69/chapter/recommendations"}, {"id": "S26", "title": "NHS.", "url": "https://www.nhs.uk/mental-health/feelings-symptoms-behaviours/behaviours/eating-disorders/overview/"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('b67949fd-83ee-5620-9832-4254bdee6e0c','bff21190-bb55-50e7-8bd1-377d679a3143',99,'review','{"title": "Accueillir une émotion sans la supprimer immédiatement", "objective": "diversifier les réponses à vos besoins. Manger pour se réconforter arrive à beaucoup de personnes. Cela devient particulièrement préoccupant lorsque la perte de contrôle, la détresse ou les compensations se répètent. Ces situations méritent des soins spécifiques.", "body": "Une émotion inconfortable n’a pas toujours besoin de disparaître avant que vous poursuiviez votre journée. Cela ne signifie pas endurer seul une détresse importante. Les techniques d’attention doivent rester tolérables.", "action": "nommez l’émotion, sentez vos pieds au sol et regardez trois objets autour de vous. Puis choisissez une action de soutien. Si vous vous sentez plus anxieux ou déconnecté, arrêtez l’exercice et privilégiez un contact humain ou une activité familière.", "question": "De quoi avais-je besoin à ce moment-là?", "sources": [{"id": "S20", "title": "NCCIH, National Institutes of Health.", "url": "https://www.nccih.nih.gov/health/meditation-and-mindfulness-effectiveness-and-safety"}, {"id": "S25", "title": "NICE, NG69, 2017, version en ligne consultée.", "url": "https://www.nice.org.uk/guidance/ng69/chapter/recommendations"}, {"id": "S26", "title": "NHS.", "url": "https://www.nhs.uk/mental-health/feelings-symptoms-behaviours/behaviours/eating-disorders/overview/"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('fa148619-c829-5cb9-a064-d06ae6d9b37a','bff21190-bb55-50e7-8bd1-377d679a3143',100,'review','{"title": "Choisir consciemment de manger avec une émotion présente", "objective": "diversifier les réponses à vos besoins. Manger pour se réconforter arrive à beaucoup de personnes. Cela devient particulièrement préoccupant lorsque la perte de contrôle, la détresse ou les compensations se répètent. Ces situations méritent des soins spécifiques.", "body": "La nourriture peut rester un plaisir même quand vous êtes triste ou stressé. Vous n’avez pas besoin d’être parfaitement calme pour manger. Le choix peut associer nourriture et autre soutien.", "action": "servez un aliment apprécié, installez-vous et mangez sans vous imposer de compensation. Après, vérifiez si un autre besoin reste présent. Si les épisodes comportent régulièrement une impression de ne plus pouvoir s’arrêter, cherchez un accompagnement spécialisé plutôt que de durcir cet exercice.", "question": "De quoi avais-je besoin à ce moment-là?", "sources": [{"id": "S25", "title": "NICE, NG69, 2017, version en ligne consultée.", "url": "https://www.nice.org.uk/guidance/ng69/chapter/recommendations"}, {"id": "S26", "title": "NHS.", "url": "https://www.nhs.uk/mental-health/feelings-symptoms-behaviours/behaviours/eating-disorders/overview/"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('aacf5266-1b27-5da7-9fdb-20bfed613788','3bd39602-79f9-5809-8d45-0afd2ea46156',101,'review','{"title": "Identifier les situations déclenchantes", "objective": "augmenter votre marge de choix, sans faire de la résistance à la faim un objectif. Les stratégies ci-dessous sont des expériences personnelles ; aucune n’est une technique infaillible pour faire disparaître les envies.", "body": "Un aliment peut être difficile à gérer dans un contexte précis et beaucoup moins dans un autre. La faim, les interdictions antérieures, la fatigue et le conditionnement peuvent se combiner. L’aliment seul ne raconte pas toute l’histoire.", "action": "décrivez « aliment + lieu + moment + état ». Comparez ensuite deux contextes. Si les biscuits deviennent surtout difficiles après un dîner sauté, commencez par le dîner. Il n’est pas nécessaire de conclure que vous ne pourrez jamais garder de biscuits chez vous.", "question": "Quel petit espace de choix puis-je me donner?", "sources": [{"id": "S18", "title": "Santé Canada.", "url": "https://www.canada.ca/fr/sante-canada/services/guide-alimentaire/explorez/recommandations-matiere-alimentation-saine/prenez-conscience-habitudes-alimentaires.html"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('3fa5f7af-b98e-5ac0-917a-7047a372f42e','3bd39602-79f9-5809-8d45-0afd2ea46156',102,'review','{"title": "Comprendre l’influence des indices extérieurs", "objective": "augmenter votre marge de choix, sans faire de la résistance à la faim un objectif. Les stratégies ci-dessous sont des expériences personnelles ; aucune n’est une technique infaillible pour faire disparaître les envies.", "body": "Une odeur, une publicité ou un emballage visible peut susciter une envie. Remarquer cette influence permet de modifier votre environnement sans vous demander de lutter constamment.", "action": "changez un seul indice : retirez les notifications d’une application de livraison, placez les collations dans un espace choisi ou gardez une option pratique à portée de main. Observez l’effet. Dans une maison partagée, négociez l’organisation plutôt que d’imposer vos règles aux autres.", "question": "Quel petit espace de choix puis-je me donner?", "sources": [{"id": "S18", "title": "Santé Canada.", "url": "https://www.canada.ca/fr/sante-canada/services/guide-alimentaire/explorez/recommandations-matiere-alimentation-saine/prenez-conscience-habitudes-alimentaires.html"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('1d36740c-0c9c-53c1-902a-9eae425ed147','3bd39602-79f9-5809-8d45-0afd2ea46156',103,'review','{"title": "Observer une envie qui évolue", "objective": "augmenter votre marge de choix, sans faire de la résistance à la faim un objectif. Les stratégies ci-dessous sont des expériences personnelles ; aucune n’est une technique infaillible pour faire disparaître les envies.", "body": "Une envie peut augmenter, diminuer ou persister. Il n’existe pas une durée garantie après laquelle elle disparaît. Observer cette évolution peut être utile si vous n’êtes pas en situation de faim à satisfaire.", "action": "nommez l’envie et poursuivez brièvement une activité ordinaire, si cela vous convient. Revenez ensuite à votre décision. Si l’envie reste présente, manger demeure une option. Vous n’avez pas échoué parce que l’envie n’a pas diminué.", "question": "Quel petit espace de choix puis-je me donner?", "sources": [{"id": "S18", "title": "Santé Canada.", "url": "https://www.canada.ca/fr/sante-canada/services/guide-alimentaire/explorez/recommandations-matiere-alimentation-saine/prenez-conscience-habitudes-alimentaires.html"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('f2c111d2-270a-5ca7-9c4a-4c3135b0f304','3bd39602-79f9-5809-8d45-0afd2ea46156',104,'review','{"title": "Distinguer envie et action", "objective": "augmenter votre marge de choix, sans faire de la résistance à la faim un objectif. Les stratégies ci-dessous sont des expériences personnelles ; aucune n’est une technique infaillible pour faire disparaître les envies.", "body": "Ressentir une envie n’impose pas une action unique. Vous pouvez manger maintenant, prévoir l’aliment pour un autre moment ou choisir autre chose. La liberté de manger fait partie de cette marge de choix.", "action": "formulez trois réponses possibles à une situation précise. Par exemple : manger la pâtisserie au café, en partager une ou choisir une autre collation. Évitez de désigner à l’avance une réponse comme moralement supérieure. Cherchez celle qui correspond à votre envie et à votre confort.", "question": "Quel petit espace de choix puis-je me donner?", "sources": [{"id": "S18", "title": "Santé Canada.", "url": "https://www.canada.ca/fr/sante-canada/services/guide-alimentaire/explorez/recommandations-matiere-alimentation-saine/prenez-conscience-habitudes-alimentaires.html"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('4b03336e-895f-50af-a6ba-af8ff0fcbbef','3bd39602-79f9-5809-8d45-0afd2ea46156',105,'review','{"title": "Essayer un court délai, lorsque c’est pertinent", "objective": "augmenter votre marge de choix, sans faire de la résistance à la faim un objectif. Les stratégies ci-dessous sont des expériences personnelles ; aucune n’est une technique infaillible pour faire disparaître les envies.", "body": "Un délai peut aider à sortir d’un automatisme ; il ne doit pas devenir un test d’endurance. Ne l’utilisez pas pour ignorer un besoin de repas, des symptômes d’hypoglycémie ou des consignes médicales.", "action": "si vous n’avez pas faim et hésitez réellement, terminez une petite tâche puis redécidez. N’empilez pas les délais pour vous empêcher de manger. Si cette méthode augmente la préoccupation alimentaire, abandonnez-la au profit d’un choix direct et sans culpabilité.", "question": "Quel petit espace de choix puis-je me donner?", "sources": [{"id": "S18", "title": "Santé Canada.", "url": "https://www.canada.ca/fr/sante-canada/services/guide-alimentaire/explorez/recommandations-matiere-alimentation-saine/prenez-conscience-habitudes-alimentaires.html"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('9eba9ada-c960-5b35-952c-4096bb3e2341','3bd39602-79f9-5809-8d45-0afd2ea46156',106,'review','{"title": "Reconnaître l’effet des interdictions", "objective": "augmenter votre marge de choix, sans faire de la résistance à la faim un objectif. Les stratégies ci-dessous sont des expériences personnelles ; aucune n’est une technique infaillible pour faire disparaître les envies.", "body": "Le sentiment qu’un aliment sera bientôt interdit peut rendre son accès plus urgent : « autant en profiter maintenant ». Cela ne se produit pas chez tout le monde, mais mérite d’être observé.", "action": "remplacez « demain, plus jamais » par « je pourrai en reprendre une autre fois ». Voyez si l’urgence change. En présence de crises fréquentes, ne vous imposez pas seul un exercice d’exposition à un aliment difficile ; faites construire une approche adaptée avec un professionnel.", "question": "Quel petit espace de choix puis-je me donner?", "sources": [{"id": "S25", "title": "NICE, NG69, 2017, version en ligne consultée.", "url": "https://www.nice.org.uk/guidance/ng69/chapter/recommendations"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('8d2a89a2-7d62-5347-b1eb-ab80f21c91ef','3bd39602-79f9-5809-8d45-0afd2ea46156',107,'review','{"title": "Prévoir une portion appréciable", "objective": "augmenter votre marge de choix, sans faire de la résistance à la faim un objectif. Les stratégies ci-dessous sont des expériences personnelles ; aucune n’est une technique infaillible pour faire disparaître les envies.", "body": "Une portion prévue est un point de départ, pas un plafond intangible. Une quantité trop petite pour être satisfaisante peut simplement entretenir la recherche de nourriture.", "action": "mettez une quantité habituelle dans une assiette, rangez l’emballage et mangez. Vous pouvez reprendre si cela correspond à votre faim et à votre choix. Après plusieurs occasions, ajustez votre repère personnel. Le contenant rend la consommation visible ; il ne doit pas devenir un dispositif de punition.", "question": "Quel petit espace de choix puis-je me donner?", "sources": [{"id": "S18", "title": "Santé Canada.", "url": "https://www.canada.ca/fr/sante-canada/services/guide-alimentaire/explorez/recommandations-matiere-alimentation-saine/prenez-conscience-habitudes-alimentaires.html"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('0949f9c5-56c4-59ff-bb90-dcb8b61062c8','3bd39602-79f9-5809-8d45-0afd2ea46156',108,'review','{"title": "Préparer les soirées", "objective": "augmenter votre marge de choix, sans faire de la résistance à la faim un objectif. Les stratégies ci-dessous sont des expériences personnelles ; aucune n’est une technique infaillible pour faire disparaître les envies.", "body": "Manger le soir n’est pas automatiquement problématique. La question est de savoir si vous avez faim, si votre journée vous a nourri suffisamment et si la situation vous convient. Une heure limite universelle répond mal à des horaires variés.", "action": "choisissez une soirée à observer. Si la faim est présente, prévoyez une collation ; si vous cherchez une transition après le travail, ajoutez un rituel de détente. Les deux peuvent être nécessaires. Évaluez surtout le confort et la facilité à vous coucher.", "question": "Quel petit espace de choix puis-je me donner?", "sources": [{"id": "S18", "title": "Santé Canada.", "url": "https://www.canada.ca/fr/sante-canada/services/guide-alimentaire/explorez/recommandations-matiere-alimentation-saine/prenez-conscience-habitudes-alimentaires.html"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('98a6d4ed-bcdc-5a89-8870-7bc0a2dc2cd9','3bd39602-79f9-5809-8d45-0afd2ea46156',109,'review','{"title": "Découpler écran et grignotage automatique", "objective": "augmenter votre marge de choix, sans faire de la résistance à la faim un objectif. Les stratégies ci-dessous sont des expériences personnelles ; aucune n’est une technique infaillible pour faire disparaître les envies.", "body": "L’écran peut devenir le signal de commencer à manger. Il est possible de garder une collation devant une série tout en rendant le choix plus conscient.", "action": "avant de lancer l’épisode, décidez si vous voulez manger et servez votre collation. Si une envie apparaît plus tard, faites une pause pour choisir. Vous pouvez aussi prendre les premières bouchées sans écran. Le but est de retrouver une décision, pas de bannir un moment agréable.", "question": "Quel petit espace de choix puis-je me donner?", "sources": [{"id": "S18", "title": "Santé Canada.", "url": "https://www.canada.ca/fr/sante-canada/services/guide-alimentaire/explorez/recommandations-matiere-alimentation-saine/prenez-conscience-habitudes-alimentaires.html"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('ffa529a9-a73c-50b6-9c2e-98c8cf7161df','3bd39602-79f9-5809-8d45-0afd2ea46156',110,'review','{"title": "Préparer un plan « si… alors… »", "objective": "augmenter votre marge de choix, sans faire de la résistance à la faim un objectif. Les stratégies ci-dessous sont des expériences personnelles ; aucune n’est une technique infaillible pour faire disparaître les envies.", "body": "Un plan conditionnel relie une situation prévisible à une action disponible. Il est plus utile lorsqu’il est simple et ne dépend pas d’un état d’esprit idéal.", "action": "« Si ma réunion dépasse l’heure du dîner, alors je prendrai le repas de secours prévu. » Ajoutez une alternative : « s’il n’est pas disponible, je choisirai l’option du commerce voisin ». Testez le plan dans une vraie journée et corrigez l’obstacle rencontré.", "question": "Quel petit espace de choix puis-je me donner?", "sources": [{"id": "S06", "title": "NIDDK, révision 2020.", "url": "https://www.niddk.nih.gov/health-information/diet-nutrition/changing-habits-better-health"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('1a5400e5-bb13-53b3-90d2-ecc3adcf1530','6b8b7f8c-0304-50ee-a154-311ef18dac67',111,'review','{"title": "Planifier selon son horaire réel", "objective": "rendre les repas possibles avec vos ressources réelles. Une alimentation saine peut utiliser des produits surgelés, des conserves et des aliments préparés. Le budget, l’accès à une cuisine et la fatigue sont des paramètres de conception, pas des défauts personnels.", "body": "Un menu qui ignore les réunions, les déplacements ou les soirées occupées a peu de chances d’être utilisé. Commencez par le calendrier, puis choisissez les repas.", "action": "classez vos prochains soupers en trois catégories : cuisine possible, repas rapide, sortie ou imprévu. Planifiez seulement ce qui vous aide et laissez des espaces libres. Vous n’avez pas à cuisiner systématiquement en double : les restes peuvent être pratiques, mais leur répétition doit vous convenir.", "question": "Quel obstacle concret pourrais-je enlever cette semaine?", "sources": [{"id": "S23", "title": "Santé Canada.", "url": "https://www.canada.ca/en/health-canada/services/food-guide/eating-support/meal-planning-grocery-shopping/healthy-eating-budget.html"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('5486b497-7c4c-5e7e-8972-faa665ad53a2','6b8b7f8c-0304-50ee-a154-311ef18dac67',112,'review','{"title": "Faire une liste d’épicerie utile", "objective": "rendre les repas possibles avec vos ressources réelles. Une alimentation saine peut utiliser des produits surgelés, des conserves et des aliments préparés. Le budget, l’accès à une cuisine et la fatigue sont des paramètres de conception, pas des défauts personnels.", "body": "Une liste gagne à partir de ce qui est déjà disponible. Elle peut réduire les oublis et les achats qui ne s’intègrent à aucun repas. Le plus petit prix d’achat n’est pas toujours le plus économique si l’aliment est gaspillé.", "action": "vérifiez réfrigérateur, congélateur et garde-manger. Choisissez deux ou trois repas partageant certains ingrédients. Ajoutez un aliment plaisir et une option de secours. Comparez les prix à l’unité lorsque c’est possible, en tenant compte de la quantité que vous utiliserez vraiment.", "question": "Quel obstacle concret pourrais-je enlever cette semaine?", "sources": [{"id": "S23", "title": "Santé Canada.", "url": "https://www.canada.ca/en/health-canada/services/food-guide/eating-support/meal-planning-grocery-shopping/healthy-eating-budget.html"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('9057f8df-1b23-5120-94a4-48efcf689341','6b8b7f8c-0304-50ee-a154-311ef18dac67',113,'review','{"title": "Prévoir des repas pour les journées difficiles", "objective": "rendre les repas possibles avec vos ressources réelles. Une alimentation saine peut utiliser des produits surgelés, des conserves et des aliments préparés. Le budget, l’accès à une cuisine et la fatigue sont des paramètres de conception, pas des défauts personnels.", "body": "Le repas de secours doit être plus facile que la décision de ne rien préparer. Il peut être acheté, surgelé ou assemblé. Sa fonction est de vous nourrir sans exiger une grande énergie.", "action": "choisissez trois options concrètes : omelette et pain ; légumineuses, riz précuit et légumes ; sandwich et fruit. Adaptez aux allergies et à vos goûts. Gardez une option sans cuisson si votre accès à la cuisine est limité.", "question": "Quel obstacle concret pourrais-je enlever cette semaine?", "sources": [{"id": "S23", "title": "Santé Canada.", "url": "https://www.canada.ca/en/health-canada/services/food-guide/eating-support/meal-planning-grocery-shopping/healthy-eating-budget.html"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('3fee316d-b7db-50c8-aba0-874dbc59b06b','6b8b7f8c-0304-50ee-a154-311ef18dac67',114,'review','{"title": "Garder des options accessibles", "objective": "rendre les repas possibles avec vos ressources réelles. Une alimentation saine peut utiliser des produits surgelés, des conserves et des aliments préparés. Le budget, l’accès à une cuisine et la fatigue sont des paramètres de conception, pas des défauts personnels.", "body": "Un aliment utile mais enfoui derrière plusieurs contenants sera moins facile à utiliser. L’accessibilité concerne aussi la capacité d’ouvrir, couper, mâcher ou préparer.", "action": "choisissez une amélioration : fruit visible, yogourt facile à prendre, légumes surgelés prêts à cuire ou conserve à ouverture pratique. Si vous avez peu d’énergie ou une limitation physique, une version précoupée peut valoir son coût. L’objectif est un repas réalisable, pas une démonstration d’autonomie totale.", "question": "Quel obstacle concret pourrais-je enlever cette semaine?", "sources": [{"id": "S23", "title": "Santé Canada.", "url": "https://www.canada.ca/en/health-canada/services/food-guide/eating-support/meal-planning-grocery-shopping/healthy-eating-budget.html"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('f7a9f28a-dfff-5dca-bdf2-31aeef34c837','6b8b7f8c-0304-50ee-a154-311ef18dac67',115,'review','{"title": "Ajuster la visibilité des aliments", "objective": "rendre les repas possibles avec vos ressources réelles. Une alimentation saine peut utiliser des produits surgelés, des conserves et des aliments préparés. Le budget, l’accès à une cuisine et la fatigue sont des paramètres de conception, pas des défauts personnels.", "body": "Vous pouvez organiser l’espace pour diminuer les sollicitations répétées. Cela ne nécessite pas d’éliminer tous les aliments plaisir ni de verrouiller leur accès.", "action": "placez les collations dans un emplacement choisi, plutôt qu’au milieu de votre espace de travail. Mettez à portée de main ce qui facilite vos repas habituels. Dans un logement partagé, convenez ensemble des espaces. Votre démarche n’exige pas que vos proches suivent le même programme.", "question": "Quel obstacle concret pourrais-je enlever cette semaine?", "sources": [{"id": "S23", "title": "Santé Canada.", "url": "https://www.canada.ca/en/health-canada/services/food-guide/eating-support/meal-planning-grocery-shopping/healthy-eating-budget.html"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('2eaff75a-9050-5ccf-9116-b6d9c7953e85','6b8b7f8c-0304-50ee-a154-311ef18dac67',116,'review','{"title": "Servir plutôt que manger dans l’emballage", "objective": "rendre les repas possibles avec vos ressources réelles. Une alimentation saine peut utiliser des produits surgelés, des conserves et des aliments préparés. Le budget, l’accès à une cuisine et la fatigue sont des paramètres de conception, pas des défauts personnels.", "body": "Un bol ou une assiette rend la quantité plus visible et peut rendre le moment plus agréable. Cela ne garantit pas que vous mangerez moins, et ce n’est pas son seul intérêt.", "action": "versez une collation dans un contenant puis rangez l’emballage. Mangez, puis décidez si vous en voulez davantage. Si ce geste vous convient, gardez-le. Si vous êtes en déplacement, une autre façon de rendre le choix clair peut suffire.", "question": "Quel obstacle concret pourrais-je enlever cette semaine?", "sources": [{"id": "S23", "title": "Santé Canada.", "url": "https://www.canada.ca/en/health-canada/services/food-guide/eating-support/meal-planning-grocery-shopping/healthy-eating-budget.html"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('2fe99cff-b998-5991-8f7f-d55fa519b878','6b8b7f8c-0304-50ee-a154-311ef18dac67',117,'review','{"title": "Lire les étiquettes simplement", "objective": "rendre les repas possibles avec vos ressources réelles. Une alimentation saine peut utiliser des produits surgelés, des conserves et des aliments préparés. Le budget, l’accès à une cuisine et la fatigue sont des paramètres de conception, pas des défauts personnels.", "body": "Commencez par la portion de référence, puis comparez des quantités semblables. Au Canada, 5 % de la valeur quotidienne ou moins correspond à « peu » et 15 % ou plus à « beaucoup ». Ce repère dépend du nutriment recherché ou à limiter.", "action": "comparez deux pains pour les fibres ou deux soupes pour le sodium. Vérifiez aussi le goût, le prix et les allergies. Évitez de juger un produit uniquement à son emballage « naturel » ou « protéiné ».", "question": "Quel obstacle concret pourrais-je enlever cette semaine?", "sources": [{"id": "S15", "title": "Santé Canada.", "url": "https://www.canada.ca/en/health-canada/services/food-guide/explore/healthy-eating-recommendations/use-food-labels.html"}, {"id": "S23", "title": "Santé Canada.", "url": "https://www.canada.ca/en/health-canada/services/food-guide/eating-support/meal-planning-grocery-shopping/healthy-eating-budget.html"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('4131662d-2e44-5ce1-8f5c-0c5f27ea628c','6b8b7f8c-0304-50ee-a154-311ef18dac67',118,'review','{"title": "Adapter les recettes familiales", "objective": "rendre les repas possibles avec vos ressources réelles. Une alimentation saine peut utiliser des produits surgelés, des conserves et des aliments préparés. Le budget, l’accès à une cuisine et la fatigue sont des paramètres de conception, pas des défauts personnels.", "body": "Une recette porte parfois des souvenirs et une identité culturelle. Une adaptation respectueuse conserve ce qui compte et modifie seulement ce qui est acceptable pour vous.", "action": "demandez aux personnes qui mangent avec vous quel élément doit rester : sauce, texture, épices, fromage. Changez ensuite une seule variable, comme la proportion de légumes ou l’accompagnement. Notez la version qui plaît. Une recette légèrement adaptée et régulièrement cuisinée est plus utile qu’une version idéale délaissée.", "question": "Quel obstacle concret pourrais-je enlever cette semaine?", "sources": [{"id": "S23", "title": "Santé Canada.", "url": "https://www.canada.ca/en/health-canada/services/food-guide/eating-support/meal-planning-grocery-shopping/healthy-eating-budget.html"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('5e77df8e-9b05-5012-b263-0ff2a4c5d876','6b8b7f8c-0304-50ee-a154-311ef18dac67',119,'review','{"title": "Préparer des composantes à l’avance", "objective": "rendre les repas possibles avec vos ressources réelles. Une alimentation saine peut utiliser des produits surgelés, des conserves et des aliments préparés. Le budget, l’accès à une cuisine et la fatigue sont des paramètres de conception, pas des défauts personnels.", "body": "La préparation peut concerner une sauce, un ingrédient lavé ou un repas au congélateur. Vous n’avez pas à consacrer une journée entière à cuisiner. La sécurité alimentaire et la conservation restent essentielles.", "action": "préparez une composante qui servira à deux repas différents, comme des légumes ou une base de légumineuses. Étiquetez et conservez selon les recommandations de sécurité alimentaire et les emballages. Choisissez des quantités réalistes ; un réfrigérateur rempli de préparations délaissées ne simplifie pas la semaine.", "question": "Quel obstacle concret pourrais-je enlever cette semaine?", "sources": [{"id": "S23", "title": "Santé Canada.", "url": "https://www.canada.ca/en/health-canada/services/food-guide/eating-support/meal-planning-grocery-shopping/healthy-eating-budget.html"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('93628702-b76d-57da-aad1-a8e3ffee9452','6b8b7f8c-0304-50ee-a154-311ef18dac67',120,'review','{"title": "Réduire les décisions en urgence", "objective": "rendre les repas possibles avec vos ressources réelles. Une alimentation saine peut utiliser des produits surgelés, des conserves et des aliments préparés. Le budget, l’accès à une cuisine et la fatigue sont des paramètres de conception, pas des défauts personnels.", "body": "Lorsque faim et fatigue s’accumulent, une courte liste d’options peut aider davantage qu’une longue collection de recettes. Vous pouvez créer quelques décisions par défaut tout en gardant de la variété.", "action": "écrivez « mes trois repas rapides », « mes deux commandes habituelles » et « ma collation transportable ». Gardez cette liste facilement accessible. Actualisez-la si vos goûts changent. Elle doit vous éviter de recommencer votre réflexion à zéro, sans vous enfermer dans un menu fixe.", "question": "Quel obstacle concret pourrais-je enlever cette semaine?", "sources": [{"id": "S23", "title": "Santé Canada.", "url": "https://www.canada.ca/en/health-canada/services/food-guide/eating-support/meal-planning-grocery-shopping/healthy-eating-budget.html"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('8fc96d43-ebde-522b-9731-bbb19390714d','9513b194-feb2-589a-97f8-49167a5ce868',121,'review','{"title": "Préparer une sortie au restaurant", "objective": "participer aux repas partagés sans abandonner vos besoins. Le soutien social fait partie des moyens de maintien ; il doit être choisi, respectueux et concret.", "body": "Une préparation légère peut éviter de décider dans l’urgence. Cela ne veut pas dire analyser chaque ingrédient ni arriver affamé pour « garder ses calories ».", "action": "regardez le menu si cela vous rassure, puis choisissez ce qui vous attire. Si le repas sera très tardif, prévoyez de vous nourrir normalement avant, avec une collation au besoin. Votre intention peut être simple : profiter du plat et remarquer votre confort, sans viser une commande parfaite.", "question": "Comment préserver ce qui compte pour moi dans ce moment partagé?", "sources": [{"id": "S32", "title": "CDC, 2023.", "url": "https://www.cdc.gov/healthy-weight-growth/losing-weight/keeping-it-off.html"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('b60ed828-9f53-5266-9abb-7a7c2128977d','9513b194-feb2-589a-97f8-49167a5ce868',122,'review','{"title": "Choisir ce qu’on veut réellement savourer", "objective": "participer aux repas partagés sans abandonner vos besoins. Le soutien social fait partie des moyens de maintien ; il doit être choisi, respectueux et concret.", "body": "Un menu offre souvent plusieurs plaisirs possibles. Vous n’avez pas à tout prendre pour profiter de la sortie, ni à choisir systématiquement l’option présentée comme légère.", "action": "demandez-vous ce qui vous ferait le plus plaisir aujourd’hui. Peut-être le plat principal, une entrée à partager ou un dessert. Composez le repas autour de ce choix, puis ajustez selon votre faim. Le plaisir anticipé et le plaisir réel peuvent différer : prenez cette information pour la prochaine fois.", "question": "Comment préserver ce qui compte pour moi dans ce moment partagé?", "sources": [{"id": "S32", "title": "CDC, 2023.", "url": "https://www.cdc.gov/healthy-weight-growth/losing-weight/keeping-it-off.html"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('f7ae77f3-0b10-5495-98b0-4b779452bd42','9513b194-feb2-589a-97f8-49167a5ce868',123,'review','{"title": "Adapter une portion de restaurant", "objective": "participer aux repas partagés sans abandonner vos besoins. Le soutien social fait partie des moyens de maintien ; il doit être choisi, respectueux et concret.", "body": "Une portion servie peut dépasser votre appétit ou, au contraire, être insuffisante. La quantité dans l’assiette n’est pas une consigne personnelle.", "action": "mangez puis réévaluez, sans obligation de terminer. Vous pouvez demander un contenant lorsque la conservation est possible, partager ou compléter le repas. Si vous emportez des restes, prévoyez un retour et une réfrigération compatibles avec leur sécurité. Le choix dépend aussi du trajet et du contexte.", "question": "Comment préserver ce qui compte pour moi dans ce moment partagé?", "sources": [{"id": "S10", "title": "NIDDK, révision 2021.", "url": "https://www.niddk.nih.gov/health-information/weight-management/just-enough-food-portions"}, {"id": "S32", "title": "CDC, 2023.", "url": "https://www.cdc.gov/healthy-weight-growth/losing-weight/keeping-it-off.html"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('876255ba-adfc-5b71-abe2-5f1ff60b8980','9513b194-feb2-589a-97f8-49167a5ce868',124,'review','{"title": "Traverser un buffet avec une intention claire", "objective": "participer aux repas partagés sans abandonner vos besoins. Le soutien social fait partie des moyens de maintien ; il doit être choisi, respectueux et concret.", "body": "Le buffet multiplie les possibilités et peut créer le sentiment de devoir « rentabiliser ». Un bref tour d’observation peut aider à choisir ce qui vous intéresse vraiment.", "action": "regardez les options avant de vous servir, puis composez une première assiette avec vos choix préférés. Vous pourrez revenir. Faites une pause pour vérifier votre faim et votre confort, sans règle de nombre d’assiettes. Le prix payé n’oblige pas votre corps à dépasser son confort.", "question": "Comment préserver ce qui compte pour moi dans ce moment partagé?", "sources": [{"id": "S32", "title": "CDC, 2023.", "url": "https://www.cdc.gov/healthy-weight-growth/losing-weight/keeping-it-off.html"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('14de20be-9af7-5dbf-802f-8de22f21a594','9513b194-feb2-589a-97f8-49167a5ce868',125,'review','{"title": "Faire une place aux fêtes", "objective": "participer aux repas partagés sans abandonner vos besoins. Le soutien social fait partie des moyens de maintien ; il doit être choisi, respectueux et concret.", "body": "Une fête fait partie de la vie. Sa fréquence et son contexte comptent davantage qu’une tentative de contrôler parfaitement chaque bouchée. Les habitudes ordinaires peuvent reprendre sans réparation.", "action": "choisissez une intention de présence : parler à quelqu’un, savourer un plat de famille, manger assis lorsque possible. Le lendemain, revenez à une alimentation régulière. Si plusieurs occasions se succèdent, adaptez votre organisation entre elles, sans jeûnes compensatoires ni programme punitif.", "question": "Comment préserver ce qui compte pour moi dans ce moment partagé?", "sources": [{"id": "S32", "title": "CDC, 2023.", "url": "https://www.cdc.gov/healthy-weight-growth/losing-weight/keeping-it-off.html"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('c3374fcc-69ae-5d5d-af8a-dc077e1292f0','9513b194-feb2-589a-97f8-49167a5ce868',126,'review','{"title": "Comprendre la place de l’alcool", "objective": "participer aux repas partagés sans abandonner vos besoins. Le soutien social fait partie des moyens de maintien ; il doit être choisi, respectueux et concret.", "body": "L’alcool concerne la santé au-delà de ses calories. Les repères canadiens de 2023 indiquent que moins on boit, moins le risque est élevé ; une ou deux consommations standards par semaine correspondent à un risque plus faible, pas nul. Ne pas boire évite les risques liés à la consommation.", "action": "prévoyez une boisson sans alcool que vous appréciez. Ne sautez pas un repas pour « compenser ». Si vous buvez beaucoup quotidiennement, discutez d’une réduction sécuritaire avec un professionnel plutôt que d’arrêter brutalement seul.", "question": "Comment préserver ce qui compte pour moi dans ce moment partagé?", "sources": [{"id": "S24", "title": "Centre canadien sur les dépendances et l’usage de substances, 2023.", "url": "https://www.ccsa.ca/en/guidance-tools-resources/substances/alcohol/canadas-guidance-alcohol-and-health"}, {"id": "S32", "title": "CDC, 2023.", "url": "https://www.cdc.gov/healthy-weight-growth/losing-weight/keeping-it-off.html"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('70752712-396e-5f39-9841-99504e3591fa','9513b194-feb2-589a-97f8-49167a5ce868',127,'review','{"title": "Répondre aux personnes qui insistent", "objective": "participer aux repas partagés sans abandonner vos besoins. Le soutien social fait partie des moyens de maintien ; il doit être choisi, respectueux et concret.", "body": "Refuser une portion n’est pas refuser une personne. Vous pouvez rester chaleureux et clair. Il n’est pas nécessaire de justifier votre démarche ou de parler de votre poids.", "action": "préparez une phrase : « C’était très bon, j’en ai assez pour l’instant » ou « je vais décider un peu plus tard ». Répétez-la si nécessaire. Si les commentaires persistent, déplacez la discussion : « j’aimerais qu’on parle d’autre chose que de mon assiette ».", "question": "Comment préserver ce qui compte pour moi dans ce moment partagé?", "sources": [{"id": "S32", "title": "CDC, 2023.", "url": "https://www.cdc.gov/healthy-weight-growth/losing-weight/keeping-it-off.html"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('63082ee5-b743-55b0-864b-80226309bcd7','9513b194-feb2-589a-97f8-49167a5ce868',128,'review','{"title": "Exprimer ses besoins aux proches", "objective": "participer aux repas partagés sans abandonner vos besoins. Le soutien social fait partie des moyens de maintien ; il doit être choisi, respectueux et concret.", "body": "Les proches peuvent vouloir aider sans savoir comment. Les demandes générales, comme « soutiens-moi », laissent beaucoup de place aux interprétations, parfois aux commentaires non souhaités.", "action": "dites ce qui serait utile : « préparer un repas ensemble », « marcher avec moi », « éviter les remarques sur mon poids ». Précisez aussi ce qui ne vous aide pas. Votre conjoint ou votre famille n’a pas à devenir votre surveillant alimentaire.", "question": "Comment préserver ce qui compte pour moi dans ce moment partagé?", "sources": [{"id": "S32", "title": "CDC, 2023.", "url": "https://www.cdc.gov/healthy-weight-growth/losing-weight/keeping-it-off.html"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('bc1e195c-17b8-53dd-9a79-8a77d0cbed0b','9513b194-feb2-589a-97f8-49167a5ce868',129,'review','{"title": "Demander un soutien concret", "objective": "participer aux repas partagés sans abandonner vos besoins. Le soutien social fait partie des moyens de maintien ; il doit être choisi, respectueux et concret.", "body": "Le soutien peut être émotionnel, pratique ou professionnel. Une personne peut être excellente pour vous écouter mais peu disponible pour cuisiner ; une autre peut aider avec les courses.", "action": "identifiez un besoin et la personne ou le service approprié. Demandez une action limitée : « pourrais-tu choisir un repas cette semaine ? ». Si vous manquez de soutien proche, envisagez un groupe respectueux, une diététiste ou un service communautaire. La qualité du soutien compte plus que le nombre de personnes impliquées.", "question": "Comment préserver ce qui compte pour moi dans ce moment partagé?", "sources": [{"id": "S32", "title": "CDC, 2023.", "url": "https://www.cdc.gov/healthy-weight-growth/losing-weight/keeping-it-off.html"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('070cf6a8-c131-52de-9fdc-e59bed43908b','9513b194-feb2-589a-97f8-49167a5ce868',130,'review','{"title": "Éviter les comparaisons de parcours", "objective": "participer aux repas partagés sans abandonner vos besoins. Le soutien social fait partie des moyens de maintien ; il doit être choisi, respectueux et concret.", "body": "Deux personnes ne partagent pas la même biologie, les mêmes traitements ou les mêmes contraintes. Comparer uniquement les kilos perdus peut invisibiliser ces différences et pousser à des changements inadaptés.", "action": "choisissez une comparaison avec votre propre quotidien : « est-ce plus facile de préparer mon dîner qu’il y a un mois ? ». Ajustez vos abonnements si certains contenus alimentent la honte. Vous pouvez apprécier la réussite d’un proche sans faire de sa trajectoire votre norme.", "question": "Comment préserver ce qui compte pour moi dans ce moment partagé?", "sources": [{"id": "S32", "title": "CDC, 2023.", "url": "https://www.cdc.gov/healthy-weight-growth/losing-weight/keeping-it-off.html"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('0d96dd55-7a88-5d61-ad51-f3afe3d7600d','9a61d466-f75f-5fe2-8ce1-1285dd53ec95',131,'review','{"title": "Trouver une activité appréciée", "objective": "renforcer votre capacité à vivre vos journées. Les repères de santé publique sont des directions à adapter, pas des exigences de départ. Toute progression doit tenir compte de votre mobilité, de votre douleur et de votre santé.", "body": "Marcher, danser, jardiner, faire du vélo, nager ou bouger assis peuvent contribuer à une vie active. Le meilleur point de départ dépend de ce qui est accessible et suffisamment agréable pour être répété.", "action": "choisissez deux activités et testez-en une brièvement. Évaluez plaisir, confort et difficulté d’organisation. Si la douleur limite vos options, cherchez une adaptation avec un professionnel du mouvement plutôt que d’attendre d’avoir maigri pour bouger.", "question": "Quel geste de récupération serait réaliste aujourd’hui?", "sources": [{"id": "S27", "title": "Organisation mondiale de la Santé, 2020.", "url": "https://www.ncbi.nlm.nih.gov/books/NBK566046/"}, {"id": "S28", "title": "Société canadienne de physiologie de l’exercice, 2020.", "url": "https://csepguidelines.ca/guidelines/adults-18-64/"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('58f1d0ef-167e-5b49-beac-6ba774a9787c','9a61d466-f75f-5fe2-8ce1-1285dd53ec95',132,'review','{"title": "Se fixer une progression réaliste", "objective": "renforcer votre capacité à vivre vos journées. Les repères de santé publique sont des directions à adapter, pas des exigences de départ. Toute progression doit tenir compte de votre mobilité, de votre douleur et de votre santé.", "body": "L’OMS recommande aux adultes de viser 150 à 300 minutes d’activité aérobique modérée par semaine, ou un équivalent vigoureux, et du renforcement au moins deux jours. Ce repère n’oblige pas à commencer à ce niveau. À intensité modérée, parler reste généralement possible, chanter devient plus difficile.", "action": "partez de votre niveau actuel, même quelques minutes. Augmentez un élément à la fois : durée, fréquence ou difficulté. Revenez à une dose tolérable si récupération ou douleur se dégradent.", "question": "Quel geste de récupération serait réaliste aujourd’hui?", "sources": [{"id": "S27", "title": "Organisation mondiale de la Santé, 2020.", "url": "https://www.ncbi.nlm.nih.gov/books/NBK566046/"}, {"id": "S28", "title": "Société canadienne de physiologie de l’exercice, 2020.", "url": "https://csepguidelines.ca/guidelines/adults-18-64/"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('d29f83fc-697c-5f82-8a89-443795bd59ee','9a61d466-f75f-5fe2-8ce1-1285dd53ec95',133,'review','{"title": "Augmenter le mouvement quotidien", "objective": "renforcer votre capacité à vivre vos journées. Les repères de santé publique sont des directions à adapter, pas des exigences de départ. Toute progression doit tenir compte de votre mobilité, de votre douleur et de votre santé.", "body": "Les déplacements et les tâches ordinaires comptent aussi. Ils peuvent être plus faciles à intégrer qu’une séance formelle, sans devoir remplacer toutes les activités structurées.", "action": "choisissez une occasion existante : une petite promenade après un repas, un déplacement actif ou quelques mouvements pendant une pause. Si vous utilisez un compteur, observez d’abord votre niveau personnel. Il n’y a pas besoin de faire de 10 000 pas une condition universelle de réussite.", "question": "Quel geste de récupération serait réaliste aujourd’hui?", "sources": [{"id": "S27", "title": "Organisation mondiale de la Santé, 2020.", "url": "https://www.ncbi.nlm.nih.gov/books/NBK566046/"}, {"id": "S28", "title": "Société canadienne de physiologie de l’exercice, 2020.", "url": "https://csepguidelines.ca/guidelines/adults-18-64/"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('186d04af-7303-5041-9e44-ae87cc3c97d7','9a61d466-f75f-5fe2-8ce1-1285dd53ec95',134,'review','{"title": "Interrompre les longues périodes assises", "objective": "renforcer votre capacité à vivre vos journées. Les repères de santé publique sont des directions à adapter, pas des exigences de départ. Toute progression doit tenir compte de votre mobilité, de votre douleur et de votre santé.", "body": "Faire du sport et réduire les longues périodes immobiles sont deux objectifs complémentaires. Vous pouvez varier les positions et bouger un peu même si votre travail impose beaucoup de temps assis.", "action": "associez une courte pause à une transition naturelle : fin d’appel, passage aux toilettes, remplissage d’un verre. Si vous ne pouvez pas vous lever, explorez des mouvements adaptés. Un rappel toutes les heures est une option d’organisation, pas une fréquence médicale obligatoire pour tous.", "question": "Quel geste de récupération serait réaliste aujourd’hui?", "sources": [{"id": "S28", "title": "Société canadienne de physiologie de l’exercice, 2020.", "url": "https://csepguidelines.ca/guidelines/adults-18-64/"}, {"id": "S27", "title": "Organisation mondiale de la Santé, 2020.", "url": "https://www.ncbi.nlm.nih.gov/books/NBK566046/"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('b1d042eb-b5a4-575e-a963-47362adc83db','9a61d466-f75f-5fe2-8ce1-1285dd53ec95',135,'review','{"title": "Valoriser les bénéfices au-delà du poids et développer la force", "objective": "renforcer votre capacité à vivre vos journées. Les repères de santé publique sont des directions à adapter, pas des exigences de départ. Toute progression doit tenir compte de votre mobilité, de votre douleur et de votre santé.", "body": "Le mouvement peut soutenir la capacité fonctionnelle même sans baisse de poids. Le renforcement mérite une place particulière pour préserver ou développer la force ; sous traitement amaigrissant, les protéines seules ne remplacent pas ce travail.", "action": "choisissez un mouvement adapté avec une personne qualifiée : se relever d’une chaise stable, pousser contre un mur ou utiliser un élastique. Commencez selon vos capacités. Mesurez un progrès utile, comme porter un sac plus confortablement, plutôt que les calories « brûlées ».", "question": "Quel geste de récupération serait réaliste aujourd’hui?", "sources": [{"id": "S27", "title": "Organisation mondiale de la Santé, 2020.", "url": "https://www.ncbi.nlm.nih.gov/books/NBK566046/"}, {"id": "S29", "title": "American College of Lifestyle Medicine, American Society for Nutrition, Obesity Medicine Association et The Obesity Society, 2025.", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC12125019/"}, {"id": "S28", "title": "Société canadienne de physiologie de l’exercice, 2020.", "url": "https://csepguidelines.ca/guidelines/adults-18-64/"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('352793b8-168c-58f6-9afb-f93e33b49058','9a61d466-f75f-5fe2-8ce1-1285dd53ec95',136,'review','{"title": "Comprendre les liens entre sommeil, énergie et appétit", "objective": "renforcer votre capacité à vivre vos journées. Les repères de santé publique sont des directions à adapter, pas des exigences de départ. Toute progression doit tenir compte de votre mobilité, de votre douleur et de votre santé.", "body": "Le manque de sommeil peut compliquer l’énergie et les choix alimentaires. Un petit essai randomisé chez des adultes dormant peu a observé une baisse de l’apport énergétique après prolongation du sommeil, mais sur une courte durée : cela ne garantit pas un amaigrissement à long terme.", "action": "observez pendant quelques jours votre repos et vos moments de faim ou de fatigue. Cherchez une possibilité de récupération plutôt que d’interpréter toute difficulté comme un manque de motivation.", "question": "Quel geste de récupération serait réaliste aujourd’hui?", "sources": [{"id": "S30", "title": "Tasali et coll., JAMA Internal Medicine, 2022.", "url": "https://pubmed.ncbi.nlm.nih.gov/35129580/"}, {"id": "S27", "title": "Organisation mondiale de la Santé, 2020.", "url": "https://www.ncbi.nlm.nih.gov/books/NBK566046/"}, {"id": "S28", "title": "Société canadienne de physiologie de l’exercice, 2020.", "url": "https://csepguidelines.ca/guidelines/adults-18-64/"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('e771d3d9-9a40-5039-8530-10294ceb009a','9a61d466-f75f-5fe2-8ce1-1285dd53ec95',137,'review','{"title": "Installer une routine de sommeil réaliste", "objective": "renforcer votre capacité à vivre vos journées. Les repères de santé publique sont des directions à adapter, pas des exigences de départ. Toute progression doit tenir compte de votre mobilité, de votre douleur et de votre santé.", "body": "Les recommandations canadiennes proposent généralement 7 à 9 heures de sommeil aux adultes de 18 à 64 ans, et 7 à 8 heures après 65 ans. Les horaires et les besoins individuels demandent des adaptations.", "action": "protégez un petit moment de transition avant le coucher. En cas de ronflements importants, pauses respiratoires observées ou somnolence marquée le jour, consultez pour rechercher notamment une apnée du sommeil. Une routine seule ne traite pas ce trouble.", "question": "Quel geste de récupération serait réaliste aujourd’hui?", "sources": [{"id": "S28", "title": "Société canadienne de physiologie de l’exercice, 2020.", "url": "https://csepguidelines.ca/guidelines/adults-18-64/"}, {"id": "S31", "title": "NHLBI, National Institutes of Health, 2025.", "url": "https://www.nhlbi.nih.gov/health/sleep-apnea/symptoms"}, {"id": "S27", "title": "Organisation mondiale de la Santé, 2020.", "url": "https://www.ncbi.nlm.nih.gov/books/NBK566046/"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('7c5d7d3a-ccb1-55f1-99aa-bf7123500ed4','9a61d466-f75f-5fe2-8ce1-1285dd53ec95',138,'review','{"title": "Reconnaître ses signes de surcharge", "objective": "renforcer votre capacité à vivre vos journées. Les repères de santé publique sont des directions à adapter, pas des exigences de départ. Toute progression doit tenir compte de votre mobilité, de votre douleur et de votre santé.", "body": "La surcharge peut apparaître comme une impatience, une tension, des oublis ou le sentiment de ne jamais s’arrêter. Une technique de détente ne remplace pas toujours une réduction de la charge.", "action": "repérez un signal précoce et une réponse concrète : déplacer une tâche, demander de l’aide ou protéger une pause-repas. Si votre plan de santé ajoute une nouvelle couche d’exigences à une vie déjà saturée, simplifiez-le. Le repos peut être l’action la plus pertinente du jour.", "question": "Quel geste de récupération serait réaliste aujourd’hui?", "sources": [{"id": "S27", "title": "Organisation mondiale de la Santé, 2020.", "url": "https://www.ncbi.nlm.nih.gov/books/NBK566046/"}, {"id": "S28", "title": "Société canadienne de physiologie de l’exercice, 2020.", "url": "https://csepguidelines.ca/guidelines/adults-18-64/"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('e9363371-3474-5237-95c9-c622c897253d','9a61d466-f75f-5fe2-8ce1-1285dd53ec95',139,'review','{"title": "Utiliser respiration et attention au présent", "objective": "renforcer votre capacité à vivre vos journées. Les repères de santé publique sont des directions à adapter, pas des exigences de départ. Toute progression doit tenir compte de votre mobilité, de votre douleur et de votre santé.", "body": "Certaines personnes trouvent ces pratiques utiles pour diminuer une tension. D’autres les apprécient peu ou ressentent davantage d’inconfort. Elles restent facultatives et ne sont pas des techniques directes pour « brûler du gras ».", "action": "pendant une minute, respirez confortablement sans forcer ni retenir votre souffle. Vous pouvez plutôt regarder autour de vous ou écouter des sons. Si l’exercice déclenche une gêne, arrêtez. Choisissez une activité apaisante adaptée à votre expérience.", "question": "Quel geste de récupération serait réaliste aujourd’hui?", "sources": [{"id": "S20", "title": "NCCIH, National Institutes of Health.", "url": "https://www.nccih.nih.gov/health/meditation-and-mindfulness-effectiveness-and-safety"}, {"id": "S27", "title": "Organisation mondiale de la Santé, 2020.", "url": "https://www.ncbi.nlm.nih.gov/books/NBK566046/"}, {"id": "S28", "title": "Société canadienne de physiologie de l’exercice, 2020.", "url": "https://csepguidelines.ca/guidelines/adults-18-64/"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('bc80dd46-2c2f-5e77-a45a-a52cf5bb53c8','9a61d466-f75f-5fe2-8ce1-1285dd53ec95',140,'review','{"title": "Planifier la récupération", "objective": "renforcer votre capacité à vivre vos journées. Les repères de santé publique sont des directions à adapter, pas des exigences de départ. Toute progression doit tenir compte de votre mobilité, de votre douleur et de votre santé.", "body": "La récupération soutient une démarche qui dure. Elle peut comprendre du sommeil, des journées d’activité légère, des moments sociaux ou moins de tâches. Un jour de repos n’est pas une dette sportive.", "action": "inscrivez un moment de récupération dans votre semaine aussi concrètement qu’un rendez-vous. Après une période de maladie ou de fatigue importante, reprenez progressivement. Si la fatigue reste inhabituelle ou persistante, faites-la évaluer plutôt que de la traiter uniquement avec davantage de discipline.", "question": "Quel geste de récupération serait réaliste aujourd’hui?", "sources": [{"id": "S27", "title": "Organisation mondiale de la Santé, 2020.", "url": "https://www.ncbi.nlm.nih.gov/books/NBK566046/"}, {"id": "S28", "title": "Société canadienne de physiologie de l’exercice, 2020.", "url": "https://csepguidelines.ca/guidelines/adults-18-64/"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('fa4b2162-5c57-5dd9-9a50-11e49eda6f9d','55fb1826-8b34-51ff-bb6e-8fa53d50c471',141,'review','{"title": "Formuler un objectif précis et réalisable", "objective": "continuer à ajuster votre démarche. Les programmes étudiés comprennent souvent un accompagnement prolongé et plusieurs composantes. Lire un manuel ne reproduit pas à lui seul cette intensité de soutien.", "body": "« Mieux manger » indique une direction, mais ne précise pas votre prochaine action. Un objectif utile décrit quoi faire, dans quelle situation et pendant quelle période d’essai.", "action": "écrivez « pendant les deux prochaines semaines, je prévois un dîner pour les jours où je travaille au bureau ». Ajoutez une solution de secours. Vérifiez que l’objectif correspond à un problème réel et qu’il est assez petit pour être essayé sans réorganiser toute votre vie.", "question": "Qu’est-ce que je souhaite conserver, simplifier ou ajuster?", "sources": [{"id": "S04", "title": "USPSTF, 2018.", "url": "https://www.uspreventiveservicestaskforce.org/uspstf/recommendation/obesity-in-adults-interventions"}, {"id": "S34", "title": "NIDDK, révision 2024.", "url": "https://www.niddk.nih.gov/health-information/weight-management/choosing-a-safe-successful-weight-loss-program"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('31bbf5f4-5635-5c9c-80a4-4abb019b682a','55fb1826-8b34-51ff-bb6e-8fa53d50c471',142,'review','{"title": "Distinguer comportement et résultat", "objective": "continuer à ajuster votre démarche. Les programmes étudiés comprennent souvent un accompagnement prolongé et plusieurs composantes. Lire un manuel ne reproduit pas à lui seul cette intensité de soutien.", "body": "Vous pouvez agir directement sur certaines actions ; le résultat pondéral dépend aussi d’éléments moins contrôlables. Garder les deux niveaux évite de considérer une semaine comme inutile lorsque la balance ne change pas.", "action": "associez à un objectif de résultat deux comportements et un indicateur de qualité de vie. Exemple : améliorer le confort de marche ; pratiquer régulièrement une activité adaptée ; organiser certains repas ; observer l’essoufflement. Faites réévaluer les symptômes inhabituels plutôt que de tout attribuer au poids.", "question": "Qu’est-ce que je souhaite conserver, simplifier ou ajuster?", "sources": [{"id": "S04", "title": "USPSTF, 2018.", "url": "https://www.uspreventiveservicestaskforce.org/uspstf/recommendation/obesity-in-adults-interventions"}, {"id": "S34", "title": "NIDDK, révision 2024.", "url": "https://www.niddk.nih.gov/health-information/weight-management/choosing-a-safe-successful-weight-loss-program"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('fa6d4bed-e6bc-56dd-b5a0-5d9b0f0cf12e','55fb1826-8b34-51ff-bb6e-8fa53d50c471',143,'review','{"title": "Utiliser la pesée comme information", "objective": "continuer à ajuster votre démarche. Les programmes étudiés comprennent souvent un accompagnement prolongé et plusieurs composantes. Lire un manuel ne reproduit pas à lui seul cette intensité de soutien.", "body": "La pesée peut aider certaines personnes et nuire à d’autres. Elle reste facultative dans ce manuel. Si vous l’utilisez, choisissez une fréquence supportable et des conditions comparables ; ne modifiez pas le plan à partir d’un seul chiffre.", "action": "décidez à l’avance comment vous utiliserez l’information, par exemple dans un bilan hebdomadaire. Si vous vous pesez plusieurs fois par jour, compensez après une hausse ou ressentez une forte détresse, interrompez cette pratique et demandez conseil.", "question": "Qu’est-ce que je souhaite conserver, simplifier ou ajuster?", "sources": [{"id": "S09", "title": "USDA, Nutrition Evidence Systematic Review.", "url": "https://nesr.usda.gov/what-relationship-between-use-diet-and-body-weight-self-monitoring-strategies-and-body-weight"}, {"id": "S32", "title": "CDC, 2023.", "url": "https://www.cdc.gov/healthy-weight-growth/losing-weight/keeping-it-off.html"}, {"id": "S04", "title": "USPSTF, 2018.", "url": "https://www.uspreventiveservicestaskforce.org/uspstf/recommendation/obesity-in-adults-interventions"}, {"id": "S34", "title": "NIDDK, révision 2024.", "url": "https://www.niddk.nih.gov/health-information/weight-management/choosing-a-safe-successful-weight-loss-program"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('9b07b25c-1981-51d3-b711-dff8e2fd9219','55fb1826-8b34-51ff-bb6e-8fa53d50c471',144,'review','{"title": "Comprendre les fluctuations quotidiennes", "objective": "continuer à ajuster votre démarche. Les programmes étudiés comprennent souvent un accompagnement prolongé et plusieurs composantes. Lire un manuel ne reproduit pas à lui seul cette intensité de soutien.", "body": "Le poids comprend la masse grasse, mais aussi l’eau, les tissus et le contenu digestif. Une variation rapide ne correspond pas automatiquement à une variation de graisse. Repas salé, transit, cycle menstruel ou activité inhabituelle peuvent compliquer l’interprétation.", "action": "regardez plusieurs mesures comparables plutôt que celle du lendemain d’un événement. Si vous avez peu de mesures, acceptez une plus grande incertitude. Une variation rapide inexpliquée, surtout avec gonflement ou essoufflement, mérite une évaluation médicale.", "question": "Qu’est-ce que je souhaite conserver, simplifier ou ajuster?", "sources": [{"id": "S37", "title": "Office on Women’s Health, U.S. Department of Health and Human Services.", "url": "https://womenshealth.gov/healthy-weight/weight-loss-and-women"}, {"id": "S04", "title": "USPSTF, 2018.", "url": "https://www.uspreventiveservicestaskforce.org/uspstf/recommendation/obesity-in-adults-interventions"}, {"id": "S34", "title": "NIDDK, révision 2024.", "url": "https://www.niddk.nih.gov/health-information/weight-management/choosing-a-safe-successful-weight-loss-program"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('56e87a83-006b-5499-b6ab-19c36506ef4b','55fb1826-8b34-51ff-bb6e-8fa53d50c471',145,'review','{"title": "Reconnaître les progrès non pondéraux", "objective": "continuer à ajuster votre démarche. Les programmes étudiés comprennent souvent un accompagnement prolongé et plusieurs composantes. Lire un manuel ne reproduit pas à lui seul cette intensité de soutien.", "body": "Les progrès peuvent être pratiques : moins de décisions épuisantes, une marche plus confortable, davantage de force ou moins de culpabilité. Les marqueurs médicaux sont à interpréter avec votre équipe de soins.", "action": "notez chaque semaine une amélioration précise, même petite. « J’ai mangé au restaurant sans sauter le repas suivant » peut être un progrès important. Évitez de remplacer une obsession du poids par une surveillance exhaustive de toutes les autres mesures.", "question": "Qu’est-ce que je souhaite conserver, simplifier ou ajuster?", "sources": [{"id": "S04", "title": "USPSTF, 2018.", "url": "https://www.uspreventiveservicestaskforce.org/uspstf/recommendation/obesity-in-adults-interventions"}, {"id": "S34", "title": "NIDDK, révision 2024.", "url": "https://www.niddk.nih.gov/health-information/weight-management/choosing-a-safe-successful-weight-loss-program"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('fd9207c6-a23e-5017-a003-8200f036f1be','55fb1826-8b34-51ff-bb6e-8fa53d50c471',146,'review','{"title": "Faire un bilan régulier", "objective": "continuer à ajuster votre démarche. Les programmes étudiés comprennent souvent un accompagnement prolongé et plusieurs composantes. Lire un manuel ne reproduit pas à lui seul cette intensité de soutien.", "body": "Un bilan sert à décider, pas à distribuer une note. Il doit être assez court pour rester faisable. Les chiffres ne racontent pas tout : la charge mentale et le plaisir font partie de l’évaluation.", "action": "répondez à quatre questions : qu’est-ce qui m’a aidé ? Qu’est-ce qui m’a coûté trop cher en effort ? Qu’est-ce qui a changé dans ma vie ? Quel ajustement unique vais-je essayer ? Gardez une trace brève pour voir l’évolution de votre stratégie.", "question": "Qu’est-ce que je souhaite conserver, simplifier ou ajuster?", "sources": [{"id": "S04", "title": "USPSTF, 2018.", "url": "https://www.uspreventiveservicestaskforce.org/uspstf/recommendation/obesity-in-adults-interventions"}, {"id": "S34", "title": "NIDDK, révision 2024.", "url": "https://www.niddk.nih.gov/health-information/weight-management/choosing-a-safe-successful-weight-loss-program"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('21f109b9-6442-5d18-a84d-ea8dc6951103','55fb1826-8b34-51ff-bb6e-8fa53d50c471',147,'review','{"title": "Comprendre ralentissements et plateaux", "objective": "continuer à ajuster votre démarche. Les programmes étudiés comprennent souvent un accompagnement prolongé et plusieurs composantes. Lire un manuel ne reproduit pas à lui seul cette intensité de soutien.", "body": "La perte de poids n’est généralement pas linéaire. Les besoins énergétiques et l’appétit évoluent, et les fluctuations peuvent masquer une tendance. Quelques jours stables ne suffisent pas à conclure qu’il faut manger moins.", "action": "examinez plusieurs semaines, la faisabilité du plan, le sommeil, les traitements et les mesures disponibles. Si le poids reste stable malgré une démarche régulière, demandez une réévaluation. Un plateau peut appeler une autre forme de soutien, pas seulement une restriction plus importante.", "question": "Qu’est-ce que je souhaite conserver, simplifier ou ajuster?", "sources": [{"id": "S01", "title": "Wharton et coll., CMAJ, 2020.", "url": "https://www.cmaj.ca/content/192/31/e875"}, {"id": "S34", "title": "NIDDK, révision 2024.", "url": "https://www.niddk.nih.gov/health-information/weight-management/choosing-a-safe-successful-weight-loss-program"}, {"id": "S04", "title": "USPSTF, 2018.", "url": "https://www.uspreventiveservicestaskforce.org/uspstf/recommendation/obesity-in-adults-interventions"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('92b6947f-7958-5cd5-b261-3093b33ac154','55fb1826-8b34-51ff-bb6e-8fa53d50c471',148,'review','{"title": "Ajuster à partir de plusieurs observations", "objective": "continuer à ajuster votre démarche. Les programmes étudiés comprennent souvent un accompagnement prolongé et plusieurs composantes. Lire un manuel ne reproduit pas à lui seul cette intensité de soutien.", "body": "Un ajustement doit répondre à une hypothèse précise. Réduire les portions, augmenter l’exercice et supprimer les collations en même temps empêche de comprendre ce qui aide et peut rendre le plan difficile.", "action": "choisissez un changement soutenable et une période d’observation. Si les repas sont déjà insuffisants ou la faim excessive, ne réduisez pas davantage : vérifiez l’adéquation du plan. Les médicaments et la chirurgie, lorsque indiqués, font partie des options de soins à discuter sans honte.", "question": "Qu’est-ce que je souhaite conserver, simplifier ou ajuster?", "sources": [{"id": "S33", "title": "Pedersen et coll., Obésité Canada, mise à jour 2025.", "url": "https://obesitycanada.ca/wp-content/uploads/2025/08/11-Canadian-Adult-Obesity-CPG-Pharmacotherapy-2025-update.pdf"}, {"id": "S38", "title": "NIDDK.", "url": "https://www.niddk.nih.gov/health-information/weight-management/adult-overweight-obesity/treatment"}, {"id": "S04", "title": "USPSTF, 2018.", "url": "https://www.uspreventiveservicestaskforce.org/uspstf/recommendation/obesity-in-adults-interventions"}, {"id": "S34", "title": "NIDDK, révision 2024.", "url": "https://www.niddk.nih.gov/health-information/weight-management/choosing-a-safe-successful-weight-loss-program"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('e0366b29-6cce-5264-b530-4b8ec47a8451','55fb1826-8b34-51ff-bb6e-8fa53d50c471',149,'review','{"title": "Préparer le retour après une interruption", "objective": "continuer à ajuster votre démarche. Les programmes étudiés comprennent souvent un accompagnement prolongé et plusieurs composantes. Lire un manuel ne reproduit pas à lui seul cette intensité de soutien.", "body": "Voyage, maladie, déménagement ou surcharge peuvent interrompre une routine. Une reprise efficace tient compte de la nouvelle situation. Elle ne suppose pas que votre ancien plan convient encore.", "action": "utilisez un plan en trois gestes : rétablir un repas facile, reprendre un mouvement tolérable, contacter une personne de soutien. Choisissez ensuite une seule habitude à reconstruire. Ne cherchez pas à rattraper les séances ou les repas « manqués » ; revenez à des soins ordinaires.", "question": "Qu’est-ce que je souhaite conserver, simplifier ou ajuster?", "sources": [{"id": "S04", "title": "USPSTF, 2018.", "url": "https://www.uspreventiveservicestaskforce.org/uspstf/recommendation/obesity-in-adults-interventions"}, {"id": "S34", "title": "NIDDK, révision 2024.", "url": "https://www.niddk.nih.gov/health-information/weight-management/choosing-a-safe-successful-weight-loss-program"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
insert into public.learning_documents(id,module_id,position,status,draft,published,published_revision) values('8ea4e620-2708-5b5a-a48e-9a7391a0ae2c','55fb1826-8b34-51ff-bb6e-8fa53d50c471',150,'review','{"title": "Construire une façon de vivre durable", "objective": "continuer à ajuster votre démarche. Les programmes étudiés comprennent souvent un accompagnement prolongé et plusieurs composantes. Lire un manuel ne reproduit pas à lui seul cette intensité de soutien.", "body": "Le maintien est une phase active d’adaptation. Il peut nécessiter un suivi, des traitements et des ajustements pendant longtemps. Une reprise de poids ne prouve pas un défaut moral ni l’inutilité des efforts.", "action": "rédigez votre plan personnel : mes habitudes utiles ; mes signes précoces de difficulté ; mes solutions minimales ; les personnes à contacter. Révisez-le lorsque votre vie change. Le but est une capacité à revenir et à demander de l’aide, pas une vie sans fluctuations.", "question": "Qu’est-ce que je souhaite conserver, simplifier ou ajuster?", "sources": [{"id": "S32", "title": "CDC, 2023.", "url": "https://www.cdc.gov/healthy-weight-growth/losing-weight/keeping-it-off.html"}, {"id": "S33", "title": "Pedersen et coll., Obésité Canada, mise à jour 2025.", "url": "https://obesitycanada.ca/wp-content/uploads/2025/08/11-Canadian-Adult-Obesity-CPG-Pharmacotherapy-2025-update.pdf"}, {"id": "S04", "title": "USPSTF, 2018.", "url": "https://www.uspreventiveservicestaskforce.org/uspstf/recommendation/obesity-in-adults-interventions"}, {"id": "S34", "title": "NIDDK, révision 2024.", "url": "https://www.niddk.nih.gov/health-information/weight-management/choosing-a-safe-successful-weight-loss-program"}], "limits": "Information éducative générale. Les sources ne valident pas l’efficacité de ce parcours ni chaque exercice. Adapter aux contraintes de la personne; aucune prescription, aucun diagnostic ni résultat garanti. Révision professionnelle à prévoir pour les sujets de santé.", "adaptations": "Adapter les exemples, la longueur, la question et le petit essai au contexte déclaré. Conserver le concept, les faits sourcés et les limites; ne jamais interpréter un symptôme ni imposer une cible de poids ou de calories.", "reviewedOn": "2026-10-21"}'::jsonb,null,null) on conflict do nothing;
